export type McpAccessibilityConfig = {
  enabled: boolean;
  maxTextChars: number;
  collapseThreshold: number;
  collapseKeepHead: number;
  collapseKeepTail: number;
  minLengthToProcess: number;
};

export const DEFAULT_MCP_ACCESSIBILITY_CONFIG: McpAccessibilityConfig = {
  enabled: true,
