  collapseThreshold: MCP_ACCESSIBILITY_DEFAULTS.collapseThreshold,
  collapseKeepHead: MCP_ACCESSIBILITY_DEFAULTS.collapseKeepHead,
  collapseKeepTail: MCP_ACCESSIBILITY_DEFAULTS.collapseKeepTail,
  minLengthToProcess: MCP_ACCESSIBILITY_DEFAULTS.minLengthToProcess,
};

/**
 * Chars `smartFilterText` reserves for the truncation tail/notice (`maxTextChars - this` is the
 * head kept). A `maxTextChars` at or below this leaves no head, so the whole tool result would be
 * replaced by the notice. The engine and the config bounds must agree on this number.
 */
export const MCP_ACCESSIBILITY_TAIL_RESERVE = 300;

/**
 * Minimum sane `maxTextChars`: below this the truncated head is too small to be useful (or empty).
 * Values in `(0, MIN)` are treated as misconfiguration and fall back to the default.
 */
export const MCP_ACCESSIBILITY_MIN_MAX_TEXT_CHARS = MCP_ACCESSIBILITY_TAIL_RESERVE * 2;

function boundedInt(value: unknown, min: number, fallback: number): number {
  return typeof value === "number" && Number.isFinite(value) && value >= min
    ? Math.floor(value)
    : fallback;
}

/**
 * Bound a raw/persisted mcpAccessibility config into a safe, fully-populated config. Centralizes
 * the numeric floors so both the DB normalizer and the live MCP-server read path agree (a small
 * `maxTextChars` would otherwise make `smartFilterText` truncate the whole text away).
 */
export function clampMcpAccessibilityConfig(raw: unknown): McpAccessibilityConfig {
  const record = (raw && typeof raw === "object" ? raw : {}) as Record<string, unknown>;
  const d = DEFAULT_MCP_ACCESSIBILITY_CONFIG;
  return {
    enabled: record["enabled"] !== false,
    maxTextChars: boundedInt(record["maxTextChars"], MCP_ACCESSIBILITY_MIN_MAX_TEXT_CHARS, d.maxTextChars),
    collapseThreshold: boundedInt(record["collapseThreshold"], 1, d.collapseThreshold),
    collapseKeepHead: boundedInt(record["collapseKeepHead"], 0, d.collapseKeepHead),
    collapseKeepTail: boundedInt(record["collapseKeepTail"], 0, d.collapseKeepTail),
    minLengthToProcess: boundedInt(record["minLengthToProcess"], 1, d.minLengthToProcess),
  };
}

import { extractTextContent } from "./messageContent.ts";
import { checkFidelity, type FidelityGateConfig } from "./fidelityGate.ts";
import type { CompressionResult } from "./types.ts";
import type { StackAccumulator } from "./stackedStepCore.ts";
import { getCompressionEngine } from "./engines/registry.ts";

function bodyToText(body: Record<string, unknown>): string {
  const messages = body.messages;
  if (!Array.isArray(messages)) return "";
  return messages
    .map((m) => extractTextContent((m as { content?: unknown }).content as never))
    .join("\n");
}

/**
 * Fidelity gate (opt-in, independent of TV1). Called at each advance point AFTER mergeStackStep
 * pushed the step's breakdown entry. Off → zero-cost `return true` (byte-identical legacy). On a
 * fidelity failure it marks the just-pushed breakdown entry rejected (no advance) and returns false.
 */
export function gateAdvance(
  result: CompressionResult,
  inputBody: Record<string, unknown>,
  fidelityGate: FidelityGateConfig | undefined,
  acc: StackAccumulator,
  engineId?: string
): boolean {
  if (!fidelityGate?.enabled) return true;
  if (engineId && getCompressionEngine(engineId)?.sampling) return true; // lossy-by-design, CCR-recoverable
  const verdict = checkFidelity(bodyToText(inputBody), bodyToText(result.body), fidelityGate);
  if (verdict.passed) return true;
  // mergeStackStep only pushed a breakdown entry when result.stats exists; only then is
  // acc.breakdown's last entry THIS step's (else it would be the prior engine's — don't touch it).
  if (result.stats) {
    const last = acc.breakdown[acc.breakdown.length - 1];
    if (last) {
      last.rejected = true;
      last.rejectReason = verdict.detail ?? verdict.failedInvariant;
      last.compressedTokens = last.originalTokens;
      last.savingsPercent = 0;
    }
  }
  acc.fallbackApplied = true;
  return false;
}

export interface TextBlock {
  type?: string;
  text?: string;
  [key: string]: unknown;
}

export interface ChatMessageLike {
  role: string;
  content?: string | TextBlock[] | unknown[];
  [key: string]: unknown;
}

export function isTextBlock(value: unknown): value is TextBlock {
  return (
    !!value &&
    typeof value === "object" &&
    "text" in value &&
    typeof (value as TextBlock).text === "string" &&
    ((value as TextBlock).type === undefined ||
      (value as TextBlock).type === "text" ||
      (value as TextBlock).type === "input_text")
  );
}

export function extractTextContent(content: ChatMessageLike["content"]): string {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";

  const textParts: string[] = [];
  for (const part of content) {
    if (isTextBlock(part) && part.text) {
      textParts.push(part.text);
    }
  }
  return textParts.join("\n");
}

export function mapTextContent(
  msg: ChatMessageLike,
  transform: (text: string, index: number) => string
): ChatMessageLike {
  if (typeof msg.content === "string") {
    return { ...msg, content: transform(msg.content, 0) };
  }
  if (!Array.isArray(msg.content)) return msg;

  let textIndex = 0;
  let changed = false;
  const content = msg.content.map((part) => {
    if (!isTextBlock(part)) return part;
    const nextText = transform(part.text ?? "", textIndex);
    textIndex++;
    if (nextText === part.text) return part;
    changed = true;
    return { ...part, text: nextText };
  });

  return changed ? { ...msg, content } : msg;
}

export function replaceTextContent(msg: ChatMessageLike, newText: string): ChatMessageLike {
  if (typeof msg.content === "string" || !Array.isArray(msg.content)) {
    return { ...msg, content: newText };
  }

  // The first text block receives `newText`. Trailing text blocks are normally
  // already subsumed by `newText` (callers build it from the JOIN of all text
  // blocks via extractTextContent), so we drop them to avoid duplicating content.
  // But if a caller's `newText` does NOT contain a trailing block's text, dropping
  // it would silently lose content the model can no longer see (B-AGG-TEXTDROP) —
  // so in that case we keep the trailing block instead of returning [].
  let replaced = false;
  const content = msg.content.flatMap((part) => {
    if (!isTextBlock(part)) return [part];
    if (!replaced) {
      replaced = true;
      return [{ ...part, text: newText }];
    }
    const partText = part.text ?? "";
    if (partText && !newText.includes(partText)) return [part];
    return [];
  });

  if (!replaced) {
    return { ...msg, content: [{ type: "text", text: newText }, ...msg.content] };
  }

  return { ...msg, content };
}

import { extractPreservedBlocks } from "./preservation.ts";

export interface FidelityGateConfig {
  enabled: boolean;
  /** % of input protected tokens that must survive. Default 95. */
  minTokenSurvivalPercent?: number;
  /** % of input JSON keys that must survive. Default 90. */
  minJsonKeyPercent?: number;
  /** Require every input number literal to appear in the output. Default true. */
  checkNumericIntegrity?: boolean;
  /** Require every input @@…@@ hunk header to appear in the output. Default true. */
  checkDiffHunks?: boolean;
}

export type FidelityInvariant = "protected-tokens" | "numeric" | "json-keys" | "diff-hunks";

export interface FidelityResult {
  passed: boolean;
  failedInvariant?: FidelityInvariant;
  detail?: string;
}

const CRITICAL_KINDS = new Set([
  "url",
  "const_case",
  "env_var",
  "version",
  "dotted_identifier",
  "function_call",
  "file_path",
  "inline_code",
]);

// Anti-ReDoS: all quantifiers are bounded.
// NUMERIC_RE matches a number plus any trailing run of digits/dots/commas (e.g. "1,3" in a diff
// hunk, "1," in JSON). This is intentional: comparing the same literal slice in input vs output
// keeps the check structural-aware and ReDoS-bounded ({0,40}).
const NUMERIC_RE = /\d[\d.,]{0,40}/g;
const JSON_KEY_RE = /"([A-Za-z_$][\w$-]{0,80})"\s*:/g;
const HUNK_RE = /@@ -\d{1,9}(?:,\d{1,9})? \+\d{1,9}(?:,\d{1,9})? @@/g;

function survivalRatio(needles: string[], haystack: string): number {
  if (needles.length === 0) return 1;
  let survived = 0;
  for (const n of needles) if (haystack.includes(n)) survived++;
  return survived / needles.length;
}

function uniq(values: Iterable<string>): string[] {
  return Array.from(new Set(values));
}

/**
 * Deterministic per-step fidelity check. Returns {passed:false, failedInvariant, detail}
 * on the FIRST failing invariant (cheap→expensive order), else {passed:true}.
 * FAIL-OPEN: any internal error → {passed:true} (a verifier bug must never block compression).
 */
export function checkFidelity(
  inputText: string,
  outputText: string,
  cfg: FidelityGateConfig
): FidelityResult {
  try {
    const tokens = uniq(
      extractPreservedBlocks(inputText)
        .blocks.filter((b) => CRITICAL_KINDS.has(b.kind))
        .map((b) => b.content.trim())
        .filter((c) => c.length > 0)
    );
    const minTok = (cfg.minTokenSurvivalPercent ?? 95) / 100;
    const tokRatio = survivalRatio(tokens, outputText);
    if (tokRatio < minTok) {
      return {
        passed: false,
        failedInvariant: "protected-tokens",
        detail: `tokens protegidos ${Math.round(tokRatio * 100)}% < ${Math.round(minTok * 100)}%`,
      };
    }

    if (cfg.checkDiffHunks !== false) {
      for (const h of uniq(inputText.match(HUNK_RE) ?? [])) {
        if (!outputText.includes(h)) {
          return {
            passed: false,
            failedInvariant: "diff-hunks",
            detail: `hunk "${h}" ausente no output`,
          };
        }
      }
    }

    if (cfg.checkNumericIntegrity !== false) {
      for (const num of uniq(inputText.match(NUMERIC_RE) ?? [])) {
        if (!outputText.includes(num)) {
          return {
            passed: false,
            failedInvariant: "numeric",
            detail: `número "${num}" ausente no output`,
          };
        }
      }
    }

    const keys = uniq(Array.from(inputText.matchAll(JSON_KEY_RE), (m) => m[1]));
    if (keys.length > 0) {
      const minKey = (cfg.minJsonKeyPercent ?? 90) / 100;
      const keyRatio = survivalRatio(
        keys.map((k) => `"${k}"`),
        outputText
      );
      if (keyRatio < minKey) {
        return {
          passed: false,
          failedInvariant: "json-keys",
          detail: `chaves JSON ${Math.round(keyRatio * 100)}% < ${Math.round(minKey * 100)}%`,
        };
      }
    }

    return { passed: true };
  } catch {
    return { passed: true };
  }
}

export interface PreservedBlock {
  placeholder: string;
  content: string;
  kind: string;
}

export interface PreservationOptions {
  preservePatterns?: Array<string | RegExp>;
}

interface CompiledPattern {
  pattern: RegExp;
  kind: string;
}

const SENTINEL_PREFIX = "\u0000OMNI_CAVEMAN";

function randomSentinelSeed(): string {
  const bytes = new Uint8Array(8);
  const cryptoLike = globalThis.crypto;
  if (cryptoLike?.getRandomValues) {
    cryptoLike.getRandomValues(bytes);
    return `r${Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("")}`;
  }
  return `r${Math.random().toString(36).slice(2)}`;
}

function ensureGlobal(pattern: RegExp): RegExp {
  const flags = pattern.flags.includes("g") ? pattern.flags : `${pattern.flags}g`;
  return new RegExp(pattern.source, flags);
}

function compileUserPatterns(patterns: Array<string | RegExp> | undefined): CompiledPattern[] {
  if (!patterns?.length) return [];
  const compiled: CompiledPattern[] = [];
  for (const pattern of patterns) {
    try {
      compiled.push({
        pattern: typeof pattern === "string" ? new RegExp(pattern, "g") : ensureGlobal(pattern),
        kind: "custom",
      });
    } catch {
      // Invalid user regexes are ignored by the hot path. Validation/preview exposes warnings.
    }
  }
  return compiled;
}

function replacePattern(
  text: string,
  pattern: RegExp,
  kind: string,
  addBlock: (content: string, kind: string) => string
): string {
  pattern.lastIndex = 0;
  return text.replace(pattern, (match) => {
    if (!match) return match;
    if (match.includes(SENTINEL_PREFIX)) return match;
    return addBlock(match, kind);
  });
}

export function findFencedCodeBlocks(text: string): string[] {
  const blocks: string[] = [];
  extractFencedCodeBlocks(text, (content) => {
    blocks.push(content);
    return content;
  });
  return blocks;
}

export function extractPreservedBlocks(
  text: string,
  options: PreservationOptions = {}
): { text: string; blocks: PreservedBlock[] } {
  const blocks: PreservedBlock[] = [];
  const seed = randomSentinelSeed();
  let counter = 0;

  const addBlock = (content: string, kind: string): string => {
    const placeholder = `${SENTINEL_PREFIX}_${seed}_${counter}\u0000`;
    blocks.push({ placeholder, content, kind });
    counter++;
    return placeholder;
  };

  let result = text;

  result = extractFrontmatter(result, addBlock);
  result = extractFencedCodeBlocks(result, (content) => addBlock(content, "fenced_code"));

  const builtIns: CompiledPattern[] = [
    { pattern: /\$\$[\s\S]*?\$\$/g, kind: "math_block" },
    { pattern: /\\\[[\s\S]*?\\\]/g, kind: "math_block" },
    // #4795: exclude `\` from the catch-all branch so a backslash is only ever
    // consumed by the escape branch `\\.`. The previous `[^$\n]` overlapped with
    // `\\.`, making a run of consecutive backslashes (e.g. unmatched `$` + a
    // Windows path) exponentially ambiguous → catastrophic backtracking (ReDoS).
    {
      pattern: /(?<!\$)\$(?![\s$\d])(?:\\.|[^$\n\\]){1,160}?(?<!\s)\$(?!\$)/g,
      kind: "math_inline",
    },
    { pattern: /\\begin\{[A-Za-z*]+\}[\s\S]*?\\end\{[A-Za-z*]+\}/g, kind: "latex_block" },
    { pattern: /^#{1,6}\s+.+$/gm, kind: "markdown_heading" },
    { pattern: /^\s*\|.*\|\s*$/gm, kind: "markdown_table" },
    { pattern: /^\s*\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)+\|?\s*$/gm, kind: "markdown_table" },
    { pattern: /^\s*#(?:set|show|let|import|include)\b.+$/gm, kind: "typst_directive" },
    { pattern: /`[^`\n]+`/g, kind: "inline_code" },
    { pattern: /\[[^\]\n]+\]\([^) \n]+(?:\s+"[^"]*")?\)/g, kind: "markdown_link" },
    { pattern: /\bhttps?:\/\/[^\s)\]"'>]+/gi, kind: "url" },
    { pattern: /\b[A-Z][A-Z0-9]*(?:_[A-Z0-9]+)+\b/g, kind: "const_case" },
    { pattern: /\bprocess\.env\.[A-Za-z_][A-Za-z0-9_]*\b/g, kind: "env_var" },
    { pattern: /\$[A-Z_][A-Z0-9_]*\b/g, kind: "env_var" },
    { pattern: /\b\d+(?:\.\d+){1,3}(?:[-+][A-Za-z0-9.-]+)?\b/g, kind: "version" },
    { pattern: /\b[a-zA-Z_$][\w$]*(?:\.[a-zA-Z_$][\w$]*)+\(\)?/g, kind: "dotted_identifier" },
    { pattern: /\b[A-Za-z_$][\w$]*\s*\([^()\n]*\)/g, kind: "function_call" },
    {
      pattern: /(?:^|\s)(?:\.{0,2}\/[A-Za-z0-9_@./-]+|[A-Za-z]:\\[A-Za-z0-9_.\\/-]+)/g,
      kind: "file_path",
    },
    {
      pattern:
        /\b(?:TypeError|ReferenceError|SyntaxError|RangeError|URIError|EvalError|Error|Exception):[^\n]+/g,
      kind: "error_message",
    },
  ];

  for (const { pattern, kind } of [...builtIns, ...compileUserPatterns(options.preservePatterns)]) {
    result = replacePattern(result, ensureGlobal(pattern), kind, addBlock);
  }

  return { text: result, blocks };
}

/**
 * Wrap explicit literal spans (by offset) into SENTINEL placeholders, reusing
 * the exact placeholder family that every engine already treats as opaque.
 * Spans must be non-overlapping and pre-sorted ascending. Restored via
 * `restorePreservedBlocks`.
 */
export function preserveSpans(
  text: string,
  spans: Array<{ start: number; end: number; kind: string }>
): { text: string; blocks: PreservedBlock[] } {
  if (!spans.length) return { text, blocks: [] };
  const seed = randomSentinelSeed();
  const blocks: PreservedBlock[] = [];
  let result = "";
  let cursor = 0;
  let counter = 0;
  for (const span of spans) {
    if (span.start < cursor || span.end > text.length || span.start >= span.end) continue;
    const placeholder = `${SENTINEL_PREFIX}_${seed}_${counter}\u0000`;
    blocks.push({ placeholder, content: text.slice(span.start, span.end), kind: span.kind });
    result += text.slice(cursor, span.start) + placeholder;
    cursor = span.end;
    counter++;
  }
  result += text.slice(cursor);
  return { text: result, blocks };
}

function extractFrontmatter(
  text: string,
  addBlock: (content: string, kind: string) => string
): string {
  if (!text.startsWith("---\n")) return text;
  const close = text.indexOf("\n---", 4);
  if (close === -1) return text;
  const closeEnd = text.indexOf("\n", close + 4);
  const end = closeEnd === -1 ? text.length : closeEnd + 1;
  return `${addBlock(text.slice(0, end), "frontmatter")}${text.slice(end)}`;
}

function extractFencedCodeBlocks(text: string, addBlock: (content: string) => string): string {
  const lines = text.match(/[^\n]*(?:\n|$)/g) ?? [text];
  let output = "";
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];
    if (line === "" && i === lines.length - 1) break;
    const opening = line.match(/^([ \t]{0,3})(`{3,}|~{3,})[^\n]*(?:\n|$)/);
    if (!opening) {
      output += line;
      i++;
      continue;
    }

    const fence = opening[2];
    const fenceChar = fence[0];
    const minLen = fence.length;
    let block = line;
    let j = i + 1;
    let closed = false;

    while (j < lines.length) {
      const candidate = lines[j];
      block += candidate;
      const closeMatch = candidate.match(/^([ \t]{0,3})(`{3,}|~{3,})\s*(?:\n|$)/);
      if (closeMatch && closeMatch[2][0] === fenceChar && closeMatch[2].length >= minLen) {
        closed = true;
        break;
      }
      j++;
    }

    if (!closed) {
      output += line;
      i++;
      continue;
    }

    output += addBlock(block);
    i = j + 1;
  }

  return output;
}

export function restorePreservedBlocks(text: string, blocks: PreservedBlock[]): string {
  let result = text;
  for (const block of blocks) {
    result = result.split(block.placeholder).join(block.content);
  }
  return result;
}

export function shouldPreserve(text: string, preservePatterns: RegExp[]): boolean {
  return preservePatterns.some((pattern) => {
    pattern.lastIndex = 0;
    return pattern.test(text);
  });
}

import type { CompressionEngine, EngineRegistryEntry, EngineValidationResult } from "./types.ts";

const ENGINES = new Map<string, EngineRegistryEntry>();

function assertValidEngine(engine: CompressionEngine): void {
  if (
    !engine?.id ||
    typeof engine.apply !== "function" ||
    typeof engine.compress !== "function" ||
    typeof engine.getConfigSchema !== "function" ||
    typeof engine.validateConfig !== "function"
  ) {
    throw new Error("Invalid compression engine registration");
  }
}

export function registerEngine(
  engine: CompressionEngine,
  defaultConfig: Record<string, unknown> = {}
): void {
  assertValidEngine(engine);
  const validation = engine.validateConfig(defaultConfig);
  if (!validation.valid) {
    throw new Error(`Invalid default config for ${engine.id}: ${validation.errors.join("; ")}`);
  }
  ENGINES.set(engine.id, {
    engine,
    enabled: true,
    config: { ...defaultConfig },
  });
}

export function registerCompressionEngine(engine: CompressionEngine): void {
  registerEngine(engine);
}

export function unregisterCompressionEngine(id: string): boolean {
  return ENGINES.delete(id);
}

export function getEngine(id: string): CompressionEngine | null {
  return ENGINES.get(id)?.engine ?? null;
}

export function getCompressionEngine(id: string): CompressionEngine | null {
  return getEngine(id);
}

export function getEngineEntry(id: string): EngineRegistryEntry | null {
  return ENGINES.get(id) ?? null;
}

export function listEngines(): EngineRegistryEntry[] {
  return Array.from(ENGINES.values());
}

export function listCompressionEngines(): CompressionEngine[] {
  return listEngines().map((entry) => entry.engine);
}

export function listEnabledEngines(): EngineRegistryEntry[] {
  return listEngines().filter((entry) => entry.enabled);
}

export function setEngineEnabled(id: string, enabled: boolean): boolean {
  const entry = ENGINES.get(id);
  if (!entry) return false;
  entry.enabled = enabled;
  return true;
}

export function updateEngineConfig(
  id: string,
  config: Record<string, unknown>
): EngineValidationResult {
  const entry = ENGINES.get(id);
  if (!entry) return { valid: false, errors: [`Unknown compression engine: ${id}`] };
  const nextConfig = { ...entry.config, ...config };
  const validation = entry.engine.validateConfig(nextConfig);
  if (!validation.valid) return validation;
  entry.config = nextConfig;
  return { valid: true, errors: [] };
}

export function clearCompressionEngineRegistry(): void {
  ENGINES.clear();
}

import { isVisionModelId } from "@/shared/constants/visionModels";
import type { CompressionResult, CompressionMode } from "./types.ts";
import { createCompressionStats } from "./stats.ts";

interface Message {
  role: string;
  content: string | Array<Record<string, unknown>>;
  [key: string]: unknown;
}

interface ChatBody {
  messages?: Message[];
  [key: string]: unknown;
}

interface LiteCompressionOptions {
  model?: string;
  supportsVision?: boolean | null;
  preserveSystemPrompt?: boolean;
}

function trimTrailingHorizontalWhitespace(line: string): string {
  let end = line.length;
  while (end > 0) {
    const code = line.charCodeAt(end - 1);
    if (code !== 32 && code !== 9) break;
    end--;
  }
  return end === line.length ? line : line.slice(0, end);
}

function collapseNewlineRuns(content: string): string {
  let normalized = "";
  let newlineRun = 0;

  for (const char of content) {
    if (char === "\n") {
      newlineRun++;
      if (newlineRun <= 2) {
        normalized += char;
      }
      continue;
    }

    newlineRun = 0;
    normalized += char;
  }

  return normalized;
}

function normalizeMessageWhitespace(content: string): string {
  return collapseNewlineRuns(content).split("\n").map(trimTrailingHorizontalWhitespace).join("\n");
}

// Vision detection is centralized in `@/shared/constants/visionModels` (#4072) so
// the lite image-strip gate, the /v1/models listing, and the routing fallback can
// never disagree. The shared list keeps the #3328 MiniMax M3 carve-out and the
// pixtral/llava/qwen-vl/glm-4v/kimi-vl/mistral-medium-3 families this gate used to
// miss (stripping their images and blinding real vision models).
function modelSupportsVision(model: string): boolean {
  return isVisionModelId(model);
}

export function collapseWhitespace(
  body: ChatBody,
  options: LiteCompressionOptions = {}
): {
  body: ChatBody;
  applied: boolean;
} {
  if (!body.messages) return { body, applied: false };
  let applied = false;
  const messages = body.messages.map((msg) => {
    if (options.preserveSystemPrompt === true && msg.role === "system") return msg;
    if (typeof msg.content !== "string") return msg;
    const normalized = normalizeMessageWhitespace(msg.content);
    if (normalized !== msg.content) applied = true;
    return { ...msg, content: normalized };
  });
  return { body: { ...body, messages }, applied };
}

export function dedupSystemPrompt(
  body: ChatBody,
  options: LiteCompressionOptions = {}
): {
  body: ChatBody;
  applied: boolean;
} {
  if (!body.messages) return { body, applied: false };
  if (options.preserveSystemPrompt === true) return { body, applied: false };
  const seen = new Set<string>();
  let applied = false;
  const messages = body.messages.filter((msg) => {
    if (msg.role !== "system" || typeof msg.content !== "string") return true;
    const key = msg.content.trim().slice(0, 200);
    if (seen.has(key)) {
      applied = true;
      return false;
    }
    seen.add(key);
    return true;
  });
  return { body: { ...body, messages }, applied };
}

// Adjust a hard cut index to the nearest whitespace within a small lookback/lookahead
// window, so a truncated tool result never garbles the word it lands in the middle of
// (#8169). Prefers backing off to the end of the previous word (keeps the result at or
// under the limit); if no whitespace precedes the cut within the window (e.g. the tail
// end of a very long unbroken run), looks forward to complete the current word instead.
// Falls back to the original hard cut index when neither direction finds a boundary.
const TOOL_TRUNCATION_LOOKBACK = 80;

function isWordChar(char: string | undefined): boolean {
  return char !== undefined && /\S/.test(char);
}

function findWhitespaceBackward(content: string, cutIndex: number): number {
  const windowStart = Math.max(0, cutIndex - TOOL_TRUNCATION_LOOKBACK);
  for (let i = cutIndex; i > windowStart; i--) {
    if (!isWordChar(content[i - 1])) return i - 1;
  }
  return -1;
}

function findWhitespaceForward(content: string, cutIndex: number): number {
  const windowEnd = Math.min(content.length, cutIndex + TOOL_TRUNCATION_LOOKBACK);
  for (let i = cutIndex; i < windowEnd; i++) {
    if (!isWordChar(content[i])) return i;
  }
  return -1;
}

function backOffToWordBoundary(content: string, cutIndex: number): number {
  const onWordBoundary = !isWordChar(content[cutIndex - 1]) || !isWordChar(content[cutIndex]);
  if (onWordBoundary) return cutIndex;

  const backward = findWhitespaceBackward(content, cutIndex);
  if (backward !== -1) return backward;

  const forward = findWhitespaceForward(content, cutIndex);
  if (forward !== -1) return forward;

  return cutIndex;
}

export function compressToolResults(body: ChatBody): {
  body: ChatBody;
  applied: boolean;
} {
  if (!body.messages) return { body, applied: false };
  const MAX_TOOL_LENGTH = 2000;
  let applied = false;
  const messages = body.messages.map((msg) => {
    if (msg.role !== "tool" || typeof msg.content !== "string") return msg;
    if (msg.content.length <= MAX_TOOL_LENGTH) return msg;
    applied = true;
    const cutIndex = backOffToWordBoundary(msg.content, MAX_TOOL_LENGTH);
    return {
      ...msg,
      content: msg.content.slice(0, cutIndex) + "\n...[truncated]",
    };
  });
  return { body: { ...body, messages }, applied };
}

export function removeRedundantContent(
  body: ChatBody,
  options: LiteCompressionOptions = {}
): {
  body: ChatBody;
  applied: boolean;
} {
  if (!body.messages) return { body, applied: false };
  let applied = false;
  const messages: Message[] = [];
  for (let i = 0; i < body.messages.length; i++) {
    const msg = body.messages[i];
    if (options.preserveSystemPrompt === true && msg.role === "system") {
      messages.push(msg);
      continue;
    }
    const contentStr = typeof msg.content === "string" ? msg.content : JSON.stringify(msg.content);
    if (
      i > 0 &&
      body.messages[i - 1].role === msg.role &&
      typeof body.messages[i - 1].content === "string" &&
      body.messages[i - 1].content === contentStr
    ) {
      applied = true;
      continue;
    }
    messages.push(msg);
  }
  return { body: { ...body, messages }, applied };
}

export function replaceImageUrls(
  body: ChatBody,
  options?: LiteCompressionOptions | string
): { body: ChatBody; applied: boolean } {
  if (!body.messages) return { body, applied: false };
  const supportsVision =
    typeof options === "object" && options !== null
      ? options.supportsVision
      : typeof options === "string"
        ? modelSupportsVision(options)
        : undefined;
  if (supportsVision !== false) return { body, applied: false };

  let applied = false;
  const messages = body.messages.map((msg) => {
    if (!Array.isArray(msg.content)) return msg;
    const newContent = msg.content.map((part) => {
      if (
        typeof part === "object" &&
        part !== null &&
        part.type === "image_url" &&
        typeof (part as Record<string, unknown>).image_url === "object" &&
        ((part as Record<string, unknown>).image_url as Record<string, unknown>)?.url
      ) {
        const url = String(
          ((part as Record<string, unknown>).image_url as Record<string, unknown>).url
        );
        if (url.startsWith("data:image/")) {
          applied = true;
          const format = url.slice(url.indexOf("/") + 1, url.indexOf(";")) || "unknown";
          return { type: "text", text: `[image: ${format}]` };
        }
      }
      return part;
    });
    return { ...msg, content: newContent };
  });
  return { body: { ...body, messages }, applied };
}

export function applyLiteCompression(
  body: Record<string, unknown>,
  options?: LiteCompressionOptions
): CompressionResult {
  const originalBody = body;
  let current = body as ChatBody;
  const techniquesApplied: string[] = [];

  const r1 = collapseWhitespace(current, options);
  current = r1.body;
  if (r1.applied) techniquesApplied.push("whitespace");

  const r2 = dedupSystemPrompt(current, options);
  current = r2.body;
  if (r2.applied) techniquesApplied.push("system-dedup");

  const r3 = compressToolResults(current);
  current = r3.body;
  if (r3.applied) techniquesApplied.push("tool-compress");

  const r4 = removeRedundantContent(current, options);
  current = r4.body;
  if (r4.applied) techniquesApplied.push("redundant-remove");

  const r5 = replaceImageUrls(current, options);
  current = r5.body;
  if (r5.applied) techniquesApplied.push("image-placeholder");

  const compressed = techniquesApplied.length > 0;
  const stats = compressed
    ? createCompressionStats(
        originalBody,
        current as Record<string, unknown>,
        "lite" as CompressionMode,
        techniquesApplied
      )
    : null;

  return {
    body: current as Record<string, unknown>,
    compressed,
    stats,
  };
}

