      const map: Record<string, string> = {
        "is being used": "uses",
        "is being called": "calls",
        "is being generated": "generated",
        "was created": "created",
        "was generated": "generated",
        "was implemented": "implemented",
      };
      return map[match.toLowerCase()] ?? match;
    },
    context: "all",
    category: "structural",
    minIntensity: "full",
  },

  // ── Category 4: Multi-Turn Dedup (5+ rules) ─────────────────────────

  {
    name: "repeated_context",
    pattern:
      /\b(?:As we discussed earlier|As mentioned before|As previously stated|As I said before)\b[,.]?\s*/gi,
    replacement: "See above. ",
    context: "all",
    category: "dedup",
    minIntensity: "lite",
  },
  {
    name: "repeated_question",
    pattern:
      /\b(?:Same question as before|I asked this earlier|This is the same question)\b[,.]?\s*/gi,
    replacement: "[same question] ",
    context: "user",
    category: "dedup",
    minIntensity: "lite",
  },
  {
    name: "reestablished_context",
    pattern: /\b(?:Going back to the code above|Referring back to|Returning to)\b\s*/gi,
    replacement: "Re: ",
    context: "all",
    category: "dedup",
    minIntensity: "lite",
  },
  {
    name: "summary_replacement",
    pattern:
      /\b(?:To summarize what we've discussed|In summary of our conversation|To recap)\b[,.]?\s*/gi,
    replacement: "Summary: ",
    context: "assistant",
    category: "dedup",
    minIntensity: "lite",
  },

  // ── Category 5: Ultra Abbreviations ─────────────────────────────────

  {
    name: "ultra_abbreviations",
    pattern:
      /\b(?:database|configuration|function|request|response|implementation|authentication|authorization|application|dependency|dependencies)\b/gi,
    replacement: (match: string): string => {
      const map: Record<string, string> = {
        database: "DB",
        configuration: "config",
        function: "fn",
        request: "req",
        response: "res",
        implementation: "impl",
        authentication: "auth",
        authorization: "authz",
        application: "app",
        dependency: "dep",
        dependencies: "deps",
      };
      return map[match.toLowerCase()] ?? match;
    },
    context: "all",
    category: "ultra",
    minIntensity: "ultra",
  },
];

const INTENSITY_RANK = { lite: 0, full: 1, ultra: 2 } as const;

export function getRulesForContext(
  context: string,
  intensity: "lite" | "full" | "ultra" = "full",
  language = "en"
): CavemanRule[] {
  const rank = INTENSITY_RANK[intensity] ?? INTENSITY_RANK.full;
  const fileRules = language ? loadAllRulesForLanguage(language) : [];
  const rules = fileRules.length > 0 ? fileRules : CAVEMAN_RULES;
  const selected = rules.filter((rule) => {
    const minRank = INTENSITY_RANK[rule.minIntensity ?? "lite"];
    return (rule.context === "all" || rule.context === context) && minRank <= rank;
  });
  return selected.length > 0
    ? selected
    : CAVEMAN_RULES.filter((rule) => {
        const minRank = INTENSITY_RANK[rule.minIntensity ?? "lite"];
        return (rule.context === "all" || rule.context === context) && minRank <= rank;
      });
}

export function getRuleByName(name: string): CavemanRule | undefined {
  return CAVEMAN_RULES.find((rule) => rule.name === name);
}

export function getCavemanRuleMetadata() {
  const intensities = ["lite", "full", "ultra"] as const;
  return CAVEMAN_RULES.map((rule) => ({
    name: rule.name,
    context: rule.context,
    category: rule.category ?? "terse",
    minIntensity: rule.minIntensity ?? "lite",
    intensities: intensities.filter(
      (intensity) => INTENSITY_RANK[intensity] >= INTENSITY_RANK[rule.minIntensity ?? "lite"]
    ),
    description: rule.description ?? rule.name.replace(/_/g, " "),
  }));
}

export { CAVEMAN_RULES };

import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import type { CavemanIntensity, CavemanRule } from "./types.ts";

type CavemanRuleCategory = NonNullable<CavemanRule["category"]>;
type CavemanRuleContext = CavemanRule["context"];

interface FileRule {
  name: string;
  pattern: string;
  replacement?: string;
  replacementMap?: Record<string, string>;
  flags?: string;
  context?: CavemanRuleContext;
  category?: CavemanRuleCategory;
  minIntensity?: CavemanIntensity;
  description?: string;
}

interface RulePack {
  language: string;
  category: string;
  rules: FileRule[];
}

export interface RulePackMetadata {
  language: string;
  categories: string[];
  ruleCount: number;
}

const VALID_CONTEXTS = new Set(["all", "user", "system", "assistant"]);
const VALID_CATEGORIES = new Set(["filler", "context", "structural", "dedup", "terse", "ultra"]);
const VALID_INTENSITIES = new Set(["lite", "full", "ultra"]);
const cache = new Map<string, CavemanRule[]>();
let rulesDirCache: string | null = null;

function normalizeReplacementKey(value: string): string {
  return value.trim().replace(/\s+/g, " ").toLowerCase();
}

function compileReplacement(rule: FileRule): CavemanRule["replacement"] {
  if (!rule.replacementMap) return rule.replacement ?? "";

  const normalizedMap = new Map(
    Object.entries(rule.replacementMap).map(([key, value]) => [normalizeReplacementKey(key), value])
  );
  const fallback = rule.replacement;
  return (match: string) => {
    const normalized = normalizeReplacementKey(match);
    if (normalizedMap.has(normalized)) return normalizedMap.get(normalized) ?? "";
    return fallback ?? match;
  };
}

function getRuleFlags(rule: FileRule): string {
  return rule.flags ?? "gi";
}

function getModuleDir(): string {
  const anchors = [process.cwd()];
  const argv1 = process.argv[1];
  if (typeof argv1 === "string" && argv1) anchors.push(path.dirname(argv1));
  const rel = path.join("open-sse", "services", "compression");
  for (const anchor of anchors) {
    let dir = path.resolve(anchor);
    for (let i = 0; i <= 8; i++) {
      if (fs.existsSync(path.join(dir, rel))) return dir;
      const parent = path.dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  }
  return path.join(os.homedir(), ".omniroute");
}

function getRulesDir(): string {
  if (rulesDirCache) return rulesDirCache;
  const root = getModuleDir();
  const candidates = [
    path.join(root, "open-sse", "services", "compression", "rules"),
    path.join(root, "app", "open-sse", "services", "compression", "rules"),
  ];
  rulesDirCache =
    candidates.find((candidate, index) => {
      return candidates.indexOf(candidate) === index && fs.existsSync(candidate);
    }) ?? candidates[0];
  return rulesDirCache;
}

function compileRule(rule: FileRule, source: string): CavemanRule {
  try {
    const flags = getRuleFlags(rule);
    return {
      name: rule.name,
      pattern: new RegExp(rule.pattern, flags),
      replacement: compileReplacement(rule),
      context: rule.context ?? "all",
      category: rule.category ?? "filler",
      minIntensity: rule.minIntensity ?? "lite",
      description: rule.description,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid Caveman rule pattern in ${source}:${rule.name}: ${message}`);
  }
}

export function validateRulePack(pack: unknown): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  if (!pack || typeof pack !== "object") {
    return { valid: false, errors: ["Rule pack must be an object"] };
  }

  const value = pack as Partial<RulePack>;
  if (typeof value.language !== "string" || !value.language.trim()) {
    errors.push("language must be a non-empty string");
  }
  if (typeof value.category !== "string" || !value.category.trim()) {
    errors.push("category must be a non-empty string");
  }
  if (!Array.isArray(value.rules)) {
    errors.push("rules must be an array");
  } else {
    value.rules.forEach((rule, index) => {
      if (!rule || typeof rule !== "object") {
        errors.push(`rules[${index}] must be an object`);
        return;
      }
      const entry = rule as Partial<FileRule>;
      const flags = typeof entry.flags === "string" ? entry.flags : "gi";
      if (typeof entry.name !== "string" || !entry.name.trim()) {
        errors.push(`rules[${index}].name must be a non-empty string`);
      }
      if (typeof entry.pattern !== "string" || !entry.pattern.trim()) {
        errors.push(`rules[${index}].pattern must be a non-empty string`);
      } else {
        try {
          new RegExp(entry.pattern, flags);
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error);
          errors.push(`rules[${index}].pattern is invalid: ${message}`);
        }
      }
      if (entry.flags !== undefined && typeof entry.flags !== "string") {
        errors.push(`rules[${index}].flags must be a string`);
      }
      if (entry.replacement !== undefined && typeof entry.replacement !== "string") {
        errors.push(`rules[${index}].replacement must be a string`);
      }
      if (entry.replacementMap !== undefined) {
        if (
          !entry.replacementMap ||
          typeof entry.replacementMap !== "object" ||
          Array.isArray(entry.replacementMap)
        ) {
          errors.push(`rules[${index}].replacementMap must be an object`);
        } else {
          Object.entries(entry.replacementMap).forEach(([key, replacement]) => {
            if (!key.trim()) {
              errors.push(`rules[${index}].replacementMap contains an empty key`);
            }
            if (typeof replacement !== "string") {
              errors.push(`rules[${index}].replacementMap.${key} must be a string`);
            }
          });
        }
      }
      if (typeof entry.replacement !== "string" && entry.replacementMap === undefined) {
        errors.push(`rules[${index}] must define replacement or replacementMap`);
      }
      if (entry.context !== undefined && !VALID_CONTEXTS.has(entry.context)) {
        errors.push(`rules[${index}].context is invalid`);
      }
      if (entry.category !== undefined && !VALID_CATEGORIES.has(entry.category)) {
        errors.push(`rules[${index}].category is invalid`);
      }
      if (entry.minIntensity !== undefined && !VALID_INTENSITIES.has(entry.minIntensity)) {
        errors.push(`rules[${index}].minIntensity is invalid`);
      }
    });
  }
  return { valid: errors.length === 0, errors };
}

function readPack(language: string, category: string): RulePack | null {
  const filename = path.join(getRulesDir(), language, `${category}.json`);
  if (!fs.existsSync(filename)) return null;
  const parsed = JSON.parse(fs.readFileSync(filename, "utf8")) as unknown;
  const validation = validateRulePack(parsed);
  if (!validation.valid) {
    throw new Error(
      `Invalid Caveman rule pack ${language}/${category}: ${validation.errors.join("; ")}`
    );
  }
  return parsed as RulePack;
}

export function loadRulePack(
  language: string,
  category: string,
  options: { refresh?: boolean } = {}
): CavemanRule[] {
  const key = `${getRulesDir()}:${language}:${category}`;
  if (cache.has(key) && !options.refresh) return cache.get(key) ?? [];

  const pack = readPack(language, category);
  if (!pack) {
    cache.set(key, []);
    return [];
  }

  const rules = pack.rules.map((rule) => compileRule(rule, `${language}/${category}`));
  cache.set(key, rules);
  return rules;
}

export function loadAllRulesForLanguage(
  language: string,
  options: { refresh?: boolean } = {}
): CavemanRule[] {
  const key = `${getRulesDir()}:${language}:*`;
  if (cache.has(key) && !options.refresh) return cache.get(key) ?? [];

  const languageDir = path.join(getRulesDir(), language);
  if (!fs.existsSync(languageDir)) {
    cache.set(key, []);
    return [];
  }

  const rules = fs
    .readdirSync(languageDir)
    .filter((entry) => entry.endsWith(".json"))
    .sort()
    .flatMap((entry) => loadRulePack(language, path.basename(entry, ".json"), options));

  cache.set(key, rules);
  return rules;
}

export function getAvailableLanguagePacks(): RulePackMetadata[] {
  const root = getRulesDir();
  if (!fs.existsSync(root)) return [];

  return fs
    .readdirSync(root)
    .filter((entry) => fs.statSync(path.join(root, entry)).isDirectory())
    .map((language) => {
      const categories = fs
        .readdirSync(path.join(root, language))
        .filter((entry) => entry.endsWith(".json"))
        .map((entry) => path.basename(entry, ".json"))
        .sort();
      const ruleCount = categories.reduce(
        (count, category) => count + loadRulePack(language, category).length,
        0
      );
      return { language, categories, ruleCount };
    })
    .sort((a, b) => a.language.localeCompare(b.language));
}

export function loadCavemanFileRules(
  language: string,
  options: { refresh?: boolean } = {}
): CavemanRule[] {
  return loadAllRulesForLanguage(language, options);
}

export function listCavemanRulePacks(): RulePackMetadata[] {
  return getAvailableLanguagePacks();
}

import { findFencedCodeBlocks } from "./preservation.ts";

export interface ValidationResult {
  valid: boolean;
  errors: string[];
  warnings: string[];
  fallbackApplied: boolean;
}

function requireExactPresence(
  label: string,
  originalItems: string[],
  compressed: string,
  errors: string[]
) {
  for (const item of originalItems) {
    if (!compressed.includes(item)) {
      const preview = collapseWhitespaceForPreview(item).slice(0, 80);
      errors.push(`${label} changed or missing: ${preview}`);
    }
  }
}

function isPreviewWhitespace(char: string): boolean {
  return (
    char === " " ||
    char === "\t" ||
    char === "\n" ||
    char === "\r" ||
    char === "\f" ||
    char === "\v"
  );
}

function isHorizontalWhitespace(char: string): boolean {
  return char === " " || char === "\t";
}

function isAsciiDigit(char: string | undefined): boolean {
  return !!char && char >= "0" && char <= "9";
}

function isAsciiUpper(char: string | undefined): boolean {
  return !!char && char >= "A" && char <= "Z";
}

function isAsciiLetter(char: string | undefined): boolean {
  return !!char && ((char >= "A" && char <= "Z") || (char >= "a" && char <= "z"));
}

function isAsciiAlphaNumeric(char: string | undefined): boolean {
  return !!char && (isAsciiLetter(char) || isAsciiDigit(char));
}

function isWordChar(char: string | undefined): boolean {
  return !!char && (isAsciiAlphaNumeric(char) || char === "_");
}

function isUrlTerminator(char: string): boolean {
  return (
    isPreviewWhitespace(char) ||
    char === ")" ||
    char === "]" ||
    char === '"' ||
    char === "'" ||
    char === ">"
  );
}

function collapseWhitespaceForPreview(text: string): string {
  let output = "";
  let previousWasWhitespace = false;
  let changed = false;

  for (const char of text) {
    if (isPreviewWhitespace(char)) {
      if (!previousWasWhitespace) {
        output += " ";
      } else {
        changed = true;
      }
      if (char !== " ") changed = true;
      previousWasWhitespace = true;
      continue;
    }

    output += char;
    previousWasWhitespace = false;
  }

  return changed ? output : text;
}

export function validateCompression(original: string, compressed: string): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];

  if (typeof original !== "string" || typeof compressed !== "string") {
    return {
      valid: false,
      errors: ["validation received non-string input"],
      warnings,
      fallbackApplied: true,
    };
  }

  if (original.length > 0 && compressed.trim().length === 0) {
    errors.push("compressed text is empty");
  }

  requireExactPresence("fenced code block", findFencedCodeBlocks(original), compressed, errors);
  requireExactPresence("inline code", collectInlineCode(original), compressed, errors);
  requireExactPresence("URL", collectUrls(original), compressed, errors);
  requireExactPresence("markdown link", collectMarkdownLinks(original), compressed, errors);
  requireExactPresence("frontmatter", collectFrontmatter(original), compressed, errors);
  requireExactPresence("heading", collectHeadings(original), compressed, errors);
  requireExactPresence("table row", collectTableRows(original), compressed, errors);
  requireExactPresence("math block", collectMathBlocks(original), compressed, errors);
  requireExactPresence("inline math", collectInlineMath(original), compressed, errors);
  requireExactPresence("LaTeX block", collectLatexBlocks(original), compressed, errors);
  requireExactPresence("version", collectVersions(original), compressed, errors);
  requireExactPresence("CONST_CASE", collectConstCase(original), compressed, errors);

  const originalFenceCount = findFencedCodeBlocks(original).length;
  const compressedFenceCount = findFencedCodeBlocks(compressed).length;
  if (compressedFenceCount < originalFenceCount) {
    errors.push(
      `fenced code block count dropped: ${originalFenceCount} -> ${compressedFenceCount}`
    );
  }

  if (compressed.length > original.length) {
    warnings.push("compressed text is longer than original");
  }

  return {
    valid: errors.length === 0,
    errors,
    warnings,
    fallbackApplied: errors.length > 0,
  };
}

function collectInlineCode(text: string): string[] {
  const matches: string[] = [];

  for (let index = 0; index < text.length; index++) {
    if (text[index] !== "`") continue;
    const end = text.indexOf("`", index + 1);
    if (end === -1) break;

    const content = text.slice(index + 1, end);
    if (content.length > 0 && !content.includes("\n")) {
      matches.push(text.slice(index, end + 1));
      index = end;
    }
  }

  return matches;
}

function collectUrls(text: string): string[] {
  const matches: string[] = [];

  for (let index = 0; index < text.length; index++) {
    const startsWithHttp = text.startsWith("http://", index);
    const startsWithHttps = text.startsWith("https://", index);
    if (!startsWithHttp && !startsWithHttps) continue;
    if (index > 0 && isWordChar(text[index - 1])) continue;

    let end = index + (startsWithHttps ? "https://".length : "http://".length);
    while (end < text.length && !isUrlTerminator(text[end])) {
      end++;
    }

    if (end > index) {
      matches.push(text.slice(index, end));
      index = end - 1;
    }
  }

  return matches;
}

function collectMarkdownLinks(text: string): string[] {
  const matches: string[] = [];

  for (let index = 0; index < text.length; index++) {
    if (text[index] !== "[") continue;

    const labelEnd = text.indexOf("]", index + 1);
    if (labelEnd === -1 || labelEnd - index - 1 > 1000) continue;
    if (text.slice(index + 1, labelEnd).includes("\n")) continue;
    if (text[labelEnd + 1] !== "(") continue;

    const targetStart = labelEnd + 2;
    const maxTargetEnd = Math.min(text.length, targetStart + 2000);
    let targetEnd = -1;
    for (let cursor = targetStart; cursor < maxTargetEnd; cursor++) {
      if (text[cursor] === "\n") break;
      if (text[cursor] === ")") {
        targetEnd = cursor;
        break;
      }
    }

    if (targetEnd !== -1) {
      matches.push(text.slice(index, targetEnd + 1));
      index = targetEnd;
    }
  }

  return matches;
}

function collectFrontmatter(text: string): string[] {
  if (!text.startsWith("---\n")) return [];
  const close = text.indexOf("\n---", 4);
  if (close === -1) return [];
  const closeEnd = text.indexOf("\n", close + 4);
  const end = closeEnd === -1 ? text.length : closeEnd + 1;
  return [text.slice(0, end)];
}

function collectHeadings(text: string): string[] {
  return collectLines(text).filter((line) => {
    let markerCount = 0;
    while (markerCount < line.length && line[markerCount] === "#") {
      markerCount++;
    }
    if (markerCount < 1 || markerCount > 6) return false;
    if (!isPreviewWhitespace(line[markerCount] ?? "")) return false;

    for (let index = markerCount + 1; index < line.length; index++) {
      if (!isPreviewWhitespace(line[index])) return true;
    }
    return false;
  });
}

function collectTableRows(text: string): string[] {
  return collectLines(text).filter((line) => {
    let index = 0;
    while (index < line.length && isHorizontalWhitespace(line[index])) {
      index++;
    }
    if (line[index] !== "|") return false;

    let pipeCount = 0;
    for (; index < line.length; index++) {
      if (line[index] === "|") pipeCount++;
    }
    return pipeCount >= 2;
  });
}

function collectLines(text: string): string[] {
  const lines: string[] = [];
  let start = 0;

  for (let index = 0; index < text.length; index++) {
    if (text[index] !== "\n") continue;
    lines.push(text.slice(start, index));
    start = index + 1;
  }

  lines.push(text.slice(start));
  return lines;
}

function collectMathBlocks(text: string): string[] {
  const matches: string[] = [];
  let index = 0;

  while (index < text.length) {
    const start = text.indexOf("$$", index);
    if (start === -1) break;
    const end = text.indexOf("$$", start + 2);
    if (end === -1) break;

    if (end - start - 2 <= 10000) {
      matches.push(text.slice(start, end + 2));
      index = end + 2;
    } else {
      index = start + 2;
    }
  }

  return matches;
}

function collectInlineMath(text: string): string[] {
  const matches: string[] = [];

  for (let index = 0; index < text.length; index++) {
    if (text[index] !== "$") continue;
    if (text[index - 1] === "$") continue;

    const next = text[index + 1];
    if (!next || isPreviewWhitespace(next) || next === "$" || isAsciiDigit(next)) continue;

    const maxEnd = Math.min(text.length, index + 1 + 160);
    for (let cursor = index + 1; cursor < maxEnd; cursor++) {
      const char = text[cursor];
      if (char === "\n") break;
      if (char === "\\") {
        cursor++;
        continue;
      }
      if (char !== "$") continue;
      if (isPreviewWhitespace(text[cursor - 1] ?? "")) continue;
      if (text[cursor + 1] === "$") continue;

      matches.push(text.slice(index, cursor + 1));
      index = cursor;
      break;
    }
  }

  return matches;
}

function collectLatexBlocks(text: string): string[] {
  const matches: string[] = [];
  let index = 0;

  while (index < text.length) {
    const start = text.indexOf("\\begin{", index);
    if (start === -1) break;

    const envStart = start + "\\begin{".length;
    const envEnd = text.indexOf("}", envStart);
    if (envEnd === -1 || envEnd - envStart < 1 || envEnd - envStart > 50) {
      index = envStart;
      continue;
    }

    const env = text.slice(envStart, envEnd);
    if (![...env].every((char) => isAsciiLetter(char) || char === "*")) {
      index = envStart;
      continue;
    }

    const closeToken = `\\end{${env}}`;
    const closeStart = text.indexOf(closeToken, envEnd + 1);
    if (closeStart === -1) {
      index = envEnd + 1;
      continue;
    }

    if (closeStart - envEnd - 1 <= 10000) {
      const end = closeStart + closeToken.length;
      matches.push(text.slice(start, end));
      index = end;
    } else {
      index = envEnd + 1;
    }
  }

  return matches;
}

function collectVersions(text: string): string[] {
  const matches: string[] = [];

  for (let index = 0; index < text.length; index++) {
    if (!isAsciiDigit(text[index])) continue;
    if (index > 0 && isWordChar(text[index - 1])) continue;

    let cursor = readDigits(text, index);
    let dotGroups = 0;
    while (dotGroups < 3 && text[cursor] === "." && isAsciiDigit(text[cursor + 1])) {
      cursor = readDigits(text, cursor + 1);
      dotGroups++;
    }
    if (dotGroups < 1) continue;

    if ((text[cursor] === "-" || text[cursor] === "+") && isVersionSuffixChar(text[cursor + 1])) {
      cursor++;
      while (cursor < text.length && isVersionSuffixChar(text[cursor])) {
        cursor++;
      }
    }

    if (isWordChar(text[cursor])) continue;
    matches.push(text.slice(index, cursor));
    index = cursor - 1;
  }

  return matches;
}

function readDigits(text: string, start: number): number {
  let cursor = start;
  while (cursor < text.length && isAsciiDigit(text[cursor])) {
    cursor++;
  }
  return cursor;
}

function isVersionSuffixChar(char: string | undefined): boolean {
  return !!char && (isAsciiAlphaNumeric(char) || char === "." || char === "-");
}

function collectConstCase(text: string): string[] {
  const matches: string[] = [];

  for (let index = 0; index < text.length; index++) {
    if (!isAsciiUpper(text[index])) continue;
    if (index > 0 && isWordChar(text[index - 1])) continue;

    let cursor = index + 1;
    let hasUnderscore = false;
    while (cursor < text.length) {
      const char = text[cursor];
      if (char === "_") {
        if (!isAsciiUpper(text[cursor + 1]) && !isAsciiDigit(text[cursor + 1])) break;
        hasUnderscore = true;
        cursor++;
        continue;
      }
      if (!isAsciiUpper(char) && !isAsciiDigit(char)) break;
      cursor++;
    }

    if (!hasUnderscore || isWordChar(text[cursor])) continue;
    matches.push(text.slice(index, cursor));
    index = cursor - 1;
  }

  return matches;
}

const LANGUAGE_HINTS: Record<string, RegExp[]> = {
  "pt-BR": [/\b(?:voce|você|preciso|arquivo|codigo|código|erro|falha|obrigado)\b/i],
  // NOTE: English-ambiguous words are intentionally excluded — "error" (es) and
  // "configuration" (fr) are identical in English and would misclassify English text.
  // Spanish/French keep their distinctive native spellings (fallo / erreur, etc).
  es: [/\b(?:necesito|archivo|codigo|código|fallo|gracias|puedes)\b/i],
  de: [/\b(?:ich|datei|fehler|bitte|kannst|konfiguration|danke)\b/i],
  fr: [/\b(?:fichier|erreur|merci|peux|besoin)\b/i],
  ja: [/[\u3040-\u30ff]/],
  id: [/\b(?:saya|kamu|anda|dengan|untuk|yang|tidak|bisa|terima\s+kasih|dari)\b/i],
};

/**
 * Score each language by the NUMBER of native-keyword hits and pick the highest
 * (English-ambiguous words are excluded from the hint lists, so a lone shared word
 * never misclassifies English). Highest score wins; ties keep the earlier language;
 * zero hits → English. (B-LANG-DETECTOR)
 */
export function detectCompressionLanguage(text: string): string {
  // CJK disambiguation: Han ideographs (U+4E00–U+9FFF) are shared by Chinese and Japanese, but
  // kana (U+3040–U+30FF) is Japanese-exclusive. Text with Han and no kana is Chinese (zh); text
  // with kana falls through to the scorer below, where the `ja` kana hint catches it. Keeping zh
  // out of the additive scorer means a Han-heavy Japanese sentence is never misread as Chinese.
  if (/[一-鿿]/.test(text) && !/[぀-ヿ]/.test(text)) {
    return "zh";
  }

  let best = "en";
  let bestScore = 0;
  for (const [language, patterns] of Object.entries(LANGUAGE_HINTS)) {
    let score = 0;
    for (const pattern of patterns) {
      const global = pattern.flags.includes("g")
        ? pattern
        : new RegExp(pattern.source, pattern.flags + "g");
      const matches = text.match(global);
      if (matches) score += matches.length;
    }
    if (score > bestScore) {
      bestScore = score;
      best = language;
    }
  }
  return best;
}

export function listSupportedCompressionLanguages(): string[] {
  // zh is detected via the CJK Han/kana disambiguation in detectCompressionLanguage rather than a
  // keyword hint (so it stays out of the additive scorer), hence it is listed explicitly here.
  return ["en", "zh", ...Object.keys(LANGUAGE_HINTS)];
}

import type { AggressiveConfig, CompressionStats, Summarizer } from "./types.ts";
import { DEFAULT_AGGRESSIVE_CONFIG } from "./types.ts";
import {
  compressToolResult,
  compressAnthropicToolResultBlock,
  isAnthropicToolResultBlock,
} from "./toolResultCompressor.ts";
import { applyAging } from "./progressiveAging.ts";
import { RuleBasedSummarizer } from "./summarizer.ts";
import { cavemanCompress } from "./caveman.ts";
import { applyLiteCompression } from "./lite.ts";
import { extractTextContent, replaceTextContent, type ChatMessageLike } from "./messageContent.ts";

const COMPRESSED_MARKER_RE = /^\[COMPRESSED:/;

type ChatMessage = ChatMessageLike;

interface AggressiveCompressionResult {
  messages: ChatMessage[];
  stats: CompressionStats;
}

function setContent(msg: ChatMessage, newContent: string): ChatMessage {
  return replaceTextContent(msg, newContent) as ChatMessage;
}

function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4);
}

export function compressAggressive(
  messages: ChatMessage[],
  config?: Partial<AggressiveConfig>,
  stats?: CompressionStats
): AggressiveCompressionResult {
  const cfg: AggressiveConfig = {
    ...DEFAULT_AGGRESSIVE_CONFIG,
    ...config,
    thresholds: { ...DEFAULT_AGGRESSIVE_CONFIG.thresholds, ...(config?.thresholds ?? {}) },
    toolStrategies: {
      ...DEFAULT_AGGRESSIVE_CONFIG.toolStrategies,
      ...(config?.toolStrategies ?? {}),
    },
  };

  const summarizer: Summarizer = new RuleBasedSummarizer();

  const resultStats: CompressionStats = stats ?? {
    originalTokens: 0,
    compressedTokens: 0,
    savingsPercent: 0,
    techniquesUsed: [],
    mode: "aggressive",
    timestamp: Date.now(),
  };

  const originalTokens = messages.reduce(
    (sum, m) => sum + estimateTokens(extractTextContent(m.content)),
    0
  );
  resultStats.originalTokens = originalTokens;

  let currentMessages = [...messages];
  let summarizerSavings = 0;
  let toolResultSavings = 0;
  let agingSavings = 0;

  // Step 1: Tool-result compression
  try {
    const afterToolResult = currentMessages.map((msg) => {
      if (cfg.preserveSystemPrompt !== false && msg.role === "system") return msg;

      // OpenAI-shape: a dedicated tool/function message whose content is the result text.
      if (msg.role === "tool" || msg.role === "function") {
        const text = extractTextContent(msg.content);
        if (!text || COMPRESSED_MARKER_RE.test(text)) return msg;

        const result = compressToolResult(text, cfg.toolStrategies);
        if (result.strategy === "none" || result.saved <= 0) return msg;

        toolResultSavings += result.saved;
        return setContent(msg, result.compressed);
      }

      // Anthropic-shape: `tool_result` content blocks live inside a (typically user)
      // message's content array. Compress the text inside each block while preserving
      // the tool_use_id and block structure exactly (B-AGG-ANTHROPIC-TR).
      if (!Array.isArray(msg.content)) return msg;
      if (!msg.content.some(isAnthropicToolResultBlock)) return msg;

      let blockSavings = 0;
      const nextContent = msg.content.map((part) => {
        if (!isAnthropicToolResultBlock(part)) return part;
        const { block, saved } = compressAnthropicToolResultBlock(part, cfg.toolStrategies);
        blockSavings += saved;
        return block;
      });
      if (blockSavings <= 0) return msg;
      toolResultSavings += blockSavings;
      return { ...msg, content: nextContent };
    });
    currentMessages = afterToolResult;
  } catch (err) {
    // Downgrade: skip tool-result compression, continue pipeline
  }

  // Step 2: Progressive aging
  try {
    const agingResult = applyAging(
      currentMessages,
      cfg.thresholds,
      summarizer,
      cfg.preserveSystemPrompt !== false
    );
    agingSavings = agingResult.saved;
    currentMessages = agingResult.messages as ChatMessage[];
  } catch (err) {
    // Downgrade: skip aging, continue with current messages
  }

  // Step 3: Fallback summarizer for remaining long messages
  if (cfg.summarizerEnabled) {
    try {
      currentMessages = currentMessages.map((msg) => {
        if (cfg.preserveSystemPrompt !== false && msg.role === "system") return msg;
        const text = extractTextContent(msg.content);
        if (!text || COMPRESSED_MARKER_RE.test(text)) return msg;
        if (text.length <= cfg.maxTokensPerMessage * 4) return msg;

        const summary = summarizer.summarize([msg], {
          maxLen: cfg.maxTokensPerMessage,
          preserveCode: true,
        });
        if (summary && summary.length < text.length) {
          summarizerSavings += estimateTokens(text) - estimateTokens(summary);
          return setContent(msg, `[COMPRESSED:summary] ${summary}`);
        }
        return msg;
      });
    } catch (err) {
      // Downgrade: skip fallback summarizer
    }
  }

  // Downgrade chain: if total savings < threshold, try caveman then lite
  const compressedTokens = currentMessages.reduce(
    (sum, m) => sum + estimateTokens(extractTextContent(m.content)),
    0
  );
  resultStats.compressedTokens = compressedTokens;
  resultStats.savingsPercent =
    originalTokens > 0 ? ((originalTokens - compressedTokens) / originalTokens) * 100 : 0;

  if (resultStats.savingsPercent < cfg.minSavingsThreshold * 100) {
    try {
      const cavemanResult = cavemanCompress({ messages: currentMessages as unknown as Parameters<typeof cavemanCompress>[0]["messages"] });
      if (cavemanResult?.compressed && cavemanResult.stats) {
        const cavemanSavings = cavemanResult.stats.savingsPercent ?? 0;
        if (cavemanSavings > resultStats.savingsPercent) {
          currentMessages = (cavemanResult.body?.messages ?? currentMessages) as ChatMessage[];
          resultStats.compressedTokens = cavemanResult.stats.compressedTokens ?? compressedTokens;
          resultStats.savingsPercent = cavemanSavings;
          resultStats.techniquesUsed.push("caveman-fallback");
        }
      }
    } catch (err) {
      // Caveman failed, try lite
    }

    try {
      const liteResult = applyLiteCompression(
        { messages: currentMessages },
        { preserveSystemPrompt: cfg.preserveSystemPrompt !== false }
      );
      if (liteResult?.compressed && liteResult.stats) {
        const liteSavings = liteResult.stats.savingsPercent ?? 0;
        if (liteSavings > resultStats.savingsPercent) {
          currentMessages = (liteResult.body?.messages ?? currentMessages) as ChatMessage[];
          resultStats.compressedTokens = liteResult.stats.compressedTokens ?? compressedTokens;
          resultStats.savingsPercent = liteSavings;
          resultStats.techniquesUsed.push("lite-fallback");
        }
      }
    } catch (err) {
      // Lite also failed, return current messages as-is
    }
  }

  resultStats.techniquesUsed.push(
    ...(toolResultSavings > 0 ? ["toolResult"] : []),
    ...(agingSavings > 0 ? ["aging"] : []),
    ...(summarizerSavings > 0 ? ["summarizer"] : [])
  );

  resultStats.aggressive = {
    summarizerSavings,
    toolResultSavings,
    agingSavings,
  };

  return { messages: currentMessages, stats: resultStats };
}

export { DEFAULT_AGGRESSIVE_CONFIG };

import type { ToolStrategiesConfig } from "./types.ts";

export interface CompressionResult {
  compressed: string;
  strategy: "fileContent" | "grepSearch" | "shellOutput" | "json" | "errorMessage" | "none";
  saved: number;
}

const ANSI_RE = /\x1b\[[0-9;]*[a-zA-Z]/g;
const SHELL_PROMPT_RE = /\$\s/;
const JSON_PREFIX_RE = /^\s*[{[]/;
const COMPRESSED_MARKER_RE = /^\[COMPRESSED:/;

function isCodeLikeLine(rawLine: string): boolean {
  const line = rawLine.trimStart();
  return (
    line.startsWith("import ") ||
    line.startsWith("export ") ||
    line.startsWith("function ") ||
    line.startsWith("class ") ||
    line.startsWith("const ") ||
    line.startsWith("let ") ||
    line.startsWith("var ") ||
    line.startsWith("return ") ||
    line.startsWith("if(") ||
    line.startsWith("if (") ||
    line.startsWith("for(") ||
    line.startsWith("for (") ||
    line.startsWith("while(") ||
    line.startsWith("while (")
  );
}

function parseGrepLinePath(line: string): string | null {
  const firstColon = line.indexOf(":");
  if (firstColon <= 0) return null;

  const secondColon = line.indexOf(":", firstColon + 1);
  if (secondColon === -1) return null;

  const lineNumber = line.slice(firstColon + 1, secondColon);
  if (!lineNumber || ![...lineNumber].every((char) => char >= "0" && char <= "9")) {
    return null;
  }

  const filePath = line.slice(0, firstColon);
  if (!filePath || /\s/.test(filePath)) return null;
  return filePath;
}

function hasErrorLikeOutput(content: string): boolean {
  const lower = content.toLowerCase();
  return (
    lower.includes("error:") ||
    lower.includes("error ") ||
    lower.includes("[error]") ||
    lower.includes("exception:") ||
    lower.includes("exception ") ||
    lower.includes("[exception]") ||
    lower.includes("traceback")
  );
}

function compressFileContent(content: string): string | null {
  const lines = content.split("\n");
  if (lines.length < 3) return null;
  if (!lines.some(isCodeLikeLine)) return null;
  const keep = 20;
  const tail = 5;
  if (lines.length <= keep + tail) return content;
  const head = lines.slice(0, keep).join("\n");
  const tailLines = lines.slice(-tail).join("\n");
  const elided = lines.length - keep - tail;
  return `${head}\n… [${elided} lines elided] …\n${tailLines}`;
}

function compressGrepSearch(content: string): string | null {
  const lines = content.split("\n");
  const grepLines = lines.filter((line) => parseGrepLinePath(line) !== null);
  if (grepLines.length === 0) return null;
  const paths = new Set<string>();
  for (const line of grepLines) {
    const filePath = parseGrepLinePath(line);
    if (filePath) paths.add(filePath);
  }
  const top30 = grepLines.slice(0, 30);
  const remaining = grepLines.length - top30.length;
  let result = top30.join("\n");
  if (remaining > 0) {
    result += `\n… [${remaining} more matches]`;
  }
  result += `\nFiles: ${[...paths].join(", ")}`;
  return result;
}

function compressShellOutput(content: string): string | null {
  const hasAnsi = ANSI_RE.test(content);
  const hasPrompt = SHELL_PROMPT_RE.test(content);
  if (!hasAnsi && !hasPrompt) return null;
  let cleaned = content.replace(ANSI_RE, "");
  const lines = cleaned.split("\n");
  const last50 = lines.slice(-50);
  const deduped: string[] = [];
  for (const line of last50) {
    if (deduped.length === 0 || line !== deduped[deduped.length - 1]) {
      deduped.push(line);
    }
  }
  return deduped.join("\n");
}

function compressJson(content: string): string | null {
  if (content.length <= 2000) return null;
  if (!JSON_PREFIX_RE.test(content)) return null;
  let parsed: unknown;
  try {
    parsed = JSON.parse(content);
  } catch {
    return null;
  }
  if (Array.isArray(parsed)) {
    const arr = parsed as unknown[];
    if (arr.length <= 7) return content;
    const head = arr.slice(0, 5);
    const tail = arr.slice(-2);
    return JSON.stringify({ type: "array", total: arr.length, first5: head, last2: tail }, null, 2);
  }
  if (typeof parsed === "object" && parsed !== null) {
    const obj = parsed as Record<string, unknown>;
    const keys = Object.keys(obj);
    const summary: Record<string, unknown> = {};
    for (const key of keys.slice(0, 20)) {
      const val = obj[key];
      if (typeof val === "object" && val !== null) {
        summary[key] = `{…${Object.keys(val as Record<string, unknown>).length} keys}`;
      } else {
        summary[key] = val;
      }
    }
    if (keys.length > 20) {
      summary[`_remaining_${keys.length - 20}_keys`] = true;
    }
    return JSON.stringify(summary, null, 2);
  }
  return null;
}

function compressErrorMessage(content: string): string | null {
  if (!hasErrorLikeOutput(content)) return null;
  const lines = content.split("\n");
  const errorLine = lines[0] || "";
  const stackLines = lines.slice(1);
  const head = stackLines.slice(0, 10);
  const tail = stackLines.length > 10 ? stackLines.slice(-3) : [];
  const middle = stackLines.length > 13 ? [`… [${stackLines.length - 13} frames elided] …`] : [];
  const result = [errorLine, ...head, ...middle, ...tail].join("\n");
  return result;
}

function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4);
}

/** Minimal shape of an Anthropic `tool_result` content block. */
export interface AnthropicToolResultBlock {
  type: "tool_result";
  tool_use_id?: string;
  content?: string | Array<{ type?: string; text?: string; [key: string]: unknown }>;
  [key: string]: unknown;
}

export function isAnthropicToolResultBlock(value: unknown): value is AnthropicToolResultBlock {
  return (
    !!value &&
    typeof value === "object" &&
    (value as { type?: unknown }).type === "tool_result"
  );
}

/**
 * Compress the text inside an Anthropic-shape `tool_result` content block,
 * reusing the same per-type strategies as OpenAI-shape tool messages. The
 * `tool_use_id` and block type are preserved exactly; only the inner text is
 * compressed. Returns the (possibly unchanged) block plus tokens saved.
 */
export function compressAnthropicToolResultBlock(
  block: AnthropicToolResultBlock,
  opts: ToolStrategiesConfig
): { block: AnthropicToolResultBlock; saved: number } {
  const content = block.content;

  if (typeof content === "string") {
    if (!content || COMPRESSED_MARKER_RE.test(content)) return { block, saved: 0 };
    const result = compressToolResult(content, opts);
    if (result.strategy === "none" || result.saved <= 0) return { block, saved: 0 };
    return { block: { ...block, content: result.compressed }, saved: result.saved };
  }

  if (Array.isArray(content)) {
    let saved = 0;
    let changed = false;
    const nextContent = content.map((part) => {
      if (
        !part ||
        typeof part !== "object" ||
        part.type !== "text" ||
        typeof part.text !== "string"
      ) {
        return part;
      }
      const text = part.text;
      if (!text || COMPRESSED_MARKER_RE.test(text)) return part;
      const result = compressToolResult(text, opts);
      if (result.strategy === "none" || result.saved <= 0) return part;
      saved += result.saved;
      changed = true;
      return { ...part, text: result.compressed };
    });
    if (!changed) return { block, saved: 0 };
    return { block: { ...block, content: nextContent }, saved };
  }

  return { block, saved: 0 };
}

export function compressToolResult(content: string, opts: ToolStrategiesConfig): CompressionResult {
  if (opts.fileContent) {
    const result = compressFileContent(content);
    if (result !== null) {
      return {
        compressed: result,
        strategy: "fileContent",
        saved: estimateTokens(content) - estimateTokens(result),
      };
    }
  }

  if (opts.grepSearch) {
    const result = compressGrepSearch(content);
    if (result !== null) {
      return {
        compressed: result,
        strategy: "grepSearch",
        saved: estimateTokens(content) - estimateTokens(result),
      };
    }
  }

  if (opts.shellOutput) {
    const result = compressShellOutput(content);
    if (result !== null) {
      return {
        compressed: result,
        strategy: "shellOutput",
        saved: estimateTokens(content) - estimateTokens(result),
      };
    }
  }

  if (opts.json) {
    const result = compressJson(content);
    if (result !== null) {
      return {
        compressed: result,
        strategy: "json",
        saved: estimateTokens(content) - estimateTokens(result),
      };
    }
  }

  if (opts.errorMessage) {
    const result = compressErrorMessage(content);
    if (result !== null) {
      return {
        compressed: result,
        strategy: "errorMessage",
        saved: estimateTokens(content) - estimateTokens(result),
      };
    }
  }

  return { compressed: content, strategy: "none", saved: 0 };
}

import type { AgingThresholds, Summarizer } from "./types.ts";
import { DEFAULT_AGGRESSIVE_CONFIG } from "./types.ts";
import { applyLiteCompression } from "./lite.ts";
import { cavemanCompress } from "./caveman.ts";
import { extractTextContent, replaceTextContent, type ChatMessageLike } from "./messageContent.ts";

const COMPRESSED_MARKER_RE = /^\[COMPRESSED:/;
const JSON_PREFIX_RE = /^\s*[{[]/;
const FENCE_RE = /^\s*```/;

function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4);
}

/**
 * Structured content that an inline `[COMPRESSED:...]` prefix would corrupt:
 * a pure-JSON payload (parses as JSON) or a fenced code block (B-AGG-JSONTAG).
 */
type StructuredKind = "json" | "fenced" | null;

function structuredKind(text: string): StructuredKind {
  const trimmed = text.trim();
  if (FENCE_RE.test(trimmed) && trimmed.endsWith("```")) return "fenced";
  if (JSON_PREFIX_RE.test(trimmed)) {
    try {
      JSON.parse(trimmed);
      return "json";
    } catch {
      return null;
    }
  }
  return null;
}

/**
 * Build the aged content for a message, keeping structured payloads intact:
 * - pure JSON: leave verbatim and untagged (stays JSON.parse-able). Aging engines
 *   (lite/caveman) do not shrink JSON anyway, so nothing is lost; tracked in stats
 *   via the unchanged content. The recursion guard relies on structuredKind() on the
 *   next pass, so re-running aging is a no-op (idempotent).
 * - fenced code block: place the tag on its own line BEFORE the fence so the block
 *   stays valid and the content still starts with `[COMPRESSED:` (recursion guard).
 * - everything else: inline-prepend the tag as before.
 */
function tagAged(tier: string, originalText: string, compressed: string): string {
  const kind = structuredKind(originalText);
  if (kind === "json") {
    return originalText;
  }
  if (kind === "fenced") {
    return `[COMPRESSED:aging:${tier}]\n${originalText}`;
  }
  return `[COMPRESSED:aging:${tier}] ${compressed}`;
}

type ChatMessage = ChatMessageLike;

type CompressedResult = {
  body?: { messages?: Array<{ content?: ChatMessageLike["content"] }> };
};

function setContent(msg: ChatMessage, newContent: string): ChatMessage {
  return replaceTextContent(msg, newContent) as ChatMessage;
}

export function applyAging(
  messages: unknown[],
  thresholds?: AgingThresholds,
  summarizer?: Summarizer,
  preserveSystemPrompt = true
): { messages: unknown[]; saved: number } {
  const t = thresholds ?? DEFAULT_AGGRESSIVE_CONFIG.thresholds;
  const sum = summarizer ?? {
    summarize: (msgs: unknown[]) => {
      const typed = msgs as ChatMessage[];
      const last = typed.filter((m) => m.role === "assistant").pop();
      return last ? extractTextContent(last.content).slice(0, 200) : "";
    },
  };

  const typed = messages as ChatMessage[];
  if (typed.length === 0) return { messages: [], saved: 0 };

  const totalMessages = typed.length;
  const result: ChatMessage[] = [];
  let saved = 0;

  for (let i = 0; i < typed.length; i++) {
    const msg = typed[i];
    const text = extractTextContent(msg.content);

    if ((preserveSystemPrompt && msg.role === "system") || COMPRESSED_MARKER_RE.test(text)) {
      result.push(msg);
      continue;
    }

    const distanceFromEnd = totalMessages - 1 - i;

    if (distanceFromEnd <= t.verbatim) {
      result.push(msg);
    } else if (distanceFromEnd <= t.light) {
      const compressed = applyLiteCompression({ messages: [msg] }) as CompressedResult;
      if (compressed?.body?.messages?.[0]?.content) {
        const newContent =
          typeof compressed.body.messages[0].content === "string"
            ? compressed.body.messages[0].content
            : extractTextContent(compressed.body.messages[0].content);
        const tagged = tagAged("light", text, newContent);
        saved += estimateTokens(text) - estimateTokens(tagged);
        result.push(setContent(msg, tagged));
      } else {
        result.push(msg);
      }
    } else if (distanceFromEnd <= t.moderate) {
      const compressed = cavemanCompress({ messages: [msg] as unknown as Parameters<typeof cavemanCompress>[0]["messages"] }) as CompressedResult;
      if (compressed?.body?.messages?.[0]?.content) {
        const newContent =
          typeof compressed.body.messages[0].content === "string"
            ? compressed.body.messages[0].content
            : extractTextContent(compressed.body.messages[0].content);
        const tagged = tagAged("moderate", text, newContent);
        saved += estimateTokens(text) - estimateTokens(tagged);
        result.push(setContent(msg, tagged));
      } else {
        result.push(msg);
      }
    } else {
      if (msg.role === "assistant") {
        const summary = sum.summarize([msg]);
        const tagged = tagAged("fullSummary", text, summary);
        saved += estimateTokens(text) - estimateTokens(tagged);
        result.push(setContent(msg, tagged));
      } else if (msg.role === "user") {
        const firstLine = text.split("\n")[0]?.slice(0, 120) ?? "";
        const tagged = tagAged("fullSummary", text, firstLine);
        saved += estimateTokens(text) - estimateTokens(tagged);
        result.push(setContent(msg, tagged));
      } else {
        result.push(msg);
      }
    }
  }

  return { messages: result, saved: Math.max(0, saved) };
}

import type { Summarizer, SummarizerOpts } from "./types.ts";

const COMPRESSED_MARKER_RE = /^\[COMPRESSED:/;
const INTENT_TRIGGERS =
  /^(?:request|fix|implement|add|remove|update|refactor|create|delete|change|build)\s*:/i;
const FILE_EXTENSIONS = new Set([
  "ts",
  "tsx",
  "js",
  "jsx",
  "py",
  "md",
  "json",
  "sql",
  "css",
  "html",
  "yaml",
  "yml",
  "sh",
  "rb",
  "go",
  "rs",
  "java",
  "c",
  "cpp",
  "h",
  "hpp",
]);

function stripTokenPunctuation(token: string): string {
  let start = 0;
  let end = token.length;
  const leading = new Set(["'", '"', "`", "(", "[", "{"]);
  const trailing = new Set(["'", '"', "`", ")", "]", "}", ",", ";", ":"]);

  while (start < end && leading.has(token[start])) start++;
  while (end > start && trailing.has(token[end - 1])) end--;

  return token.slice(start, end);
}

function getKnownFilePathToken(token: string): string | null {
  const clean = stripTokenPunctuation(token);
  const lastDot = clean.lastIndexOf(".");
  if (lastDot <= 0 || lastDot === clean.length - 1) return null;

  const extension = clean.slice(lastDot + 1).toLowerCase();
  if (!FILE_EXTENSIONS.has(extension)) return null;
  if (!clean.includes("/") && !clean.includes(".")) return null;

  return clean;
}

function extractFilePathTokens(text: string): string[] {
  const paths: string[] = [];
  for (const token of text.split(/\s+/)) {
    const filePath = getKnownFilePathToken(token);
    if (filePath) paths.push(filePath);
  }
  return paths;
}

function extractErrorSnippets(text: string): string[] {
  const snippets: string[] = [];
  for (const segment of text.split(/[.\n]/)) {
    const trimmed = segment.trim();
    if (!trimmed) continue;

    const lower = trimmed.toLowerCase();
    if (
      trimmed.includes("TypeError:") ||
      trimmed.includes("ReferenceError:") ||
      trimmed.includes("SyntaxError:") ||
      trimmed.includes("RangeError:") ||
      trimmed.includes("URIError:") ||
      trimmed.includes("EvalError:") ||
      trimmed.includes("Error:") ||
      trimmed.includes("Exception:") ||
      lower.includes("error ts")
    ) {
      snippets.push(trimmed);
    }
  }
  return snippets;
}

function extractIntents(messages: Array<{ role: string; content?: string | unknown[] }>): string[] {
  const intents: string[] = [];
  for (const msg of messages) {
    if (msg.role !== "user") continue;
    const text = extractText(msg.content);
    if (!text) continue;
    const firstLine = text.split("\n")[0]?.trim();
    if (firstLine && INTENT_TRIGGERS.test(firstLine)) {
      intents.push(firstLine.slice(0, 120));
    } else if (intents.length === 0 && firstLine) {
      intents.push(firstLine.slice(0, 120));
    }
  }
  return intents;
}

function extractFilePaths(
  messages: Array<{ role: string; content?: string | unknown[] }>
): string[] {
  const paths = new Set<string>();
  for (const msg of messages) {
    const text = extractText(msg.content);
    if (!text) continue;
    const matches = extractFilePathTokens(text);
    for (const m of matches) {
      paths.add(m);
    }
  }
  return [...paths].slice(0, 20);
}

function extractErrors(messages: Array<{ role: string; content?: string | unknown[] }>): string[] {
  const errors: string[] = [];
  for (const msg of messages) {
    const text = extractText(msg.content);
    if (!text) continue;
    for (const match of extractErrorSnippets(text)) errors.push(match.slice(0, 150));
  }
  return errors.slice(0, 10);
}

function extractLastDecision(
  messages: Array<{ role: string; content?: string | unknown[] }>
): string {
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i].role === "assistant") {
      const text = extractText(messages[i].content);
      if (text) return text;
    }
  }
  return "";
}

function trimCodeFences(text: string): string {
  let output = "";
  let cursor = 0;

  while (cursor < text.length) {
    const start = text.indexOf("```", cursor);
    if (start === -1) {
      output += text.slice(cursor);
      break;
    }

    const openingLineEnd = text.indexOf("\n", start + 3);
    if (openingLineEnd === -1) {
      output += text.slice(cursor);
      break;
    }

    const closeStart = text.indexOf("\n```", openingLineEnd + 1);
    if (closeStart === -1) {
      output += text.slice(cursor);
      break;
    }

    const closeEnd = closeStart + 4;
    const opening = text.slice(start, openingLineEnd);
    const code = text.slice(openingLineEnd + 1, closeStart);
    const lines = code.split("\n");

    output += text.slice(cursor, start);
    if (lines.length <= 4) {
      output += text.slice(start, closeEnd);
    } else {
      const head = lines.slice(0, 3).join("\n");
      const tail = lines[lines.length - 1];
      output += `${opening}\n${head}\n…\n${tail}\n\`\`\``;
    }

    cursor = closeEnd;
  }

  return output;
}

function extractText(content?: string | unknown[]): string {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content
      .filter(
        (p): p is { type: string; text?: string } =>
          typeof p === "object" && p !== null && "text" in p
      )
      .map((p) => p.text ?? "")
      .join("\n");
  }
  return "";
}

export class RuleBasedSummarizer implements Summarizer {
  summarize(messages: unknown[], opts?: SummarizerOpts): string {
    const maxLen = opts?.maxLen ?? 2000;
    const preserveCode = opts?.preserveCode ?? true;

    const typed = messages as Array<{ role: string; content?: string | unknown[] }>;

    const filtered = typed.filter((msg) => {
      const text = extractText(msg.content);
      if (!text || text.trim().length === 0) return false;
      return !COMPRESSED_MARKER_RE.test(text);
    });

    if (filtered.length === 0) return "";

    const intents = extractIntents(filtered);
    const files = extractFilePaths(filtered);
    const errors = extractErrors(filtered);
    const decision = extractLastDecision(filtered);

    const parts: string[] = ["[COMPRESSED:summary]"];

    if (intents.length > 0) {
      parts.push(`Intents: ${intents.join("; ")}.`);
    }
    if (files.length > 0) {
      parts.push(`Files touched: ${files.join(", ")}.`);
    }
    if (errors.length > 0) {
      parts.push(`Errors: ${errors.join("; ")}.`);
    }
    if (decision) {
      const processed = preserveCode ? trimCodeFences(decision) : decision;
      parts.push(`Last decision: ${processed.slice(0, 200)}.`);
    }

    let result = parts.join(" ");
    if (result.length > maxLen) {
      result = result.slice(0, maxLen - 3) + "...";
    }

    return result;
  }
}

export function createSummarizer(): Summarizer {
  return new RuleBasedSummarizer();
}

import { pruneByScore } from "./ultraHeuristic.ts";
import { extractPreservedBlocks } from "./preservation.ts";
import { DEFAULT_ULTRA_CONFIG } from "./types.ts";
import type { UltraConfig, CompressionStats, CompressionMode } from "./types.ts";
import { extractTextContent, mapTextContent, type ChatMessageLike } from "./messageContent.ts";
import {
  slmAvailable,
  runLlmlinguaUltra,
  prewarmLlmlinguaUltra,
} from "./engines/llmlingua/ultraEntry.ts";

const COMPRESSED_PREFIX = "[COMPRESSED:";

/**
 * Async sibling of `mapTextContent`: applies an async transform to each text part
 * of a message's content (string content → single call; array content → each
 * `{type:"text"}` part). Non-text parts and structure are preserved exactly.
 */
async function mapTextContentAsync(
  msg: Message,
  fn: (text: string) => Promise<string>
): Promise<Message> {
  if (typeof msg.content === "string") {
    return { ...msg, content: await fn(msg.content) };
  }
  if (Array.isArray(msg.content)) {
    const next: unknown[] = [];
    for (const part of msg.content) {
      const p = part as Record<string, unknown>;
      if (p && p["type"] === "text" && typeof p["text"] === "string") {
        next.push({ ...p, text: await fn(p["text"] as string) });
      } else {
        next.push(part);
      }
    }
    return { ...msg, content: next };
  }
  return msg;
}

/**
 * Prune PROSE only. Fenced code, inline code, URLs, CONST_CASE, versions, etc. are
 * tombstoned by `extractPreservedBlocks` and re-stitched verbatim, so the heuristic
 * NEVER mangles structured content (mirrors caveman.ts / llmlingua/index.ts).
 *
 * Without this, `pruneByScore` tokenizes the whole text and drops low-score tokens
 * (`b)`, `{`, `+`, …) inside code blocks, corrupting them while leaving the fence
 * markers intact — output that looks like valid code but isn't (B-ULTRA-CODE).
 */
function pruneProseOnly(text: string, rate: number, minScore: number): string {
  const { text: withPlaceholders, blocks } = extractPreservedBlocks(text);
  if (blocks.length === 0) return pruneByScore(text, rate, minScore);

  const placeholderToContent = new Map(blocks.map((b) => [b.placeholder, b.content]));
  const escaped = blocks.map((b) => b.placeholder.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const splitRe = new RegExp(`(${escaped.join("|")})`, "g");

  return withPlaceholders
    .split(splitRe)
    .map((part) => {
      if (!part) return "";
      const preserved = placeholderToContent.get(part);
      if (preserved !== undefined) return preserved; // verbatim — never pruned
      return pruneByScore(part, rate, minScore); // prose only
    })
    .join("");
}

/**
 * Compress one prose string with the SLM, preserving code/math/URLs verbatim.
 * Reuses `extractPreservedBlocks` (same tombstoning as `pruneProseOnly`), sends
 * ONLY prose to the worker backend, and re-stitches preserved blocks unchanged.
 * Any backend failure (throw / no-op) falls back to the Tier-A heuristic for that
 * segment, so the SLM NEVER touches structured content and NEVER fails the segment.
 */
/**
 * One compressed prose segment plus whether the SLM (not the heuristic fallback)
 * genuinely produced it. `usedSlm` is what the resolver records the tier from — it
 * must reflect "Tier-B ran", NOT merely "the text changed" (a heuristic-fallback
 * also shrinks the text, so deriving the tier from text inequality would mislabel
 * a fallback as "slm").
 */
interface ProseSlmResult {
  text: string;
  usedSlm: boolean;
}

async function compressProseSlm(text: string, cfg: UltraConfig): Promise<ProseSlmResult> {
  const { text: withPlaceholders, blocks } = extractPreservedBlocks(text);
  if (blocks.length === 0) {
    return slmOrHeuristic(text, cfg);
  }
  const placeholderToContent = new Map(blocks.map((b) => [b.placeholder, b.content]));
  const escaped = blocks.map((b) => b.placeholder.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const splitRe = new RegExp(`(${escaped.join("|")})`, "g");
  const parts = withPlaceholders.split(splitRe);
  const out: string[] = [];
  let usedSlm = false;
  for (const part of parts) {
    if (!part) {
      out.push("");
      continue;
    }
    const preserved = placeholderToContent.get(part);
    if (preserved !== undefined) {
      out.push(preserved); // verbatim — never sent to the model
    } else {
      const seg = await slmOrHeuristic(part, cfg);
      out.push(seg.text);
      if (seg.usedSlm) usedSlm = true;
    }
  }
  return { text: out.join(""), usedSlm };
}

/**
 * Run the SLM on a prose segment; on throw/no-op, fall back to the Tier-A pruner for it.
 * `usedSlm` is true ONLY when the SLM backend itself produced the output.
 */
async function slmOrHeuristic(prose: string, cfg: UltraConfig): Promise<ProseSlmResult> {
  try {
    const text = await runLlmlinguaUltra(prose, {
      model: cfg.modelPath ? undefined : undefined,
      compressionRate: cfg.compressionRate,
      modelPath: cfg.modelPath,
    });
    return { text, usedSlm: true };
  } catch {
    return { text: pruneByScore(prose, cfg.compressionRate, cfg.minScoreThreshold), usedSlm: false };
  }
}

export interface UltraCompressResult {
  messages: Array<{ role: string; content?: string | unknown[]; [key: string]: unknown }>;
  stats: CompressionStats;
}

type Message = ChatMessageLike;

/** Tier the ultra resolver records on the stats. */
export type UltraTier = "slm" | "heuristic-fallback" | "heuristic";

/**
 * Tier-A heuristic ultra (PURE, SYNCHRONOUS). Identical to the pre-B behaviour.
 * Used directly by the stacked sync engine (`cavemanAdapter`) and as the fallback
 * tier inside `ultraCompress`. `tier` lets the async resolver tag the resolved
 * tier as either "heuristic" (chosen directly) or "heuristic-fallback" (SLM failed).
 */
export function ultraCompressHeuristic(
  messages: Message[],
  config: Partial<UltraConfig> = {},
  tier: UltraTier = "heuristic"
): UltraCompressResult {
  const start = Date.now();
  const effectiveConfig: UltraConfig = {
    ...DEFAULT_ULTRA_CONFIG,
    ...config,
  };
  const { compressionRate, minScoreThreshold, maxTokensPerMessage } = effectiveConfig;

  let originalChars = 0;
  let compressedChars = 0;

  const compressed = messages.map((msg) => {
    if (effectiveConfig.preserveSystemPrompt !== false && msg.role === "system") return msg;
    const text = extractTextContent(msg.content);
    if (!text) return msg;
    if (text.startsWith(COMPRESSED_PREFIX)) return msg;
    if (maxTokensPerMessage > 0 && Math.ceil(text.length / 4) <= maxTokensPerMessage) {
      return msg;
    }

    let messageOriginalChars = 0;
    let messageCompressedChars = 0;
    const next = mapTextContent(msg, (textPart) => {
      if (!textPart || textPart.startsWith(COMPRESSED_PREFIX)) return textPart;
      messageOriginalChars += textPart.length;
      const pruned = pruneProseOnly(textPart, compressionRate, minScoreThreshold);
      messageCompressedChars += pruned.length;
      return pruned;
    }) as Message;
    originalChars += messageOriginalChars;
    compressedChars += messageCompressedChars;
    return next;
  });

  const originalTokens = Math.ceil(originalChars / 4);
  const compressedTokens = Math.ceil(compressedChars / 4);
  const savingsPercent =
    originalTokens > 0
      ? Math.round(((originalTokens - compressedTokens) / originalTokens) * 100 * 10) / 10
      : 0;

  const stats: CompressionStats = {
    originalTokens,
    compressedTokens,
    savingsPercent,
    techniquesUsed: ["ultra-heuristic-pruning"],
    mode: "ultra" as CompressionMode,
    timestamp: Date.now(),
    durationMs: Date.now() - start,
    ultraTier: tier,
  };

  return { messages: compressed, stats };
}

/**
 * Ultra compression with the two-tier resolver (Phase 4, Sub-project B).
 *
 * - `ultraEngine: "slm"` AND `slmAvailable()` → route prose through the SLM worker
 *   backend (Tier-B). On timeout / worker error / load failure / no-op → fall back
 *   to the Tier-A heuristic for THIS request and record "heuristic-fallback".
 * - otherwise → Tier-A heuristic ("heuristic").
 *
 * The structure-preservation wrapper (`extractPreservedBlocks` / re-stitch, inside
 * `pruneProseOnly` for Tier-A and `splitProseAndPreserved` inside the worker engine
 * path for Tier-B) wraps BOTH tiers, so code/math/URLs stay verbatim regardless.
 * A request is NEVER failed or left uncompressed because the SLM was unavailable.
 */
export async function ultraCompress(
  messages: Message[],
  config: Partial<UltraConfig> & { ultraEngine?: "heuristic" | "slm" } = {}
): Promise<UltraCompressResult> {
  if (config.ultraEngine !== "slm" || !slmAvailable()) {
    return ultraCompressHeuristic(messages, config, "heuristic");
  }

  const start = Date.now();
  const effectiveConfig: UltraConfig = { ...DEFAULT_ULTRA_CONFIG, ...config };
  const { maxTokensPerMessage } = effectiveConfig;

  let originalChars = 0;
  let compressedChars = 0;
  let anySlm = false;

  try {
    const compressed: Message[] = [];
    for (const msg of messages) {
      if (effectiveConfig.preserveSystemPrompt !== false && msg.role === "system") {
        compressed.push(msg);
        continue;
      }
      const text = extractTextContent(msg.content);
      if (!text || text.startsWith(COMPRESSED_PREFIX)) {
        compressed.push(msg);
        continue;
      }
      if (maxTokensPerMessage > 0 && Math.ceil(text.length / 4) <= maxTokensPerMessage) {
        compressed.push(msg);
        continue;
      }

      let messageOriginalChars = 0;
      let messageCompressedChars = 0;
      const next = (await mapTextContentAsync(msg, async (textPart) => {
        if (!textPart || textPart.startsWith(COMPRESSED_PREFIX)) return textPart;
        messageOriginalChars += textPart.length;
        const { text: out, usedSlm } = await compressProseSlm(textPart, effectiveConfig);
        if (usedSlm) anySlm = true;
        messageCompressedChars += out.length;
        return out;
      })) as Message;
      originalChars += messageOriginalChars;
      compressedChars += messageCompressedChars;
      compressed.push(next);
    }

    const originalTokens = Math.ceil(originalChars / 4);
    const compressedTokens = Math.ceil(compressedChars / 4);
    const savingsPercent =
      originalTokens > 0
        ? Math.round(((originalTokens - compressedTokens) / originalTokens) * 100 * 10) / 10
        : 0;

    const stats: CompressionStats = {
      originalTokens,
      compressedTokens,
      savingsPercent,
      techniquesUsed: anySlm ? ["ultra-slm"] : ["ultra-heuristic-pruning"],
      mode: "ultra" as CompressionMode,
      timestamp: Date.now(),
      durationMs: Date.now() - start,
      ultraTier: anySlm ? "slm" : "heuristic-fallback",
    };
    return { messages: compressed, stats };
  } catch {
    // Any unexpected error in the SLM path → whole-request fail-open to Tier-A.
    return ultraCompressHeuristic(messages, config, "heuristic-fallback");
  }
}

/**
 * Pure decision: should the ultra SLM model be pre-warmed for this config?
 * True only when the SLM tier is selected AND pre-warm is enabled. The CALLER
 * decides timing (enable-transition or cold-start) and fires `prewarmLlmlinguaUltra`
 * best-effort; this helper stays clock-free / side-effect-free.
 */
export function shouldPrewarmUltraSlm(config: {
  ultraEngine?: "heuristic" | "slm";
  ultraSlmPrewarm?: boolean;
}): boolean {
  return config.ultraEngine === "slm" && config.ultraSlmPrewarm === true;
}

/**
 * Best-effort: when the resolved config selects the SLM tier WITH pre-warm,
 * trigger a single warm call. Awaitable for tests; call sites fire-and-forget
 * (`void maybePrewarmUltraSlmOnConfig(cfg)`). Never throws.
 */
export async function maybePrewarmUltraSlmOnConfig(config: {
  ultraEngine?: "heuristic" | "slm";
  ultraSlmPrewarm?: boolean;
}): Promise<void> {
  if (!shouldPrewarmUltraSlm(config)) return;
  try {
    await prewarmLlmlinguaUltra();
  } catch {
    // best-effort
  }
}

/**
 * LLMLingua-2 entry point for the `ultra` mode (Phase 4, Sub-project B).
 *
 * A THIN wrapper over the existing worker backend (`./worker.ts`) — no new ONNX
 * integration. It adds exactly what the `ultra` two-tier resolver needs:
 *   - `slmAvailable()` — cached, NON-BLOCKING probe (reuses the worker's memoized
 *     optional-deps gate). It NEVER loads a model; an actual load happens lazily
 *     inside the worker under its first-call timeout.
 *   - `runLlmlinguaUltra(text, opts)` — compress ONE prose string. Throws when the
 *     backend fail-opens to the original text (no-op), so the ultra resolver can
 *     fall through to the Tier-A heuristic and record "heuristic-fallback".
 *   - `prewarmLlmlinguaUltra()` — best-effort warm call (errors swallowed).
 *
 * The structure-preservation split (code/math/URLs never reach the model) is done
 * by the CALLER (`ultra.ts`), exactly as the heuristic path already does — this
 * entry only sees prose.
 */

import { workerBackend, depsAvailable } from "./worker.ts";
import { DEFAULT_LLMLINGUA_MODEL } from "./constants.ts";

/** Cached probe result. null = not probed yet. */
let _slmAvailable: boolean | null = null;

// ─── test-only injectable hooks ─────────────────────────────────────────────
interface UltraSlmTestHooks {
  available?: boolean;
  run?: (text: string, opts?: UltraSlmOptions) => Promise<string>;
}
let _testHooks: UltraSlmTestHooks | null = null;

/** Test-only: override availability + the per-prose run, to avoid loading a real model. */
export function __setUltraSlmTestHooks(hooks: UltraSlmTestHooks): void {
  _testHooks = hooks;
}

/**
 * Cheap, cached, non-blocking probe: are the optional SLM deps installed?
 * Reuses the worker's memoized `depsAvailable()` (a filesystem manifest check),
 * so it never spawns a worker or loads a model.
 */
export function slmAvailable(): boolean {
  if (_testHooks && typeof _testHooks.available === "boolean") return _testHooks.available;
  if (_slmAvailable !== null) return _slmAvailable;
  _slmAvailable = depsAvailable();
  return _slmAvailable;
}

/** Options the ultra SLM tier threads to the worker backend. */
export interface UltraSlmOptions {
  model?: string;
  compressionRate?: number;
  modelPath?: string;
}

/**
 * Compress ONE prose string via the SLM worker backend.
 *
 * The worker backend is strictly fail-open: on missing deps / spawn error /
 * model-load or inference error / per-call timeout it returns the ORIGINAL text.
 * We treat a returned no-op (output not shorter than input) as a FAILURE and
 * throw, so the ultra resolver falls back to Tier-A and records the fallback.
 */
export async function runLlmlinguaUltra(text: string, opts?: UltraSlmOptions): Promise<string> {
  if (_testHooks?.run) {
    const out = await _testHooks.run(text, opts);
    if (typeof out !== "string" || out.length >= text.length) {
      throw new Error("llmlingua-ultra: backend produced no gain");
    }
    return out;
  }
  const out = await workerBackend(text, {
    model: opts?.model,
    compressionRate: opts?.compressionRate,
    modelPath: opts?.modelPath,
  });
  if (typeof out !== "string" || out.length >= text.length) {
    // Fail-open / no-op from the worker → let the caller fall back to heuristic.
    throw new Error("llmlingua-ultra: backend produced no gain");
  }
  return out;
}

/**
 * Best-effort pre-warm: ask the worker to load the model once on a short prose
 * sample. NEVER throws — any failure is swallowed (the lazy first-call path still
 * applies on the next real request). Returns true if a warm call was attempted.
 */
export async function prewarmLlmlinguaUltra(opts?: UltraSlmOptions): Promise<boolean> {
  if (!slmAvailable()) return false;
  try {
    // A small but non-trivial sample so the worker triggers a real model load.
    // Route through `runLlmlinguaUltra` so the same backend seam (and test hook)
    // is exercised; a no-op/throw from the worker is fine here (best-effort).
    await runLlmlinguaUltra(
      "The quick brown fox jumps over the lazy dog while the sun sets behind the hills.",
      { model: opts?.model ?? DEFAULT_LLMLINGUA_MODEL, compressionRate: opts?.compressionRate }
    );
  } catch {
    // swallow — pre-warm is best-effort (a no-op/throw from the worker is fine).
  }
  return true;
}

/** Test-only: reset the cached probe + injected hooks. */
export function __resetUltraEntryForTests(): void {
  _slmAvailable = null;
  _testHooks = null;
}

/**
 * LLMLingua-2 worker-thread backend (production path).
 *
 * Real MobileBERT/BERT ONNX inference via `@atjsh/llmlingua-2` running in a
 * `worker_threads.Worker` (`./onnxWorker.ts`). The backend stays STRICTLY
 * fail-open: any failure to resolve deps, spawn the worker, load the model, or
 * classify tokens returns the ORIGINAL text unchanged — never throws to the caller.
 *
 * ## Fail-open paths
 *  1. Optional-deps gate: if any of `@atjsh/llmlingua-2`, `@huggingface/transformers`,
 *     `@tensorflow/tfjs`, `js-tiktoken` does not resolve, return `text` immediately —
 *     NO worker spawn. This is the default in CI / most installs (deps are OPTIONAL).
 *  2. Per-call timeout: first call for a model gets `FIRST_CALL_TIMEOUT_MS` (one-time
 *     model load); warm calls get `LLMLINGUA_WORKER_TIMEOUT_MS`. On timeout → original
 *     text (the worker keeps loading and will warm for the next call).
 *  3. Worker error/exit → resolve all pending with their original text + respawn next.
 *
 * ## Serialization
 *  ONNX/tfjs are not reentrant — calls are queued FIFO and only one message is
 *  in-flight at a time (the next is posted after the previous reply or its timeout).
 *
 * ## Idle eviction
 *  After `LLMLINGUA_WORKER_IDLE_MS` with no calls, the worker is terminated and the
 *  singleton reset (next call respawns). The idle timer is `unref`'d so it never keeps
 *  the process alive.
 *
 * Code blocks NEVER reach this backend — the engine (index.ts) tombstones preserved
 * constructs first; this backend sees prose-only segments.
 *
 * VPS validation (Hard Rule #18): the real model is exercised behind RUN_LLMLINGUA_INT.
 */

import { Worker } from "node:worker_threads";
import path from "node:path";
import fs from "node:fs";
import { pathToFileURL } from "node:url";

import { LLMLINGUA_WORKER_TIMEOUT_MS, LLMLINGUA_WORKER_IDLE_MS } from "./constants.ts";
import { resolveLlmlinguaModel } from "./modelStore.ts";
import type { LlmlinguaBackend } from "./index.ts";

/** One-time model-load budget on the first call for a given model (tinybert ~2s, bert-base ~27s). */
const FIRST_CALL_TIMEOUT_MS = 60000;

/**
 * Gate probe: `@atjsh/llmlingua-2` is the entry package that declares the others
 * (`@huggingface/transformers`, `@tensorflow/tfjs`, `js-tiktoken`) as peers. We probe
 * ONLY it (by manifest existence) because the peers are ESM-only and `require.resolve`
 * throws for them even when installed; the worker still fail-opens if a peer is
 * genuinely missing at `import()` time.
 *
 * ⚠️ We do NOT use `createRequire(import.meta.url).resolve()` nor any other
 * `import.meta.url`-based resolution: the Next.js standalone bundle (webpack) replaces
 * `createRequire(import.meta.url)` with a stub module that ALWAYS throws
 * `MODULE_NOT_FOUND` and freezes `import.meta.url` to the build-machine path, so such a
 * gate is always false / mis-anchored in production (B-SLM). We probe the filesystem
 * from runtime anchors that survive the bundle instead.
 */
const GATE_DEP_REL = path.join("node_modules", "@atjsh", "llmlingua-2", "package.json");

/** Relative path (from an install root) to the esbuild'd / source worker entry. */
const WORKER_JS_REL = path.join(
  "open-sse",
  "services",
  "compression",
  "engines",
  "llmlingua",
  "onnxWorker.js"
);
const WORKER_TS_REL = path.join(
  "open-sse",
  "services",
  "compression",
  "engines",
  "llmlingua",
  "onnxWorker.ts"
);

const MAX_WALK_UP = 8;

/**
 * Walk up from each anchor directory (≤ MAX_WALK_UP levels) and return the first
 * ancestor that actually contains `relPath`, or null. Pure + exported for tests.
 *
 * This deliberately avoids `import.meta.url`/`__dirname` (both dead in the standalone
 * bundle) — see the GATE_DEP_REL comment.
 */
export function firstAncestorWith(anchors: string[], relPath: string): string | null {
  for (const anchor of anchors) {
    if (!anchor) continue;
    let dir = path.resolve(anchor);
    for (let i = 0; i <= MAX_WALK_UP; i++) {
      if (fs.existsSync(path.join(dir, relPath))) return dir;
      const parent = path.dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  }
  return null;
}

/**
 * Runtime install-root anchors that SURVIVE the standalone bundle:
 *  - `process.cwd()` — `dist/server.js` runs `process.chdir(__dirname)` → the dist root.
 *  - `dirname(process.argv[1])` — the entry script (server.js / bin), walked up.
 */
function runtimeAnchors(): string[] {
  const anchors = [process.cwd()];
  const argv1 = process.argv[1];
  if (typeof argv1 === "string" && argv1) anchors.push(path.dirname(argv1));
  return anchors;
}

// ─── optional-deps gate (memoized) ──────────────────────────────────────────────

let _depsAvailable: boolean | null = null;

/**
 * Lazily (and once) check whether the optional LLMLingua dependency stack is installed,
 * by probing `node_modules/@atjsh/llmlingua-2/package.json` from the runtime anchors.
 */
export function depsAvailable(): boolean {
  if (_depsAvailable !== null) return _depsAvailable;
  _depsAvailable = firstAncestorWith(runtimeAnchors(), GATE_DEP_REL) !== null;
  return _depsAvailable;
}

// ─── worker reply / queue plumbing ──────────────────────────────────────────────

interface WorkerReply {
  id: number;
  ok: boolean;
  text: string;
}

interface PendingEntry {
  resolve: (s: string) => void;
  timer: NodeJS.Timeout;
  /** Stored so error/exit/reset handlers can fail-open with the ORIGINAL text. */
  originalText: string;
  /** Resolved model id — used to mark the model warm ONLY on a genuine success. */
  modelKey: string;
}

interface QueueItem {
  text: string;
  opts: Parameters<LlmlinguaBackend>[1];
  resolve: (s: string) => void;
}

let worker: Worker | null = null;
let nextId = 1;
const pending = new Map<number, PendingEntry>();
const queue: QueueItem[] = [];
let busy = false;
/** Model keys (resolved `id`) that have completed at least one successful load. */
const warmedModels = new Set<string>();
let idleTimer: NodeJS.Timeout | null = null;

/**
 * Resolve the worker entry file across dev and prod WITHOUT `import.meta.url`.
 *
 * Prod: the worker is esbuild'd to `<distRoot>/open-sse/.../onnxWorker.js`
 * (scripts/build/prepublish.ts) + kept by the pack-artifact allowlist. The install
 * root is found by walking up the runtime anchors (cwd / argv[1] dir), since the
 * bundled module location (`import.meta.url`) is frozen to the build machine.
 *
 * Dev (tsx): the same relative path resolves to the `.ts` source under the project
 * root (cwd) and runs via the tsx loader.
 *
 * First existing candidate wins; a `.js` choice runs natively, a `.ts` choice gets the
 * tsx loader. Exported for tests.
 */
export function resolveWorkerFile(): { workerFile: string; execArgv: string[] } {
  const anchors = runtimeAnchors();

  // Prod first: the esbuild'd .js under the install root.
  const jsRoot = firstAncestorWith(anchors, WORKER_JS_REL);
  if (jsRoot) return { workerFile: path.join(jsRoot, WORKER_JS_REL), execArgv: [] };

  // Dev: the .ts source (tsx loader).
  const tsRoot = firstAncestorWith(anchors, WORKER_TS_REL);
  if (tsRoot)
    return { workerFile: path.join(tsRoot, WORKER_TS_REL), execArgv: ["--import", "tsx/esm"] };

  // Nothing found — return a cwd-relative .js path; the spawn will fail-open.
  return { workerFile: path.join(process.cwd(), WORKER_JS_REL), execArgv: [] };
}

/** Reset the idle eviction timer; terminates the worker after the idle window. */
function bumpIdleTimer(): void {
  if (idleTimer) clearTimeout(idleTimer);
  idleTimer = setTimeout(() => {
    resetWorker();
  }, LLMLINGUA_WORKER_IDLE_MS);
  // Never keep the process alive just for idle eviction.
  if (typeof idleTimer.unref === "function") idleTimer.unref();
}

/** Tear down the worker + all runtime state (fail-open any pending). Next call respawns. */
function resetWorker(): void {
  const w = worker;
  worker = null;
  if (idleTimer) {
    clearTimeout(idleTimer);
    idleTimer = null;
  }
  // Fail-open every in-flight call with its ORIGINAL text.
  for (const [, entry] of pending) {
    clearTimeout(entry.timer);
    entry.resolve(entry.originalText);
  }
  pending.clear();
  busy = false;
  warmedModels.clear();
  if (w) {
    try {
      void w.terminate();
    } catch {
      // ignore terminate errors
    }
  }
}

/** Spawn the singleton worker and wire its message/error/exit handlers. */
function ensureWorker(): Worker {
  if (worker) return worker;

  const { workerFile, execArgv } = resolveWorkerFile();
  const absoluteWorkerFile = path.resolve(workerFile);
  const w = new Worker(pathToFileURL(absoluteWorkerFile).href, { execArgv });

  w.on("message", (reply: WorkerReply) => {
    const entry = pending.get(reply.id);
    if (entry) {
      clearTimeout(entry.timer);
      pending.delete(reply.id);
      // Only a genuine success warms the model so later calls use the short timeout.
      // A timeout/error/fail-open MUST NOT warm it (else a still-loading model would
      // be starved of its one-time load budget on the next call).
      if (reply.ok) warmedModels.add(entry.modelKey);
      // ok:false already carries the ORIGINAL text → resolving with it IS fail-open.
      entry.resolve(reply.text);
    }
    busy = false;
    pump();
  });

  const failOpenAndRespawn = () => {
    // Resolve every pending entry fail-open, then drop the worker so the next call respawns.
    failAllPending();
    if (worker === w) worker = null;
    busy = false;
  };

  w.on("error", failOpenAndRespawn);
  w.on("exit", failOpenAndRespawn);

  worker = w;
  return w;
}

/** Resolve all pending entries with their stored fail-open value (original text). */
function failAllPending(): void {
  for (const [id, entry] of pending) {
    clearTimeout(entry.timer);
    pending.delete(id);
    entry.resolve(entry.originalText);
  }
}

/** Post the next queued item to the worker (one in-flight at a time). */
function pump(): void {
  if (busy) return;
  const item = queue.shift();
  if (!item) return;

  busy = true;
  bumpIdleTimer();

  let w: Worker;
  try {
    w = ensureWorker();
  } catch {
    // Spawn failed → fail-open this item and continue draining the queue.
    busy = false;
    item.resolve(item.text);
    pump();
    return;
  }

  const id = nextId++;
  const modelKey = resolveLlmlinguaModel(item.opts?.model).id;
  const warm = warmedModels.has(modelKey);
  const timeoutMs = warm ? LLMLINGUA_WORKER_TIMEOUT_MS : FIRST_CALL_TIMEOUT_MS;

  const timer = setTimeout(() => {
    // Timeout → fail-open with the ORIGINAL text; drop the pending entry but keep the
    // worker (it may still be loading the model and will warm for the next call).
    const entry = pending.get(id);
    if (entry) {
      pending.delete(id);
      entry.resolve(item.text);
    }
    busy = false;
    pump();
  }, timeoutMs);
  if (typeof timer.unref === "function") timer.unref();

  pending.set(id, {
    // Warming is decided by the reply handler (success only) — not here, so a
    // timeout/error fail-open never marks the model warm.
    resolve: item.resolve,
    timer,
    originalText: item.text,
    modelKey,
  });

  try {
    w.postMessage({
      id,
      text: item.text,
      model: item.opts?.model,
      compressionRate: item.opts?.compressionRate,
      modelPath: item.opts?.modelPath,
    });
  } catch {
    // postMessage failed → fail-open this item and respawn.
    clearTimeout(timer);
    pending.delete(id);
    item.resolve(item.text);
    if (worker === w) worker = null;
    busy = false;
    pump();
  }
}

// ─── public backend ─────────────────────────────────────────────────────────────

/**
 * Production worker backend. Two-arg `LlmlinguaBackend` (text, opts).
 *
 * Returns the compressed prose on success; the ORIGINAL `text` on any failure
 * (missing deps, spawn error, model-load/inference error, timeout). NEVER throws.
 */
export const workerBackend: LlmlinguaBackend = async (text, opts) => {
  // Fail-open WITHOUT spawning when the optional deps are not installed (the common case).
  if (!depsAvailable()) {
    return text;
  }

  return new Promise<string>((resolve) => {
    queue.push({ text, opts, resolve });
    pump();
  });
};

// ─── test-only reset ────────────────────────────────────────────────────────────

/**
 * Internal: terminate the worker (if any) and reset all module state so the
 * process can exit cleanly after tests. Not part of the public contract.
 */
export function __resetLlmlinguaWorkerForTests(): void {
  // Drain the queue fail-open so no callers hang.
  while (queue.length) {
    const item = queue.shift()!;
    item.resolve(item.text);
  }
  resetWorker();
  _depsAvailable = null;
  nextId = 1;
}

/**
 * LLMLingua real-engine constants — pure data + types.
 *
 * NO imports of native deps (transformers.js, onnxruntime, etc). This module is
 * safe to import from anywhere (main thread, worker, tests) without pulling in
 * the heavy ONNX runtime.
 *
 * The real backend uses `@atjsh/llmlingua-2` (ONNX via `@huggingface/transformers`),
 * which downloads models from the HuggingFace Hub into a cache dir. Only the two
 * models PROVEN to work end-to-end are registered here.
 */

export type LlmlinguaFactory = "WithBERTMultilingual" | "WithXLMRoBERTa";

export interface LlmlinguaModelEntry {
  /** config value, e.g. "tinybert" */
  id: string;
  /** HuggingFace Hub repo id */
  hfRepo: string;
  factory: LlmlinguaFactory;
  dtype: "fp32";
  /** transformers.js subfolder option; "" for both proven models */
  subfolder: string;
  sizeMB: number;
  label: string;
}

export const DEFAULT_LLMLINGUA_MODEL = "tinybert";

/** Registry keyed by config `model` value. Only the two PROVEN models. */
export const LLMLINGUA_MODELS: Record<string, LlmlinguaModelEntry> = {
  tinybert: {
    id: "tinybert",
    hfRepo: "atjsh/llmlingua-2-js-tinybert-meetingbank",
    factory: "WithBERTMultilingual",
    dtype: "fp32",
    subfolder: "",
    sizeMB: 57,
    label: "TinyBERT (57MB, fast — default)",
  },
  "bert-base": {
    id: "bert-base",
    hfRepo: "Arcoldd/llmlingua4j-bert-base-onnx",
    factory: "WithBERTMultilingual",
    dtype: "fp32",
    subfolder: "",
    sizeMB: 710,
    label: "BERT-base (710MB, higher accuracy)",
  },
};

/** Per-call worker reply timeout → fail-open. */
export const LLMLINGUA_WORKER_TIMEOUT_MS = 5000;
/** Terminate the idle worker after this long to free model RAM. */
export const LLMLINGUA_WORKER_IDLE_MS = 300000;

/**
 * LLMLingua model store — thin path/config resolver.
 *
 * transformers.js owns the actual model download (from the HuggingFace Hub into
 * its `cacheDir`). This module only resolves the cache directory, maps config
 * model ids to registry entries, and configures a transformers.js `env` object
 * for either Hub download (default) or a local modelPath override.
 *
 * Deliberately does NOT import the native `@huggingface/transformers` dep — it
 * accepts a minimal structural `env` so the heavy runtime stays out of this path.
 */

import os from "node:os";
import path from "node:path";
import fs from "node:fs";
import {
  DEFAULT_LLMLINGUA_MODEL,
  LLMLINGUA_MODELS,
  type LlmlinguaModelEntry,
} from "./constants.ts";

/** A minimal structural type for the transformers.js `env` object (avoids importing the native dep here). */
export interface TransformersEnvLike {
  cacheDir?: string;
  localModelPath?: string;
  allowRemoteModels?: boolean;
  [key: string]: unknown;
}

/** Base data dir. Mirrors rtk's getDataDir() at engines/rtk/filterLoader.ts. */
function getDataDir(): string {
  return process.env.DATA_DIR || path.join(os.homedir(), ".omniroute");
}

/** Resolve (and ensure) the model cache dir: `${DATA_DIR}/models/llmlingua`. Mirrors rtk's getDataDir(). */
export function getLlmlinguaModelCacheDir(): string {
  const dir = path.join(getDataDir(), "models", "llmlingua");
  try {
    fs.mkdirSync(dir, { recursive: true });
  } catch {
    // Ignore mkdir errors — fail-open philosophy: transformers.js will surface a
    // clearer error if the dir is genuinely unusable, and callers fail-open anyway.
  }
  return dir;
}

/** Resolve a config model id to its registry entry; falls back to the default for unknown/empty ids. */
export function resolveLlmlinguaModel(modelId: string | undefined | null): LlmlinguaModelEntry {
  if (typeof modelId === "string" && modelId.length > 0 && LLMLINGUA_MODELS[modelId]) {
    return LLMLINGUA_MODELS[modelId];
  }
  return LLMLINGUA_MODELS[DEFAULT_LLMLINGUA_MODEL];
}

/** Configure a transformers.js `env` for either Hub download (default) or a local modelPath override. */
export function configureTransformersEnv(
  env: TransformersEnvLike,
  opts: { modelPath?: string }
): void {
  env.cacheDir = getLlmlinguaModelCacheDir();
  if (typeof opts.modelPath === "string" && opts.modelPath.length > 0) {
    env.localModelPath = opts.modelPath;
    env.allowRemoteModels = false;
  } else {
    env.allowRemoteModels = true;
  }
}

/**
 * Aggregate guards for the stacked compression pipeline (T02 / Headroom H1).
 *
 * These operate on the WHOLE pipeline result, distinct from the opt-in per-step TV1 bail-out
 * (`decideStep` in `strategySelector.ts`): TV1 governs whether to ADVANCE between steps and is
 * default-off; the inflation guard here is an honest DEFAULT-ON check on the FINAL output.
 */

import type { CompressionResult, CompressionStats } from "./types.ts";

export interface PipelineInflationInput {
  /** The verbatim request body before any engine ran. */
  originalBody: Record<string, unknown>;
  /** The fully-stacked body after the pipeline ran. */
  compressedBody: Record<string, unknown>;
  /** Token count of `originalBody` (already measured by the stats pass). */
  originalTokens: number;
  /** Token count of `compressedBody` (already measured by the stats pass). */
  compressedTokens: number;
}

export interface PipelineInflationResult {
  /** The body to actually use: the original when the pipeline did not shrink it. */
  body: Record<string, unknown>;
  /** True when the stacked output did not shrink the input, so the original was kept. */
  inflated: boolean;
}

/**
 * Honest aggregate inflation guard. Only genuine INFLATION — the fully-stacked body is strictly
 * LARGER than the original (`compressedTokens > originalTokens`) — discards the compressed body and
 * returns the verbatim original.
 *
 * A net-zero result (`compressedTokens === originalTokens`) is a NO-OP, not inflation: a structural
 * engine (e.g. `ccr`, `session-dedup`) that found no candidate returns the body unchanged, so its
 * token count equals the original. That is zero savings, not a revert — flagging it as inflation
 * would emit a misleading "did not shrink; reverted to original" warning for an engine that never
 * touched the payload. Equality therefore must NOT trip the guard.
 *
 * Safe by construction: the only alternative it ever returns is `originalBody`, the unmodified
 * request, which is always a valid payload. A (rare) false trigger therefore can never corrupt a
 * payload — it only forgoes a compression that saved nothing.
 *
 * `originalTokens === 0` (empty/degenerate input) is treated as "not inflated" so an empty body is
 * never spuriously flagged.
 */
export function guardPipelineInflation(input: PipelineInflationInput): PipelineInflationResult {
  const { originalTokens, compressedTokens } = input;
  if (originalTokens > 0 && compressedTokens > originalTokens) {
    return { body: input.originalBody, inflated: true };
  }
  return { body: input.compressedBody, inflated: false };
}

/**
 * Applies the aggregate inflation guard to a finalized stacked-pipeline `stats` object, honoring
 * the `compressed` loop-level flag (#6480). If the fully-stacked body did not actually shrink
 * (its token count is >= the original), discards it and returns the verbatim original — safe by
 * construction, since the original request body is always a valid payload.
 *
 * Only meaningful when some step actually advanced `currentBody` (`compressed === true`). When
 * no step in the pipeline ever produced/advanced a candidate (e.g. a single no-op engine on an
 * out-of-charter payload), `currentBody` is still reference-identical to `originalBody`, so
 * tokens are trivially equal — running the guard in that case would mislabel a genuine no-op as
 * a "reverted" fallback (`fallbackApplied: true` + a misleading warning) even though nothing was
 * ever computed to revert.
 */
export function applyStackedInflationGuard(
  originalBody: Record<string, unknown>,
  currentBody: Record<string, unknown>,
  compressed: boolean,
  stats: CompressionStats
): CompressionResult {
  if (!compressed) return { body: currentBody, compressed, stats };

  const inflation = guardPipelineInflation({
    originalBody,
    compressedBody: currentBody,
    originalTokens: stats.originalTokens,
    compressedTokens: stats.compressedTokens,
  });
  if (!inflation.inflated) return { body: currentBody, compressed, stats };

  const inflatedTokens = stats.compressedTokens;
  const warnings = new Set(stats.validationWarnings ?? []);
  warnings.add(
    `pipeline-inflation-guard: stacked output (${inflatedTokens} tok) did not shrink input ` +
      `(${stats.originalTokens} tok); reverted to original`
  );
  stats.validationWarnings = Array.from(warnings);
  stats.fallbackApplied = true;
  stats.compressedTokens = stats.originalTokens;
  stats.savingsPercent = 0;
  return { body: inflation.body, compressed: false, stats };
}

/**
 * T02 — pipeline engine circuit-breaker (gaps v3.8.42; opt-in, default OFF).
 *
 * A lightweight, in-memory, per-engine breaker for the stacked compression pipeline. When an
 * engine throws repeatedly ACROSS requests, the breaker opens for that engine id and the
 * stacked loops skip it (keeping the body verbatim for that step — fail-open) until a cooldown
 * elapses, then probe once (lazy half-open). Success closes it; a failed probe re-opens it.
 *
 * This is deliberately NOT the provider breaker (`src/shared/utils/circuitBreaker.ts`), which
 * is provider-scoped and DB-persisted. This one is engine-scoped, process-local, and adds zero
 * DB/IO on the hot path. It composes with — but is independent of — the TV1 per-request bail-out
 * (which skips within a single request); the breaker adds cross-request memory.
 *
 * Default OFF: with `enabled:false` the stacked loops never consult or mutate this state, so
 * behavior is byte-identical to the pre-breaker pipeline (a throwing engine still propagates
 * unless TV1 bail-out is separately enabled).
 */

export interface PipelineCircuitBreakerConfig {
  /** Master switch. Default false — the pipeline never consults the breaker when off. */
  enabled: boolean;
  /** Consecutive cross-request failures before an engine's breaker opens. Default 3. */
  failureThreshold: number;
  /** How long the breaker stays open before a half-open probe (ms). Default 30_000. */
  cooldownMs: number;
}

export const DEFAULT_PIPELINE_BREAKER: PipelineCircuitBreakerConfig = {
  enabled: false,
  failureThreshold: 3,
  cooldownMs: 30_000,
};

interface EngineBreakerState {
  failures: number;
  /** Epoch ms until which the engine is OPEN; null = CLOSED. */
  openedUntil: number | null;
}

const _state = new Map<string, EngineBreakerState>();

function get(engine: string): EngineBreakerState {
  let s = _state.get(engine);
  if (!s) {
    s = { failures: 0, openedUntil: null };
    _state.set(engine, s);
  }
  return s;
}

function toNonNegativeInt(raw: string | undefined, fallback: number): number {
  if (raw === undefined) return fallback;
  const n = Number(raw);
  return Number.isFinite(n) && n >= 0 ? Math.floor(n) : fallback;
}

/**
 * Resolve the breaker config from a partial (per-combo config) with env fallback. Env keys:
 * `COMPRESSION_PIPELINE_BREAKER_ENABLED|_THRESHOLD|_COOLDOWN_MS`. The partial wins over env.
 */
export function resolvePipelineBreakerConfig(
  partial?: Partial<PipelineCircuitBreakerConfig>,
  env: NodeJS.ProcessEnv = process.env
): PipelineCircuitBreakerConfig {
  const enabled = partial?.enabled ?? env.COMPRESSION_PIPELINE_BREAKER_ENABLED === "true";
  const failureThreshold =
    partial?.failureThreshold ??
    toNonNegativeInt(
      env.COMPRESSION_PIPELINE_BREAKER_THRESHOLD,
      DEFAULT_PIPELINE_BREAKER.failureThreshold
    );
  const cooldownMs =
    partial?.cooldownMs ??
    toNonNegativeInt(
      env.COMPRESSION_PIPELINE_BREAKER_COOLDOWN_MS,
      DEFAULT_PIPELINE_BREAKER.cooldownMs
    );
  return {
    enabled: enabled === true,
    failureThreshold: Math.max(1, failureThreshold),
    cooldownMs: Math.max(0, cooldownMs),
  };
}

/**
 * Whether an engine may run now. CLOSED → true. OPEN within cooldown → false. OPEN past the
 * cooldown → lazily transitions to half-open (one probe allowed; a probe failure re-opens it
 * immediately because failures is left one short of the threshold). `now` is injectable for tests.
 */
export function canRunEngine(
  engine: string,
  config: PipelineCircuitBreakerConfig,
  now: number = Date.now()
): boolean {
  if (!config.enabled) return true;
  const s = get(engine);
  if (s.openedUntil == null) return true; // CLOSED (or already half-open)
  if (now >= s.openedUntil) {
    // Cooldown elapsed → half-open: allow a single probe, but keep failures one below the
    // threshold so the very next failure re-opens the breaker without N more round-trips.
    s.openedUntil = null;
    s.failures = Math.max(0, config.failureThreshold - 1);
    return true;
  }
  return false; // OPEN
}

/** Record a failed engine run; opens the breaker once consecutive failures hit the threshold. */
export function recordEngineFailure(
  engine: string,
  config: PipelineCircuitBreakerConfig,
  now: number = Date.now()
): void {
  if (!config.enabled) return;
  const s = get(engine);
  s.failures += 1;
  if (s.failures >= config.failureThreshold) {
    s.openedUntil = now + config.cooldownMs;
  }
}

/** Record a successful engine run; fully closes the breaker. */
export function recordEngineSuccess(engine: string, config: PipelineCircuitBreakerConfig): void {
  if (!config.enabled) return;
  const s = get(engine);
  s.failures = 0;
  s.openedUntil = null;
}

/** Inspect breaker state for telemetry/tests. */
export function getEngineBreakerState(engine: string): { failures: number; open: boolean } {
  const s = _state.get(engine);
  return { failures: s?.failures ?? 0, open: s?.openedUntil != null };
}

/** Clear all breaker state (tests + operator reset). */
export function resetPipelineEngineBreakers(): void {
  _state.clear();
}

/**
 * Core telemetry + step-decision machinery for the stacked compression pipeline, extracted
 * from `strategySelector.ts` so that god-file stays bounded. This module is a leaf: it depends
 * only on the shared compression types, so it never participates in a cycle.
 *
 * It holds the per-run accumulator (`StackAccumulator` + `createStackAccumulator`), the TV1
 * bail-out config + advance decision (`BailoutConfig` + `decideStep`), and the per-step
 * telemetry fold (`mergeStackStep`). The sync/async stacked loops in `strategySelector.ts`
 * consume these.
 */

import type { CompressionResult, CompressionStats } from "./types.ts";

/**
 * TV1 — Opt-in bail-out configuration for the stacked pipeline.
 * When enabled: a step that throws is silently skipped (verbatim kept); a step whose gain is
 * below `minGainPercent` is also skipped. DEFAULT = disabled (byte-identical to pre-TV1).
 */
export interface BailoutConfig {
  enabled: boolean;
  /** Minimum savings percent required to advance currentBody. Default: 10. */
  minGainPercent?: number;
}

/** Accumulates per-step telemetry across a stacked run (shared sync/async). */
export interface StackAccumulator {
  techniques: Set<string>;
  rules: Set<string>;
  breakdown: NonNullable<CompressionStats["engineBreakdown"]>;
  rtkRawOutputPointers: NonNullable<CompressionStats["rtkRawOutputPointers"]>;
  validationWarnings: Set<string>;
  validationErrors: Set<string>;
  fallbackApplied: boolean;
}

export function createStackAccumulator(): StackAccumulator {
  return {
    techniques: new Set<string>(),
    rules: new Set<string>(),
    breakdown: [],
    rtkRawOutputPointers: [],
    validationWarnings: new Set<string>(),
    validationErrors: new Set<string>(),
    fallbackApplied: false,
  };
}

/**
 * TV1 — Pure helper that decides whether a completed step should advance `currentBody`. Called
 * only when bail-out is ENABLED; the loops bypass it on the default-off path (zero cost). Returns
 * `{ advance: true }` to accept the step, or `{ advance: false }` to skip it (verbatim kept).
 */
export function decideStep(
  result: CompressionResult,
  bailout: BailoutConfig
): { advance: boolean } {
  if (!result.compressed) return { advance: false };
  // Clamp: a negative minGainPercent would mean "always advance" (invalid state).
  const minGain = Math.max(0, bailout.minGainPercent ?? 10);
  const gain = result.stats?.savingsPercent ?? 0;
  if (gain < minGain) return { advance: false };
  return { advance: true };
}

/**
 * A dispatched step whose engine found nothing eligible (e.g. session-dedup with no repeated
 * blocks, ccr below its min-chars threshold) returns `stats: null` instead of throwing or
 * advancing. Left unrecorded, that step vanishes from the pipeline's telemetry with zero trace —
 * no `engineBreakdown` entry, no warning, no error (#6479, #6491). Surface it as a validation
 * warning so operators can tell "engine ran but had nothing to do" apart from "engine never ran".
 */
function recordNullStatsStep(acc: StackAccumulator, engineId: string): void {
  acc.validationWarnings.add(`${engineId}: skipped (no eligible content)`);
}

/** Folds one engine result into the accumulator (telemetry + breakdown entry). */
export function mergeStackStep(
  acc: StackAccumulator,
  engineId: string,
  result: CompressionResult
): void {
  if (!result.stats) {
    // No-op engine (e.g. ccr / session-dedup found no candidate): stats is null so there is no
    // telemetry to fold, but the engine still RAN — record a zero-savings breakdown entry so its
    // identity survives. Without this the breakdown stays empty and ensureEngineBreakdown
    // synthesizes a generic "stacked" 0% node, hiding which engine an operator actually asked for.
    // Also surface a validation warning so operators can tell "engine ran but had nothing to do"
    // apart from "engine never ran" (#6479, #6491).
    recordNullStatsStep(acc, engineId);
    acc.breakdown.push({
      engine: engineId,
      originalTokens: 0,
      compressedTokens: 0,
      savingsPercent: 0,
      techniquesUsed: [],
    });
    return;
  }
  result.stats.techniquesUsed.forEach((technique) => acc.techniques.add(technique));
  result.stats.rulesApplied?.forEach((rule) => acc.rules.add(rule));
  result.stats.rtkRawOutputPointers?.forEach((pointer) => acc.rtkRawOutputPointers.push(pointer));
  result.stats.validationWarnings?.forEach((warning) => acc.validationWarnings.add(warning));
  result.stats.validationErrors?.forEach((error) => acc.validationErrors.add(error));
  acc.fallbackApplied = acc.fallbackApplied || result.stats.fallbackApplied === true;
  acc.breakdown.push({
    engine: engineId,
    originalTokens: result.stats.originalTokens,
    compressedTokens: result.stats.compressedTokens,
    savingsPercent: result.stats.savingsPercent,
    techniquesUsed: result.stats.techniquesUsed,
    ...(result.stats.rulesApplied ? { rulesApplied: result.stats.rulesApplied } : {}),
    ...(result.stats.durationMs !== undefined ? { durationMs: result.stats.durationMs } : {}),
  });
}

// Resolves the persisted per-engine DETAIL sub-object (settings.headroom / .sessionDedup /
// .ccr) for a stacked-pipeline step. Extracted out of strategySelector.ts (frozen at cap by
// file-size-baseline.json — see scripts/check/check-file-size.mjs) rather than growing that
// file inline.
//
// #8056 wired settings.headroom.minRows into buildStepOptions so the dashboard value takes
// effect even when the stacked-pipeline step itself carries no config. #8388 extends the same
// merge to session-dedup and ccr, whose detail settings previously had nowhere to persist to
// (see compressionDetailNormalizers.ts on the DB write side of the same gap).
import type { CompressionConfig, CompressionPipelineStep } from "./types.ts";

export function resolveStepDetailConfig(
  engine: CompressionPipelineStep["engine"],
  config: CompressionConfig | undefined
) {
  switch (engine) {
    case "headroom":
      return config?.headroom ?? {};
    case "session-dedup":
      return config?.sessionDedup ?? {};
    case "ccr":
      return config?.ccr ?? {};
    default:
      return {};
  }
}

