function getModuleDir(): string {
  const anchors = [process.cwd()];
  const argv1 = process.argv[1];
  if (typeof argv1 === "string" && argv1) anchors.push(path.dirname(argv1));
  const rel = path.join("open-sse", "services", "compression");
  for (const anchor of anchors) {
    let dir = path.resolve(anchor);
    for (let i = 0; i <= 8; i++) {
      if (fs.existsSync(path.join(dir, rel))) return dir;
      const parent = path.dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  }
  return path.join(os.homedir(), ".omniroute");
}

function getFiltersDir(): string {
  const root = getModuleDir();
  const candidates = [
    path.join(root, "open-sse", "services", "compression", "engines", "rtk", "filters"),
    path.join(root, "app", "open-sse", "services", "compression", "engines", "rtk", "filters"),
  ];
  return (
    candidates.find((candidate, index) => {
      return candidates.indexOf(candidate) === index && fs.existsSync(candidate);
    }) ?? candidates[0]
  );
}

function getDataDir(): string {
  return process.env.DATA_DIR || path.join(os.homedir(), ".omniroute");
}

function sha256(value: string): string {
  return crypto.createHash("sha256").update(value).digest("hex");
}

function projectFiltersTrusted(
  filtersPath: string,
  trustProjectFilters = false
): boolean | "changed" {
  if (trustProjectFilters) return true;
  if (process.env.OMNIROUTE_RTK_TRUST_PROJECT_FILTERS === "1") return true;
  const trustPath = path.join(path.dirname(filtersPath), "trust.json");
  if (!fs.existsSync(trustPath)) return false;
  try {
    const filtersHash = sha256(fs.readFileSync(filtersPath, "utf8"));
    const trust = JSON.parse(fs.readFileSync(trustPath, "utf8")) as Record<string, unknown>;
    const isToml = filtersPath.endsWith(".toml");
    const trustedHash = isToml
      ? typeof trust.filtersTomlSha256 === "string"
        ? trust.filtersTomlSha256
        : null
      : typeof trust.filtersSha256 === "string"
        ? trust.filtersSha256
        : typeof trust.trustedFiltersSha256 === "string"
          ? trust.trustedFiltersSha256
          : null;
    if (!trustedHash) return false;
    return trustedHash === filtersHash ? true : "changed";
  } catch {
    return false;
  }
}

function collectFilterSources(options: RtkFilterLoadOptions = {}): FilterSource[] {
  const sources: FilterSource[] = [];
  if (options.customFiltersEnabled !== false) {
    collectProjectFilterSources(sources, options);
    collectGlobalFilterSources(sources);
  }
  collectBuiltinFilterSources(sources);
  return sources;
}

function collectProjectFilterSources(sources: FilterSource[], options: RtkFilterLoadOptions): void {
  const projectCandidates = [
    { path: path.join(process.cwd(), ".rtk", "filters.toml"), format: "rtk-toml-v1" as const },
    { path: path.join(process.cwd(), ".rtk", "filters.json"), format: "omniroute-json" as const },
  ];
  for (const candidate of projectCandidates) {
    if (!fs.existsSync(candidate.path)) continue;
    const trusted = projectFiltersTrusted(candidate.path, options.trustProjectFilters === true);
    if (trusted === true) {
      sources.push({ source: "project", ...candidate, trusted: true });
      continue;
    }
    diagnostics.push({
      source: "project",
      format: candidate.format,
      path: candidate.path,
      level: "warning",
      message:
        trusted === "changed"
          ? "Project RTK filters changed after trust and were skipped"
          : "Project RTK filters are untrusted and were skipped",
    });
  }
}

function collectGlobalFilterSources(sources: FilterSource[]): void {
  const globalCandidates = [
    { path: path.join(getDataDir(), "rtk", "filters.toml"), format: "rtk-toml-v1" as const },
    { path: path.join(getDataDir(), "rtk", "filters.json"), format: "omniroute-json" as const },
  ];
  for (const candidate of globalCandidates) {
    if (fs.existsSync(candidate.path)) {
      sources.push({ source: "global", ...candidate, trusted: true });
    }
  }
}

function collectBuiltinFilterSources(sources: FilterSource[]): void {
  const builtinDir = getFiltersDir();
  if (fs.existsSync(builtinDir)) {
    let builtinFiles: string[] = [];
    try {
      builtinFiles = fs
        .readdirSync(builtinDir)
        .filter((entry) => entry.endsWith(".json"))
        .sort();
    } catch {
      // A read failure on the builtin dir (lost permission, TOCTOU after existsSync, NFS
      // timeout, read-only container) must not fail the request — degrade to the filters
      // already collected. listRtkCommandSamples guards readdirSync the same way.
      builtinFiles = [];
    }
    for (const file of builtinFiles) {
      sources.push({
        source: "builtin",
        path: path.join(builtinDir, file),
        trusted: true,
        format: "omniroute-json",
      });
    }
  }
}

function parseFilterFile(source: FilterSource): RtkFilterDefinition[] {
  try {
    const content = fs.readFileSync(source.path, "utf8");
    const definitions =
      source.format === "rtk-toml-v1"
        ? (() => {
            const result = parseRtkTomlV1(content);
            if (!result.passed) {
              throw new Error("one or more inline tests failed");
            }
            for (const warning of result.warnings) {
              diagnostics.push({
                source: source.source,
                format: source.format,
                path: source.path,
                level: "warning",
                message: warning,
              });
            }
            return result.filters;
          })()
        : (() => {
            const parsed = JSON.parse(content);
            const entries = Array.isArray(parsed) ? parsed : [parsed];
            return entries.map(validateRtkFilter);
          })();
    return definitions.map((definition) => ({
      ...definition,
      source: source.source,
      sourceFormat: definition.sourceFormat ?? source.format,
    }));
  } catch (error) {
    const message =
      error instanceof RtkTomlCompatibilityError
        ? error.publicMessage
        : error instanceof Error
          ? error.message
          : String(error);
    if (source.source === "builtin") {
      throw new Error(`Invalid RTK filter ${path.basename(source.path)}: ${message}`);
    }
    diagnostics.push({
      source: source.source,
      format: source.format,
      path: source.path,
      level: "warning",
      message: `Invalid custom RTK filter skipped: ${message}`,
    });
    return [];
  }
}

export function loadRtkFilters(options: RtkFilterLoadOptions = {}): RtkFilterDefinition[] {
  const currentCacheKey = [
    process.cwd(),
    getDataDir(),
    options.customFiltersEnabled === false ? "builtin-only" : "custom",
    options.trustProjectFilters === true ? "trusted-project" : "trust-file",
    process.env.OMNIROUTE_RTK_TRUST_PROJECT_FILTERS === "1" ? "env-trust" : "env-normal",
  ].join("|");
  if (cache && cacheKey === currentCacheKey && !options.refresh) return cache;
  diagnostics = [];
  const filters: RtkFilterDefinition[] = [];
  for (const source of collectFilterSources(options)) {
    filters.push(...parseFilterFile(source));
  }

  const sourceRank = { project: 3, global: 2, builtin: 1 } as const;
  const formatRank = { "rtk-toml-v1": 2, "omniroute-json": 1 } as const;
  const sorted = filters.sort(
    (a, b) =>
      sourceRank[b.source ?? "builtin"] - sourceRank[a.source ?? "builtin"] ||
      formatRank[b.sourceFormat ?? "omniroute-json"] -
        formatRank[a.sourceFormat ?? "omniroute-json"] ||
      b.priority - a.priority ||
      a.id.localeCompare(b.id)
  );
  cache = sorted;
  cacheKey = currentCacheKey;
  return sorted;
}

export function getRtkFilterLoadDiagnostics(): RtkFilterLoadDiagnostic[] {
  loadRtkFilters();
  return diagnostics.map((entry) => ({ ...entry }));
}

export function getRtkFilterCatalog(): Array<
  Pick<
    RtkFilterDefinition,
    | "id"
    | "name"
    | "description"
    | "commandTypes"
    | "category"
    | "priority"
    | "source"
    | "sourceFormat"
  >
> {
  return loadRtkFilters().map((filter) => ({
    id: filter.id,
    name: filter.name,
    description: filter.description,
    commandTypes: filter.commandTypes,
    category: filter.category,
    priority: filter.priority,
    source: filter.source,
    sourceFormat: filter.sourceFormat,
  }));
}

export function matchRtkFilter(
  text: string,
  command?: string | null,
  options: RtkFilterLoadOptions = {}
): RtkFilterDefinition | null {
  const detection = detectCommandType(text, command);
  const detectedCommand = detection.command ?? command ?? "";
  const filters = loadRtkFilters(options);
  for (const source of ["project", "global", "builtin"] as const) {
    const scoped = filters.filter((filter) => (filter.source ?? "builtin") === source);
    const matched =
      scoped.find(
        (filter) =>
          filter.sourceFormat === "rtk-toml-v1" &&
          detectedCommand &&
          filter.commandPatterns.some((pattern) => cachedMatchPattern(pattern, detectedCommand))
      ) ??
      scoped.find((filter) => filter.commandTypes.includes(detection.type)) ??
      scoped.find(
        (filter) =>
          detectedCommand &&
          filter.commandPatterns.some((pattern) => cachedMatchPattern(pattern, detectedCommand))
      ) ??
      scoped.find((filter) =>
        filter.matchPatterns.some((pattern) => cachedMatchPattern(pattern, text))
      );
    if (matched) return matched;
  }
  return filters.find((filter) => filter.commandTypes.includes("generic-output")) ?? null;
}

import { z } from "zod";

const rtkFilterCategorySchema = z.enum([
  "git",
  "test",
  "build",
  "shell",
  "docker",
  "package",
  "infra",
  "cloud",
  "generic",
]);

const rtkReplaceRuleSchema = z
  .object({
    pattern: z.string().min(1),
    replacement: z.string(),
  })
  .strict();

const rtkMatchOutputRuleSchema = z
  .object({
    pattern: z.string().min(1),
    message: z.string(),
    unless: z.string().min(1).optional(),
  })
  .strict();

const rtkInlineTestSchema = z
  .object({
    name: z.string().min(1),
    input: z.string(),
    expected: z.string(),
    command: z.string().optional(),
  })
  .strict();

const rtkFilterMatchSchema = z
  .object({
    commands: z.array(z.string().min(1)).default([]),
    patterns: z.array(z.string().min(1)).default([]),
    outputTypes: z.array(z.string().min(1)).default([]),
  })
  .strict();

const rtkFilterRulesSchema = z
  .object({
    stripAnsi: z.boolean().default(false),
    replace: z.array(rtkReplaceRuleSchema).default([]),
    matchOutput: z.array(rtkMatchOutputRuleSchema).default([]),
    includePatterns: z.array(z.string()).default([]),
    dropPatterns: z.array(z.string()).default([]),
    collapsePatterns: z.array(z.string()).default([]),
    deduplicate: z.boolean().default(false),
    truncateLineAt: z.number().int().min(0).default(0),
    maxLines: z.number().int().min(0).default(0),
    headLines: z.number().int().min(0).default(20),
    tailLines: z.number().int().min(0).default(20),
    onEmpty: z.string().default(""),
    filterStderr: z.boolean().default(false),
  })
  .strict();

const rtkFilterPreserveSchema = z
  .object({
    errorPatterns: z.array(z.string()).default([]),
    summaryPatterns: z.array(z.string()).default([]),
  })
  .strict();

const rtkFilterPackSchema = z
  .object({
    id: z.string().min(1),
    label: z.string().min(1),
    description: z.string().default(""),
    category: rtkFilterCategorySchema,
    priority: z.number().int().min(0).max(100).default(50),
    match: rtkFilterMatchSchema,
    rules: rtkFilterRulesSchema.default({} as unknown as z.infer<typeof rtkFilterRulesSchema>),
    preserve: rtkFilterPreserveSchema.default(
      {} as unknown as z.infer<typeof rtkFilterPreserveSchema>
    ),
    tests: z.array(rtkInlineTestSchema).default([]),
  })
  .strict();

const legacyRtkFilterSchema = z
  .object({
    id: z.string().min(1),
    name: z.string().min(1),
    description: z.string().default(""),
    commandTypes: z.array(z.string().min(1)).min(1),
    category: rtkFilterCategorySchema,
    priority: z.number().int().min(0).max(100).default(50),
    stripPatterns: z.array(z.string()).default([]),
    keepPatterns: z.array(z.string()).default([]),
    priorityPatterns: z.array(z.string()).default([]),
    collapsePatterns: z.array(z.string()).default([]),
    stripAnsi: z.boolean().default(false),
    replace: z.array(rtkReplaceRuleSchema).default([]),
    matchOutput: z.array(rtkMatchOutputRuleSchema).default([]),
    truncateLineAt: z.number().int().min(0).default(0),
    onEmpty: z.string().default(""),
    filterStderr: z.boolean().default(false),
    maxLines: z.number().int().min(0).default(0),
    preserveHead: z.number().int().min(0).default(20),
    preserveTail: z.number().int().min(0).default(20),
    tests: z.array(rtkInlineTestSchema).default([]),
  })
  .strict();

export const rtkFilterSchema = z.union([rtkFilterPackSchema, legacyRtkFilterSchema]);

type RtkFilterPack = z.infer<typeof rtkFilterPackSchema>;

export interface RtkFilterDefinition {
  id: string;
  name: string;
  description: string;
  commandTypes: string[];
  commandPatterns: string[];
  matchPatterns: string[];
  category: z.infer<typeof rtkFilterCategorySchema>;
  priority: number;
  stripPatterns: string[];
  keepPatterns: string[];
  priorityPatterns: string[];
  collapsePatterns: string[];
  stripAnsi: boolean;
  replace: Array<{ pattern: string; replacement: string }>;
  matchOutput: Array<{ pattern: string; message: string; unless?: string }>;
  truncateLineAt: number;
  onEmpty: string;
  filterStderr: boolean;
  deduplicate: boolean;
  maxLines: number;
  preserveHead: number;
  preserveTail: number;
  /** Exact RTK TOML schema-v1 head/tail stages. Undefined for OmniRoute-native JSON filters. */
  rtkTomlHeadLines?: number;
  rtkTomlTailLines?: number;
  rtkTomlMaxLines?: number;
  sourceFormat?: "omniroute-json" | "rtk-toml-v1";
  source?: "project" | "global" | "builtin";
  tests: Array<{ name: string; input: string; expected: string; command?: string }>;
}

function isCanonicalFilter(value: z.infer<typeof rtkFilterSchema>): value is RtkFilterPack {
  return "label" in value && "match" in value && "rules" in value;
}

/**
 * Conservative, dependency-free ReDoS guard. Custom RTK filters (DATA_DIR/rtk/filters.json)
 * carry user-supplied regex strings that are compiled and run against untrusted tool output;
 * a nested unbounded quantifier ((a+)+, (a*)*, ([a-z]+)+, (a+|b)+ …) causes catastrophic
 * backtracking. This flags the common single-group nested-quantifier shapes so the loader
 * never compiles them. Heuristic by design — a full analysis would use `safe-regex` (not
 * installable in this symlinked worktree); it is itself linear (no nested quantifier).
 */
export function isReDoSProne(pattern: string): boolean {
  return /\([^()]*(?:[+*]|\{\d+,\})[^()]*\)\s*(?:[+*]|\{\d+,\})/.test(pattern);
}

function dropReDoSProne(patterns: string[]): string[] {
  return patterns.filter((p) => !isReDoSProne(p));
}

export function validateRtkFilter(value: unknown): RtkFilterDefinition {
  const parsed = rtkFilterSchema.parse(value);
  if (!isCanonicalFilter(parsed)) {
    const collapse = dropReDoSProne(parsed.collapsePatterns);
    return {
      ...parsed,
      stripPatterns: dropReDoSProne(parsed.stripPatterns),
      keepPatterns: dropReDoSProne(parsed.keepPatterns),
      priorityPatterns: dropReDoSProne(parsed.priorityPatterns),
      collapsePatterns: collapse,
      replace: parsed.replace.filter((r) => !isReDoSProne(r.pattern)),
      matchOutput: parsed.matchOutput.filter((r) => !isReDoSProne(r.pattern)),
      commandPatterns: [],
      matchPatterns: [],
      deduplicate: collapse.length > 0,
    };
  }

  const preservePatterns = [...parsed.preserve.errorPatterns, ...parsed.preserve.summaryPatterns];
  return {
    id: parsed.id,
    name: parsed.label,
    description: parsed.description,
    commandTypes: parsed.match.outputTypes,
    commandPatterns: dropReDoSProne(parsed.match.commands),
    matchPatterns: dropReDoSProne(parsed.match.patterns),
    category: parsed.category,
    priority: parsed.priority,
    stripPatterns: dropReDoSProne(parsed.rules.dropPatterns),
    keepPatterns: dropReDoSProne(parsed.rules.includePatterns),
    priorityPatterns: dropReDoSProne(preservePatterns),
    collapsePatterns: dropReDoSProne(parsed.rules.collapsePatterns),
    stripAnsi: parsed.rules.stripAnsi,
    replace: parsed.rules.replace.filter((r) => !isReDoSProne(r.pattern)),
    matchOutput: parsed.rules.matchOutput.filter((r) => !isReDoSProne(r.pattern)),
    truncateLineAt: parsed.rules.truncateLineAt,
    onEmpty: parsed.rules.onEmpty,
    filterStderr: parsed.rules.filterStderr,
    deduplicate: parsed.rules.deduplicate,
    maxLines: parsed.rules.maxLines,
    preserveHead: parsed.rules.headLines,
    preserveTail: parsed.rules.tailLines,
    tests: parsed.tests,
  };
}

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { parse as parseToml } from "smol-toml";
import { z } from "zod";
import { isReDoSProne, type RtkFilterDefinition } from "./filterSchema.ts";
import { applyLineFilter } from "./lineFilter.ts";

const MAX_TOML_BYTES = 1024 * 1024;

const replaceRuleSchema = z
  .object({
    pattern: z.string().min(1),
    replacement: z.string(),
  })
  .strict();

const matchOutputRuleSchema = z
  .object({
    pattern: z.string().min(1),
    message: z.string(),
    unless: z.string().min(1).optional(),
  })
  .strict();

const filterSchema = z
  .object({
    description: z.string().optional(),
    match_command: z.string().min(1),
    strip_ansi: z.boolean().optional(),
    filter_stderr: z.boolean().optional(),
    strip_lines_matching: z.array(z.string()).optional(),
    keep_lines_matching: z.array(z.string()).optional(),
    replace: z.array(replaceRuleSchema).optional(),
    match_output: z.array(matchOutputRuleSchema).optional(),
    truncate_lines_at: z.number().int().min(0).optional(),
    head_lines: z.number().int().min(0).optional(),
    tail_lines: z.number().int().min(0).optional(),
    max_lines: z.number().int().min(0).optional(),
    on_empty: z.string().optional(),
  })
  .strict();

const inlineTestSchema = z
  .object({
    name: z.string().min(1),
    input: z.string(),
    expected: z.string(),
  })
  .strict();

const fileSchema = z
  .object({
    schema_version: z.literal(1),
    filters: z.record(z.string().min(1), filterSchema).default({}),
    tests: z.record(z.string().min(1), z.array(inlineTestSchema)).default({}),
  })
  .strict();

type ParsedFilter = z.infer<typeof filterSchema>;

function arrayOrEmpty<T>(value: T[] | undefined): T[] {
  return value ?? [];
}

function numberOrZero(value: number | undefined): number {
  return value ?? 0;
}

export interface RtkTomlTestOutcome {
  filterId: string;
  testName: string;
  passed: boolean;
  actual: string;
  expected: string;
}

export interface RtkTomlCompatibilityResult {
  schemaVersion: 1;
  sha256: string;
  filters: RtkFilterDefinition[];
  outcomes: RtkTomlTestOutcome[];
  filtersWithoutTests: string[];
  warnings: string[];
  passed: boolean;
}

export class RtkTomlCompatibilityError extends Error {
  readonly publicMessage: string;

  constructor(message: string) {
    super("RTK TOML schema v1 compatibility error");
    this.name = "RtkTomlCompatibilityError";
    this.publicMessage = message;
  }
}

function compatibilityError(message: string): RtkTomlCompatibilityError {
  return new RtkTomlCompatibilityError(message);
}

function categoryFor(name: string, commandPattern: string): RtkFilterDefinition["category"] {
  const value = `${name} ${commandPattern}`.toLowerCase();
  if (/\b(?:git|gh)\b/.test(value)) return "git";
  if (/\b(?:test|jest|vitest|pytest|cargo test|go test|rspec|playwright)\b/.test(value)) {
    return "test";
  }
  if (/\b(?:build|tsc|eslint|ruff|clippy|gradle|make|next|vite|webpack)\b/.test(value)) {
    return "build";
  }
  if (/\b(?:docker|kubectl|podman|compose)\b/.test(value)) return "docker";
  if (/\b(?:npm|pnpm|yarn|bun|pip|poetry|uv|bundle|composer)\b/.test(value)) {
    return "package";
  }
  if (/\b(?:terraform|tofu|ansible|helm|pulumi)\b/.test(value)) return "infra";
  if (/\b(?:aws|gcloud|az|cloudflare)\b/.test(value)) return "cloud";
  if (/\b(?:ls|find|grep|rg|df|du|ps|systemctl|ssh|rsync)\b/.test(value)) return "shell";
  return "generic";
}

function regexFields(filter: ParsedFilter): Array<{ field: string; pattern: string }> {
  return [
    { field: "match_command", pattern: filter.match_command },
    ...(filter.strip_lines_matching ?? []).map((pattern) => ({
      field: "strip_lines_matching",
      pattern,
    })),
    ...(filter.keep_lines_matching ?? []).map((pattern) => ({
      field: "keep_lines_matching",
      pattern,
    })),
    ...(filter.replace ?? []).map(({ pattern }) => ({ field: "replace.pattern", pattern })),
    ...(filter.match_output ?? []).flatMap(({ pattern, unless }) => [
      { field: "match_output.pattern", pattern },
      ...(unless ? [{ field: "match_output.unless", pattern: unless }] : []),
    ]),
  ];
}

function validateRegexes(name: string, filter: ParsedFilter): void {
  for (const { field, pattern } of regexFields(filter)) {
    if (isReDoSProne(pattern)) {
      throw compatibilityError(`filter '${name}' has an unsafe regex in ${field}`);
    }
    try {
      new RegExp(pattern);
    } catch {
      throw compatibilityError(`filter '${name}' has an invalid regex in ${field}`);
    }
  }
}

function toDefinition(
  name: string,
  filter: ParsedFilter,
  tests: z.infer<typeof inlineTestSchema>[]
): RtkFilterDefinition {
  if (
    (filter.strip_lines_matching?.length ?? 0) > 0 &&
    (filter.keep_lines_matching?.length ?? 0) > 0
  ) {
    throw compatibilityError(
      `filter '${name}' cannot combine strip_lines_matching with keep_lines_matching`
    );
  }
  validateRegexes(name, filter);
  return {
    id: name,
    name,
    description: filter.description ?? "",
    commandTypes: [],
    commandPatterns: [filter.match_command],
    matchPatterns: [],
    category: categoryFor(name, filter.match_command),
    priority: 50,
    stripPatterns: arrayOrEmpty(filter.strip_lines_matching),
    keepPatterns: arrayOrEmpty(filter.keep_lines_matching),
    priorityPatterns: [],
    collapsePatterns: [],
    stripAnsi: filter.strip_ansi ?? false,
    replace: arrayOrEmpty(filter.replace),
    matchOutput: arrayOrEmpty(filter.match_output),
    truncateLineAt: numberOrZero(filter.truncate_lines_at),
    onEmpty: filter.on_empty ?? "",
    filterStderr: false,
    deduplicate: false,
    maxLines: numberOrZero(filter.max_lines),
    preserveHead: 0,
    preserveTail: 0,
    rtkTomlHeadLines: filter.head_lines,
    rtkTomlTailLines: filter.tail_lines,
    rtkTomlMaxLines: filter.max_lines,
    sourceFormat: "rtk-toml-v1",
    tests,
  };
}

function comparable(value: string): string {
  return value.replace(/\n+$/g, "");
}

function tomlSyntaxLocation(error: unknown): string {
  if (typeof error !== "object" || error === null) return "";
  const { line, column } = error as { line?: unknown; column?: unknown };
  if (!Number.isSafeInteger(line) || !Number.isSafeInteger(column)) return "";
  return ` (line ${line}, column ${column})`;
}

export function parseRtkTomlV1(content: string): RtkTomlCompatibilityResult {
  if (Buffer.byteLength(content, "utf8") > MAX_TOML_BYTES) {
    throw compatibilityError(`file exceeds the ${MAX_TOML_BYTES}-byte limit`);
  }

  let raw: unknown;
  try {
    raw = parseToml(content);
  } catch (error) {
    throw compatibilityError(`invalid TOML syntax${tomlSyntaxLocation(error)}`);
  }

  const parsed = fileSchema.safeParse(raw);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    const field = issue?.path.length ? issue.path.join(".") : "document";
    throw compatibilityError(`${field}: ${issue?.message ?? "invalid document"}`);
  }
  if (Object.keys(parsed.data.filters).length === 0) {
    throw compatibilityError("document contains no filters");
  }

  for (const testName of Object.keys(parsed.data.tests)) {
    if (!(testName in parsed.data.filters)) {
      throw compatibilityError(`tests reference unknown filter '${testName}'`);
    }
  }

  const filters = Object.entries(parsed.data.filters).map(([name, filter]) =>
    toDefinition(name, filter, parsed.data.tests[name] ?? [])
  );
  const outcomes = filters.flatMap((filter) =>
    filter.tests.map((test) => {
      const actual = comparable(applyLineFilter(test.input, filter).text);
      const expected = comparable(test.expected);
      return {
        filterId: filter.id,
        testName: test.name,
        passed: actual === expected,
        actual,
        expected,
      };
    })
  );
  const filtersWithoutTests = filters
    .filter((filter) => filter.tests.length === 0)
    .map((filter) => filter.id);
  const warnings = filtersWithoutTests.map(
    (id) => `Filter '${id}' has no inline tests and should be reviewed before installation`
  );
  for (const [id, filter] of Object.entries(parsed.data.filters)) {
    if (filter.filter_stderr) {
      warnings.push(
        `Filter '${id}': filter_stderr is accepted as a no-op because OmniRoute receives already-captured tool output`
      );
    }
  }

  return {
    schemaVersion: 1,
    sha256: crypto.createHash("sha256").update(content).digest("hex"),
    filters,
    outcomes,
    filtersWithoutTests,
    warnings,
    passed: outcomes.every((outcome) => outcome.passed),
  };
}

function getDataDir(): string {
  return process.env.DATA_DIR || path.join(os.homedir(), ".omniroute");
}

export function getGlobalRtkTomlPath(): string {
  return path.join(getDataDir(), "rtk", "filters.toml");
}

export function installGlobalRtkTomlV1(
  content: string,
  options: { overwrite?: boolean } = {}
): RtkTomlCompatibilityResult & { installedPath: string; backupCreated: boolean } {
  const result = parseRtkTomlV1(content);
  if (!result.passed) {
    throw compatibilityError("one or more inline tests failed");
  }

  const target = getGlobalRtkTomlPath();
  const directory = path.dirname(target);
  fs.mkdirSync(directory, { recursive: true, mode: 0o700 });
  try {
    fs.chmodSync(directory, 0o700);
  } catch {
    // Best effort on filesystems that do not support POSIX permissions.
  }
  if (fs.existsSync(target) && !options.overwrite) {
    throw compatibilityError("filters.toml already exists; confirm overwrite to replace it");
  }

  let backupCreated = false;
  if (fs.existsSync(target)) {
    fs.copyFileSync(target, `${target}.bak`);
    try {
      fs.chmodSync(`${target}.bak`, 0o600);
    } catch {
      // Best effort on filesystems that do not support POSIX permissions.
    }
    backupCreated = true;
  }
  const temporary = `${target}.${process.pid}.${crypto.randomUUID()}.tmp`;
  try {
    fs.writeFileSync(temporary, content, { encoding: "utf8", mode: 0o600, flag: "wx" });
    fs.renameSync(temporary, target);
    try {
      fs.chmodSync(target, 0o600);
    } catch {
      // Best effort on filesystems that do not support POSIX permissions.
    }
  } finally {
    fs.rmSync(temporary, { force: true });
  }

  return { ...result, installedPath: "rtk/filters.toml", backupCreated };
}

export const RTK_TOML_MAX_BYTES = MAX_TOML_BYTES;

import type { RtkFilterDefinition } from "./filterSchema.ts";
import { smartTruncate } from "./smartTruncate.ts";
import { deduplicateRepeatedLines } from "./deduplicator.ts";

export interface LineFilterResult {
  text: string;
  strippedLines: number;
  keptByRule: boolean;
  appliedRules: string[];
}

// ──────────────── RegExp cache ────────────────
//
// Patterns are static (loaded from filter JSON files on boot) but were being
// compiled via `new RegExp(...)` on every call to applyLineFilter().  For a
// busy proxy this means thousands of redundant RegExp instantiations per
// second.  Cache them here once.

const regexCache = new Map<string, RegExp>();

function cachedRegExp(pattern: string, flags: string): RegExp | null {
  const key = `${pattern}::${flags}`;
  const cached = regexCache.get(key);
  if (cached) return cached;
  try {
    const re = new RegExp(pattern, flags);
    regexCache.set(key, re);
    return re;
  } catch {
    return null;
  }
}

function compilePatterns(patterns: string[]): RegExp[] {
  return patterns.flatMap((pattern) => {
    const re = cachedRegExp(pattern, "i");
    return re ? [re] : [];
  });
}

function compileGlobalPattern(pattern: string): RegExp | null {
  return cachedRegExp(pattern, "g");
}

function compileBlobPattern(pattern: string): RegExp | null {
  return cachedRegExp(pattern, "im");
}

function stripAnsi(text: string): string {
  return text.replace(/\u001b\[[0-?]*[ -/]*[@-~]/g, "");
}

function normalizeStderrPrefix(line: string): string {
  return line.replace(/^\s*(?:stderr|err)\s*(?:\||:)\s*/i, "");
}

function applyRtkTomlLineLimits(
  lines: string[],
  filter: RtkFilterDefinition,
  appliedRules: string[]
): string[] {
  const head = filter.rtkTomlHeadLines;
  const tail = filter.rtkTomlTailLines;
  const total = lines.length;

  if (head !== undefined && tail !== undefined) {
    if (total > head + tail) {
      lines = [
        ...lines.slice(0, head),
        `... (${total - head - tail} lines omitted)`,
        ...(tail > 0 ? lines.slice(-tail) : []),
      ];
      appliedRules.push(`${filter.id}:rtk-head-tail`);
    }
  } else if (head !== undefined && total > head) {
    lines = [...lines.slice(0, head), `... (${total - head} lines omitted)`];
    appliedRules.push(`${filter.id}:rtk-head`);
  } else if (tail !== undefined && total > tail) {
    lines = [`... (${total - tail} lines omitted)`, ...(tail > 0 ? lines.slice(-tail) : [])];
    appliedRules.push(`${filter.id}:rtk-tail`);
  }

  const maxLines = filter.rtkTomlMaxLines;
  if (maxLines !== undefined && lines.length > maxLines) {
    const dropped = lines.length - maxLines;
    lines = [...lines.slice(0, maxLines), `... (${dropped} lines truncated)`];
    appliedRules.push(`${filter.id}:rtk-max-lines`);
  }
  return lines;
}

function truncateUnicodeSafe(line: string, maxChars: number): string {
  if (maxChars <= 0) return line;
  const chars = Array.from(line);
  if (chars.length <= maxChars) return line;
  if (maxChars <= 3) return chars.slice(0, maxChars).join("");
  return `${chars.slice(0, maxChars - 3).join("")}...`;
}

export function applyLineFilter(text: string, filter: RtkFilterDefinition): LineFilterResult {
  const stripPatterns = compilePatterns(filter.stripPatterns);
  const keepPatterns = compilePatterns(filter.keepPatterns);
  const collapsePatterns = compilePatterns(filter.collapsePatterns);
  const priorityPatterns = compilePatterns(filter.priorityPatterns);
  const appliedRules: string[] = [];

  let lines = text.split(/\r?\n/);
  if (filter.sourceFormat === "rtk-toml-v1" && lines.at(-1) === "") lines.pop();
  const originalLineCount = lines.length;

  if (filter.stripAnsi) {
    const stripped = lines.map(stripAnsi);
    if (stripped.join("\n") !== lines.join("\n")) {
      appliedRules.push(`${filter.id}:strip-ansi`);
    }
    lines = stripped;
  }

  if (filter.filterStderr) {
    const normalized = lines.map(normalizeStderrPrefix);
    if (normalized.join("\n") !== lines.join("\n")) {
      appliedRules.push(`${filter.id}:filter-stderr`);
    }
    lines = normalized;
  }

  for (const rule of filter.replace) {
    const pattern = compileGlobalPattern(rule.pattern);
    if (!pattern) continue;
    const replaced = lines.map((line) => line.replace(pattern, rule.replacement));
    if (replaced.join("\n") !== lines.join("\n")) {
      appliedRules.push(`${filter.id}:replace`);
    }
    lines = replaced;
  }

  if (filter.matchOutput.length > 0) {
    const blob = lines.join("\n");
    for (const rule of filter.matchOutput) {
      const pattern = compileBlobPattern(rule.pattern);
      if (!pattern?.test(blob)) continue;
      const unless = rule.unless ? compileBlobPattern(rule.unless) : null;
      if (unless?.test(blob)) continue;
      appliedRules.push(`${filter.id}:match-output`);
      return {
        text: rule.message,
        strippedLines: Math.max(0, originalLineCount - 1),
        keptByRule: false,
        appliedRules,
      };
    }
  }

  if (stripPatterns.length > 0) {
    lines = lines.filter((line) => !stripPatterns.some((pattern) => pattern.test(line)));
    if (lines.length !== originalLineCount) appliedRules.push(`${filter.id}:strip`);
  }

  if (keepPatterns.length > 0) {
    const kept = lines.filter((line) => keepPatterns.some((pattern) => pattern.test(line)));
    if (kept.length > 0) {
      lines = kept;
      appliedRules.push(`${filter.id}:keep`);
    }
  }

  if (collapsePatterns.length > 0) {
    const seen = new Set<string>();
    lines = lines.filter((line) => {
      if (!collapsePatterns.some((pattern) => pattern.test(line))) return true;
      const key = line.trim();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
    appliedRules.push(`${filter.id}:collapse`);
  }

  if (filter.truncateLineAt > 0) {
    const truncatedLines = lines.map((line) => truncateUnicodeSafe(line, filter.truncateLineAt));
    if (truncatedLines.join("\n") !== lines.join("\n")) {
      lines = truncatedLines;
      appliedRules.push(`${filter.id}:truncate-line`);
    }
  }

  // Per-filter line dedup (opt-in via the filter's `deduplicate` flag): collapse consecutive
  // duplicate lines before truncation. The engine-wide dedup (config.deduplicateThreshold) is
  // separate; this lets a single filter force it for its own output.
  if (filter.deduplicate) {
    const deduped = deduplicateRepeatedLines(lines.join("\n"));
    if (deduped.collapsed > 0) {
      lines = deduped.text.split(/\r?\n/);
      appliedRules.push(`${filter.id}:deduplicate`);
    }
  }

  if (filter.sourceFormat === "rtk-toml-v1") {
    lines = applyRtkTomlLineLimits(lines, filter, appliedRules);
    const output = lines.join("\n");
    const finalOutput = output.trim().length === 0 && filter.onEmpty ? filter.onEmpty : output;
    return {
      text: finalOutput,
      strippedLines: Math.max(0, originalLineCount - finalOutput.split(/\r?\n/).length),
      keptByRule: keepPatterns.length > 0,
      appliedRules,
    };
  }

  const truncated = smartTruncate(lines.join("\n"), {
    maxLines: filter.maxLines,
    preserveHead: filter.preserveHead,
    preserveTail: filter.preserveTail,
    priorityPatterns,
  });
  if (truncated.truncated) appliedRules.push(`${filter.id}:truncate`);
  const output =
    truncated.text.trim().length === 0 && filter.onEmpty ? filter.onEmpty : truncated.text;

  return {
    text: output,
    strippedLines: Math.max(0, originalLineCount - output.split(/\r?\n/).length),
    keptByRule: keepPatterns.length > 0,
    appliedRules,
  };
}

export interface SmartTruncateOptions {
  maxLines?: number;
  maxChars?: number;
  preserveHead?: number;
  preserveTail?: number;
  priorityPatterns?: RegExp[];
}

export function smartTruncate(
  text: string,
  options: SmartTruncateOptions = {}
): {
  text: string;
  truncated: boolean;
  droppedLines: number;
} {
  const maxChars = Math.max(0, Math.floor(options.maxChars ?? 0));
  const maxLines = Math.max(0, Math.floor(options.maxLines ?? 0));
  const lines = text.split(/\r?\n/);
  const overLineLimit = maxLines > 0 && lines.length > maxLines;
  const overCharLimit = maxChars > 0 && text.length > maxChars;
  if (!overLineLimit && !overCharLimit) {
    return { text, truncated: false, droppedLines: 0 };
  }

  const preserveHead = Math.max(0, Math.floor(options.preserveHead ?? 20));
  const preserveTail = Math.max(0, Math.floor(options.preserveTail ?? 20));
  const priorityPatterns = options.priorityPatterns ?? [];
  const priorityLines = priorityPatterns.length
    ? lines.filter((line) => priorityPatterns.some((pattern) => pattern.test(line)))
    : [];

  const head = lines.slice(0, preserveHead);
  const tail = preserveTail > 0 ? lines.slice(-preserveTail) : [];
  const selected = [...head];
  for (const line of priorityLines) {
    if (!selected.includes(line)) selected.push(line);
  }
  const tailStart = lines.length - tail.length;
  tail.forEach((line, offset) => {
    const originalIndex = tailStart + offset;
    if (originalIndex >= preserveHead && !selected.includes(line)) selected.push(line);
  });

  const droppedLines = Math.max(0, lines.length - selected.length);
  let result = [
    ...selected.slice(0, head.length),
    `[rtk:truncated ${droppedLines} lines]`,
    ...selected.slice(head.length),
  ].join("\n");

  if (maxChars > 0 && result.length > maxChars) {
    const marker = "\n[rtk:truncated by chars]\n";
    const budget = Math.max(0, maxChars - marker.length);
    if (budget === 0) {
      result = marker.slice(0, maxChars);
      return { text: result, truncated: true, droppedLines };
    }
    const headChars = Math.ceil(budget * 0.55);
    const tailChars = Math.max(0, budget - headChars);
    const tailText = tailChars > 0 ? result.slice(-tailChars) : "";
    result = `${result.slice(0, headChars)}${marker}${tailText}`;
    if (result.length > maxChars) result = result.slice(0, maxChars);
  }

  return { text: result, truncated: true, droppedLines };
}

import { createRequire } from "node:module";
// Type-only import: erased at build time, so it never forces the `typescript`
// package to be present at runtime. The value handle is resolved lazily below.
import type * as TypeScriptApi from "typescript";

type TypeScriptModule = typeof import("typescript");

// `typescript` is a devDependency used only for opt-in AST-based comment
// stripping. A production-lean deploy (`npm run build && npm prune --omit=dev`,
// recommended in Discussion #6956) removes it, so importing it eagerly at module
// top level broke *every* Compression Context page (#7096). Resolve it lazily on
// first use and degrade to a no-op when it is unavailable.
let typeScriptModule: TypeScriptModule | null | undefined;
let warnedMissingTypeScript = false;
let loadTypeScriptModule: () => TypeScriptModule | null = defaultLoadTypeScriptModule;

function defaultLoadTypeScriptModule(): TypeScriptModule | null {
  try {
    const requireFromHere = createRequire(import.meta.url);
    return requireFromHere("typescript") as TypeScriptModule;
  } catch {
    return null;
  }
}

function resolveTypeScript(): TypeScriptModule | null {
  if (typeScriptModule === undefined) {
    typeScriptModule = loadTypeScriptModule();
    if (!typeScriptModule && !warnedMissingTypeScript) {
      warnedMissingTypeScript = true;
      // One-time warning: compression still works, just without AST-based
      // code-comment stripping (which is opt-in and off by default anyway).
      console.warn(
        "[compression/rtk] optional dependency 'typescript' is not installed; " +
          "skipping AST-based code-comment stripping (compression still works). " +
          "Install 'typescript' to re-enable it."
      );
    }
  }
  return typeScriptModule;
}

/**
 * @internal Test seam — override the lazy TypeScript loader (pass `null` to
 * restore the default) and reset the cache so graceful degradation can be
 * exercised without uninstalling the package. Not part of the public API.
 */
export function __setTypeScriptModuleLoaderForTests(
  loader: (() => TypeScriptModule | null) | null
): void {
  loadTypeScriptModule = loader ?? defaultLoadTypeScriptModule;
  typeScriptModule = undefined;
  warnedMissingTypeScript = false;
}

export type CodeLanguage =
  | "javascript"
  | "typescript"
  | "python"
  | "rust"
  | "go"
  | "ruby"
  | "java"
  | "unknown";

export interface CodeStripperOptions {
  removeComments?: boolean;
  removeEmptyLines?: boolean;
  collapseWhitespace?: boolean;
  preserveDocstrings?: boolean;
}

const LANGUAGE_ALIASES: Record<string, CodeLanguage> = {
  js: "javascript",
  jsx: "javascript",
  javascript: "javascript",
  ts: "typescript",
  tsx: "typescript",
  typescript: "typescript",
  py: "python",
  python: "python",
  rs: "rust",
  rust: "rust",
  go: "go",
  rb: "ruby",
  ruby: "ruby",
  java: "java",
};

export function normalizeCodeLanguage(language?: string | null): CodeLanguage {
  if (!language) return "unknown";
  return LANGUAGE_ALIASES[language.trim().toLowerCase()] ?? "unknown";
}

export function detectCodeLanguage(text: string): CodeLanguage {
  if (/\b(?:interface|type)\s+\w+\s*=|:\s*(?:string|number|boolean)\b/.test(text)) {
    return "typescript";
  }
  if (/\b(?:const|let|function|import|export)\b|=>/.test(text)) return "javascript";
  if (/\bdef\s+\w+\(|\bimport\s+\w+|print\(/.test(text)) return "python";
  if (/\bfn\s+\w+\(|\blet\s+mut\b|println!\(/.test(text)) return "rust";
  if (/\bfunc\s+\w+\(|package\s+\w+/.test(text)) return "go";
  if (/\bclass\s+\w+|System\.out\.println/.test(text)) return "java";
  if (/\bdef\s+\w+|puts\s+|end\s*$/.test(text)) return "ruby";
  return "unknown";
}

/**
 * Remove JS/TS comments using the TypeScript parser (R1/N3). Using the parser —
 * not a regex or the raw scanner — means string, template and regex literals are
 * never mistaken for comments (the scanner alone cannot tell a regex from a
 * division without parser context). Bails out entirely when JSX is present so
 * JSX expression-container comments are never corrupted.
 */
function stripJsTsComments(text: string, preserveDocstrings: boolean): string {
  const ts = resolveTypeScript();
  // Graceful degradation: when `typescript` is unavailable (e.g. after
  // `npm prune --omit=dev`), skip AST-based comment stripping and leave the
  // code untouched rather than crashing (#7096).
  if (!ts) return text;

  const source = ts.createSourceFile(
    "snippet.tsx",
    text,
    ts.ScriptTarget.Latest,
    /* setParentNodes */ true,
    ts.ScriptKind.TSX
  );

  let hasJsx = false;
  const detectJsx = (node: TypeScriptApi.Node): void => {
    if (ts.isJsxElement(node) || ts.isJsxSelfClosingElement(node) || ts.isJsxFragment(node)) {
      hasJsx = true;
      return;
    }
    if (!hasJsx) ts.forEachChild(node, detectJsx);
  };
  detectJsx(source);
  if (hasJsx) return text;

  const ranges = new Map<number, TypeScriptApi.CommentRange>();
  const collect = (node: TypeScriptApi.Node): void => {
    for (const range of ts.getLeadingCommentRanges(text, node.getFullStart()) ?? []) {
      ranges.set(range.pos, range);
    }
    for (const range of ts.getTrailingCommentRanges(text, node.getEnd()) ?? []) {
      ranges.set(range.pos, range);
    }
    ts.forEachChild(node, collect);
  };
  collect(source);

  if (ranges.size === 0) return text;
  let result = text;
  for (const range of [...ranges.values()].sort((a, b) => b.pos - a.pos)) {
    // Keep JSDoc/docstring block comments (`/** ... */`) when preserveDocstrings is on — they
    // carry API documentation that is worth more than the bytes they cost.
    if (preserveDocstrings && text.startsWith("/**", range.pos)) continue;
    result = result.slice(0, range.pos) + result.slice(range.end);
  }
  return result;
}

export function stripCode(
  text: string,
  language: CodeLanguage = "unknown",
  options: CodeStripperOptions = {}
): {
  text: string;
  strippedLines: number;
  language: CodeLanguage;
} {
  const resolvedLanguage = language === "unknown" ? detectCodeLanguage(text) : language;
  const opts: Required<CodeStripperOptions> = {
    // Opt-in (default false): historically this flag was read but never applied,
    // so the effective behaviour was "preserve". Keeping the default at preserve
    // avoids a silent production change; callers opt in with removeComments:true.
    removeComments: options.removeComments === true,
    removeEmptyLines: options.removeEmptyLines !== false,
    collapseWhitespace: options.collapseWhitespace !== false,
    preserveDocstrings: options.preserveDocstrings === true,
  };
  const originalLines = text.split(/\r?\n/).length;
  let result = text;

  if (
    opts.removeComments &&
    (resolvedLanguage === "javascript" || resolvedLanguage === "typescript")
  ) {
    result = stripJsTsComments(result, opts.preserveDocstrings);
  }

  if (opts.removeEmptyLines) result = result.replace(/^\s*$(?:\r?\n)?/gm, "");
  if (opts.collapseWhitespace) {
    result = result
      .split(/\r?\n/)
      .map((line) => line.replace(/[ \t]+$/g, ""))
      .join("\n");
  }

  result = result.replace(/^\s*\n/, "").replace(/\n\s*$/, "");
  const strippedLines = Math.max(0, originalLines - (result ? result.split(/\r?\n/).length : 0));
  return { text: result, strippedLines, language: resolvedLanguage };
}

import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import crypto from "node:crypto";

import type { CommandSample } from "./discover.ts";

export type RtkRawOutputRetention = "never" | "failures" | "always";

export interface RtkRawOutputPointer {
  id: string;
  path: string;
  bytes: number;
  sha256: string;
  redacted: boolean;
}

const SECRET_PATTERNS: Array<[RegExp, string]> = [
  [/\b(sk-[A-Za-z0-9_-]{16,})\b/g, "[REDACTED_OPENAI_KEY]"],
  [/\b(xox[baprs]-[A-Za-z0-9-]{16,})\b/g, "[REDACTED_SLACK_TOKEN]"],
  [/\b(AKIA[0-9A-Z]{16})\b/g, "[REDACTED_AWS_KEY]"],
  // key=value / key: value for common credential field names (flat alternation — no nesting,
  // so no ReDoS). Covers names the bare token/secret/password set misses (private_key, etc).
  [
    /((?:api[_-]?key|api[_-]?token|access[_-]?key|access[_-]?token|client[_-]?secret|auth[_-]?token|private[_-]?key|secret[_-]?key|credentials?|token|secret|password)\s*[:=]\s*)("[^"]+"|'[^']+'|[^\s]+)/gi,
    "$1[REDACTED]",
  ],
  // Authorization / Proxy-Authorization with Bearer OR Basic (curl -v emits Basic <base64>).
  [/((?:Proxy-)?Authorization:\s*(?:Bearer|Basic)\s+)[A-Za-z0-9._~+/-]+=*/gi, "$1[REDACTED]"],
];

function dataDir(): string {
  return process.env.DATA_DIR || path.join(os.homedir(), ".omniroute");
}

function safeId(seed: string): string {
  return crypto.createHash("sha256").update(seed).digest("hex").slice(0, 24);
}

function safeUtf8Slice(value: string, maxBytes: number): string {
  if (maxBytes <= 0 || Buffer.byteLength(value, "utf8") <= maxBytes) return value;
  let bytes = 0;
  let output = "";
  for (const char of value) {
    const len = Buffer.byteLength(char, "utf8");
    if (bytes + len > maxBytes) break;
    output += char;
    bytes += len;
  }
  return `${output}\n\n--- truncated at ${maxBytes} bytes ---`;
}

export function redactRtkRawOutput(value: string): { text: string; redacted: boolean } {
  let redacted = false;
  let text = value;
  for (const [pattern, replacement] of SECRET_PATTERNS) {
    const next = text.replace(pattern, (...args: string[]) => {
      redacted = true;
      return typeof replacement === "string"
        ? replacement.replace("$1", args[1] ?? "")
        : replacement;
    });
    text = next;
  }
  return { text, redacted };
}

export function isLikelyFailureOutput(value: string): boolean {
  return /\b(error|failed|failure|exception|traceback|panic|fatal|critical|TS\d{4}|FAIL)\b/i.test(
    value
  );
}

export function maybePersistRtkRawOutput(
  raw: string,
  options: {
    retention: RtkRawOutputRetention;
    command?: string | null;
    maxBytes?: number;
    failure?: boolean;
  }
): RtkRawOutputPointer | null {
  if (options.retention === "never") return null;
  const failure = options.failure ?? isLikelyFailureOutput(raw);
  if (options.retention === "failures" && !failure) return null;
  if (raw.trim().length === 0) return null;

  const maxBytes = Math.max(1024, Math.floor(options.maxBytes ?? 1_048_576));
  const redaction = redactRtkRawOutput(safeUtf8Slice(raw, maxBytes));
  const now = Date.now();
  const commandSlug = (options.command || "tool-output")
    .replace(/[^A-Za-z0-9_-]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .slice(0, 48);
  const id = safeId(`${now}:${commandSlug}:${raw.length}:${redaction.text}`);
  const dir = path.join(dataDir(), "rtk", "raw-output");
  const filePath = path.join(dir, `${now}-${commandSlug || "tool-output"}-${id}.log`);
  try {
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(filePath, redaction.text);
  } catch {
    // Best-effort capture: a disk error (ENOSPC / EACCES / read-only DATA_DIR) must NEVER
    // fail the compression pipeline. Skip the capture, exactly like retention "never".
    return null;
  }

  // Sidecar metadata: the .log filename only carries a lossy command SLUG, so persist
  // the FULL command (and timestamp/flags) next to it. Keeps the .log pure output (the
  // raw-output recovery route still returns it verbatim) while letting the RTK
  // learn/discover sample source recover the exact command. Best-effort: a sidecar
  // write failure never fails the capture.
  try {
    const metaPath = filePath.replace(/\.log$/, ".meta.json");
    fs.writeFileSync(
      metaPath,
      JSON.stringify({
        command: options.command ?? null,
        timestamp: now,
        failure,
        redacted: redaction.redacted,
        bytes: Buffer.byteLength(redaction.text, "utf8"),
      })
    );
  } catch {
    // Sidecar is an optimisation for learn/discover; the .log (with slug) still works.
  }

  return {
    id,
    path: filePath,
    bytes: Buffer.byteLength(redaction.text, "utf8"),
    sha256: crypto.createHash("sha256").update(redaction.text).digest("hex"),
    redacted: redaction.redacted,
  };
}

export function readRtkRawOutput(pointerId: string): string | null {
  const dir = path.join(dataDir(), "rtk", "raw-output");
  if (!fs.existsSync(dir)) return null;
  const entry = fs
    .readdirSync(dir)
    .find((file) => file.endsWith(".log") && file.includes(pointerId));
  if (!entry) return null;
  const fullPath = path.join(dir, entry);
  if (!fullPath.startsWith(dir)) return null;
  return fs.readFileSync(fullPath, "utf8");
}

/** Recover the command for a `.log` from its filename slug (legacy, sidecar-less captures). */
function commandFromSlug(fileName: string): string {
  // `<timestamp>-<slug>-<id>.log` → strip the leading timestamp and the trailing id.
  const slug = fileName
    .replace(/^\d+-/, "")
    .replace(/-[0-9a-f]{24}\.log$/i, "")
    .replace(/\.log$/i, "");
  return slug.replace(/_+/g, " ").trim();
}

/**
 * Read the opt-in RTK raw-output store (`DATA_DIR/rtk/raw-output/*.log`) into
 * `CommandSample[]` for the pure miners `discoverRepeatedNoise()` / `suggestFilter()`.
 *
 * The command comes from the `.meta.json` sidecar when present (exact), else from the
 * filename slug (lossy, for legacy captures). Empty/unreadable entries are skipped.
 * Returns the most-recent-first samples, capped at `opts.limit` (default 500) to bound
 * memory. No throw: a corrupt entry is dropped, not propagated.
 */
export function listRtkCommandSamples(opts: { limit?: number } = {}): CommandSample[] {
  const dir = path.join(dataDir(), "rtk", "raw-output");
  if (!fs.existsSync(dir)) return [];
  const limit = Math.max(1, Math.floor(opts.limit ?? 500));

  let logs: string[];
  try {
    logs = fs.readdirSync(dir).filter((f) => f.endsWith(".log"));
  } catch {
    return [];
  }
  // Newest first: the filename is timestamp-prefixed, so a reverse lexical sort works.
  logs.sort((a, b) => (a < b ? 1 : a > b ? -1 : 0));

  const samples: CommandSample[] = [];
  for (const fileName of logs) {
    if (samples.length >= limit) break;
    const fullPath = path.join(dir, fileName);
    if (!fullPath.startsWith(dir)) continue;
    let output: string;
    try {
      output = fs.readFileSync(fullPath, "utf8");
    } catch {
      continue;
    }
    if (output.trim().length === 0) continue;

    let command = "";
    try {
      const metaRaw = fs.readFileSync(fullPath.replace(/\.log$/, ".meta.json"), "utf8");
      const meta = JSON.parse(metaRaw) as { command?: unknown };
      if (typeof meta.command === "string" && meta.command.trim()) command = meta.command.trim();
    } catch {
      // No/!invalid sidecar → fall back to the filename slug below.
    }
    if (!command) command = commandFromSlug(fileName) || "tool-output";

    samples.push({ command, output });
  }
  return samples;
}

