export interface RenderResult {
  text: string;
  changed: boolean;
  renderer: string; // nome do renderer aplicado (ou "" se nenhum)
}

export type Renderer = (text: string, detection: CommandDetectionResult) => RenderResult;

export const NO_RENDER = (text: string): RenderResult => ({ text, changed: false, renderer: "" });
export type { RtkConfig, CommandDetectionResult };

import type { RenderResult, CommandDetectionResult } from "./types.ts";
import { NO_RENDER } from "./types.ts";

/**
 * RTK semantic renderer for `git diff` / `git show` output.
 *
 * Keeps only:
 *  - `diff --git a/... b/...` file header lines
 *  - `@@ ... @@` hunk headers
 *  - change lines starting with `+` or `-` (but NOT `+++`/`---`)
 *
 * Everything else (context lines, index lines, mode lines, etc.) is dropped.
 * If no hunk header is found, returns no-op (input is not a real diff).
 */
export function renderGitDiff(text: string, _detection: CommandDetectionResult): RenderResult {
  // Guard: must have at least one hunk header
  if (!text.includes("@@ ")) {
    return NO_RENDER(text);
  }

  const kept: string[] = [];
  for (const line of text.split("\n")) {
    if (
      line.startsWith("diff --git ") ||
      line.startsWith("@@ ")
    ) {
      kept.push(line);
    } else if (/^[+-](?![+-])/.test(line)) {
      // change line (+foo or -foo) but NOT +++ or ---
      kept.push(line);
    }
    // drop: context lines (space), index lines, --- a/, +++ b/, mode lines, etc.
  }

  const out = kept.join("\n");
  if (out === text) return NO_RENDER(text);

  return { text: out, changed: true, renderer: "git-diff" };
}

import type { RenderResult, CommandDetectionResult } from "./types.ts";
import { NO_RENDER } from "./types.ts";

/**
 * RTK semantic renderer for test suite output (pytest, jest, vitest, eslint).
 *
 * CRITICAL safety guard: only collapses when output indicates TOTAL success.
 * ANY sign of failure forces a no-op to preserve full diagnostics.
 *
 * Failure signals (force no-op):
 *  - /\bFAIL\b/ in the text
 *  - /failed/i paired with a nonzero count (e.g. "1 failed")
 *  - ✖ symbol
 *  - "Error" anywhere
 *  - "Traceback" (Python)
 *  - "AssertionError"
 *
 * When green, extract the summary line and return it.
 * If no recognizable summary line is found, no-op.
 */
export function renderTestGreen(text: string, _detection: CommandDetectionResult): RenderResult {
  // Strip ANSI color codes before applying the failure guards. jest/vitest emit a
  // colored "FAIL" status whose preceding ANSI byte ("m" of [31m) is a word
  // character, defeating a /\bFAIL\b/ boundary on the raw string. Guards run on the
  // stripped copy; the original `text` is what we return on a no-op (lossless).
  const stripped = text.replace(/\[[0-9;]*m/g, "");

  // Failure guard — must check FIRST; never weaken
  if (/\bFAIL\b/.test(stripped)) return NO_RENDER(text);
  if (/✖/.test(stripped)) return NO_RENDER(text);
  if (/Error/.test(stripped)) return NO_RENDER(text);
  if (/Traceback/.test(stripped)) return NO_RENDER(text);
  if (/AssertionError/.test(stripped)) return NO_RENDER(text);

  // "failed" with a nonzero count, e.g. "1 failed" or "failed: 3"
  const failedMatch = stripped.match(/(\d+)\s+failed/i) ?? stripped.match(/failed[:\s]+(\d+)/i);
  if (failedMatch && parseInt(failedMatch[1], 10) > 0) return NO_RENDER(text);

  // Try to extract a recognised summary line (from the stripped copy → ANSI-free)
  const summary = extractSummaryLine(stripped);
  if (!summary) return NO_RENDER(text);

  return { text: summary, changed: true, renderer: "test-green" };
}

function extractSummaryLine(text: string): string | null {
  const lines = text.split("\n");

  // pytest: === N passed in X.Xs ===  (also handles variants like  === N passed, M warning ===)
  for (const line of lines) {
    if (/={3,}\s+\d+\s+passed/.test(line)) return line.trim();
  }

  // jest / vitest: "Tests: N passed, N total" or "Test Suites: ... Tests: ..."
  for (const line of lines) {
    if (/Tests:\s+\d+\s+passed/.test(line)) return line.trim();
  }

  // vitest / jest run summary line: "✓ N tests passed"
  for (const line of lines) {
    if (/\d+\s+tests?\s+passed/i.test(line)) return line.trim();
  }

  // eslint / build-eslint: empty output = clean; if we reach here with no failures, synthesize
  if (text.trim() === "" || text.trim().startsWith("\n")) {
    return "ESLint: 0 problems found";
  }

  return null;
}

import type { RenderResult, CommandDetectionResult } from "./types.ts";
import { NO_RENDER } from "./types.ts";

/**
 * RTK semantic renderer for `terraform plan` / `tofu plan` output.
 *
 * Extracts:
 *  - The canonical summary line `Plan: N to add, M to change, K to destroy.`
 *    reformatted as `Plan: +N ~M -K`
 *  - Resource lines `# <addr> will be <verb>`
 *
 * "No changes." output ⇒ no-op (already short enough).
 * If no `Plan:` line is found ⇒ no-op (conservative).
 */
export function renderTerraformPlan(
  text: string,
  _detection: CommandDetectionResult,
): RenderResult {
  // "No changes" is already compact — idempotent no-op
  if (/^No changes\./m.test(text)) return NO_RENDER(text);

  // Extract the canonical Plan summary line
  const planMatch = text.match(/Plan:\s+(\d+)\s+to add,\s+(\d+)\s+to change,\s+(\d+)\s+to destroy/);
  if (!planMatch) return NO_RENDER(text);

  const [, add, change, destroy] = planMatch;
  const summary = `Plan: +${add} ~${change} -${destroy}`;

  // Collect resource address lines: "  # <addr> will be <verb>"
  const resources: string[] = [];
  for (const line of text.split("\n")) {
    const m = line.match(/^\s+#\s+(\S+)\s+will\s+be\s+\S+/);
    if (m) {
      resources.push(`  # ${m[1]} will be ${line.trim().replace(/^#\s+\S+\s+will\s+be\s+/, "")}`);
    }
  }

  const out = [summary, ...resources].join("\n");
  return { text: out, changed: true, renderer: "terraform-plan" };
}

import type { RenderResult, CommandDetectionResult } from "./types.ts";
import { NO_RENDER } from "./types.ts";

const MAX_TABLE_ROWS = 200;
const MAX_COLUMNS = 5;
// Priority column names to prefer when choosing which columns to display
const PRIORITY_KEYS = ["name", "id", "status", "type", "kind"];

/**
 * RTK semantic renderer for structured JSON array output (aws, kubectl, etc.).
 *
 * Only renders if:
 *  - Input parses as JSON (or contains a JSON array substring)
 *  - Result is an array of ≥2 homogeneous objects (same dominant scalar keys)
 *
 * Output: minimal TSV-like table (header + rows). Large arrays (>200 items)
 * are capped with a trailing "… (+K more)" line.
 *
 * All other shapes ⇒ no-op (conservative).
 */
export function renderStructuredTable(
  text: string,
  _detection: CommandDetectionResult,
): RenderResult {
  const parsed = tryParse(text.trim());
  if (!parsed) return NO_RENDER(text);

  // Must be an array of ≥2 objects
  if (!Array.isArray(parsed) || parsed.length < 2) return NO_RENDER(text);

  const items = parsed as unknown[];
  // Every item must be a non-null, non-array object
  if (!items.every((item) => item !== null && typeof item === "object" && !Array.isArray(item))) {
    return NO_RENDER(text);
  }

  const objects = items as Record<string, unknown>[];

  // Collect scalar keys across all objects, count occurrences
  const keyCount: Record<string, number> = {};
  for (const obj of objects) {
    for (const [k, v] of Object.entries(obj)) {
      if (v === null || typeof v !== "object") {
        keyCount[k] = (keyCount[k] ?? 0) + 1;
      }
    }
  }

  if (Object.keys(keyCount).length === 0) return NO_RENDER(text);

  // Choose columns: prioritize PRIORITY_KEYS, then by frequency, cap at MAX_COLUMNS
  const threshold = Math.floor(objects.length / 2);
  const candidateKeys = Object.entries(keyCount)
    .filter(([, count]) => count >= threshold)
    .map(([k]) => k);

  const priorityChosen = PRIORITY_KEYS.filter((k) => candidateKeys.includes(k));
  const rest = candidateKeys
    .filter((k) => !PRIORITY_KEYS.includes(k))
    .sort((a, b) => (keyCount[b] ?? 0) - (keyCount[a] ?? 0));

  const columns = [...priorityChosen, ...rest].slice(0, MAX_COLUMNS);
  if (columns.length === 0) return NO_RENDER(text);

  // Build table
  const rows = objects.slice(0, MAX_TABLE_ROWS);
  const extra = objects.length > MAX_TABLE_ROWS ? objects.length - MAX_TABLE_ROWS : 0;

  const header = columns.join("\t");
  const body = rows
    .map((obj) => columns.map((k) => String(obj[k] ?? "")).join("\t"))
    .join("\n");

  const out = extra > 0 ? `${header}\n${body}\n… (+${extra} more)` : `${header}\n${body}`;

  return { text: out, changed: true, renderer: "structured-table" };
}

function tryParse(text: string): unknown {
  // Direct parse
  try {
    return JSON.parse(text);
  } catch {
    // Try to find the largest [...] substring
    const start = text.indexOf("[");
    const end = text.lastIndexOf("]");
    if (start !== -1 && end > start) {
      try {
        return JSON.parse(text.slice(start, end + 1));
      } catch {
        return null;
      }
    }
    return null;
  }
}

import { estimateCompressionTokens } from "../../stats.ts";
import {
  getRtkFilterLoadDiagnostics,
  loadRtkFilters,
  type RtkFilterLoadDiagnostic,
} from "./filterLoader.ts";
import { applyLineFilter } from "./lineFilter.ts";

export interface RtkFilterTestOutcome {
  filterId: string;
  testName: string;
  passed: boolean;
  actual: string;
  expected: string;
}

export interface RtkFilterBenchmarkRow {
  category: string;
  filters: number;
  tests: number;
  averageSavingsPercent: number;
}

export interface RtkVerifyResult {
  passed: boolean;
  outcomes: RtkFilterTestOutcome[];
  filtersWithoutTests: string[];
  benchmark: RtkFilterBenchmarkRow[];
  diagnostics: RtkFilterLoadDiagnostic[];
}

function trimComparable(value: string): string {
  return value.replace(/\n+$/g, "");
}

export function runRtkFilterTests(
  options: {
    requireAll?: boolean;
    customFiltersEnabled?: boolean;
    trustProjectFilters?: boolean;
  } = {}
): RtkVerifyResult {
  const filters = loadRtkFilters({
    refresh: true,
    customFiltersEnabled: options.customFiltersEnabled,
    trustProjectFilters: options.trustProjectFilters,
  });
  const outcomes: RtkFilterTestOutcome[] = [];
  const filtersWithoutTests: string[] = [];
  const benchmarkByCategory = new Map<
    string,
    { filters: Set<string>; tests: number; savingsTotal: number }
  >();

  for (const filter of filters) {
    const categoryStats = benchmarkByCategory.get(filter.category) ?? {
      filters: new Set<string>(),
      tests: 0,
      savingsTotal: 0,
    };
    categoryStats.filters.add(filter.id);
    benchmarkByCategory.set(filter.category, categoryStats);

    if (filter.tests.length === 0) {
      filtersWithoutTests.push(filter.id);
      continue;
    }

    for (const test of filter.tests) {
      const result = applyLineFilter(test.input, filter).text;
      const actual = trimComparable(result);
      const expected = trimComparable(test.expected);
      const originalTokens = estimateCompressionTokens(test.input);
      const compressedTokens = estimateCompressionTokens(result);
      const savings =
        originalTokens > 0 ? ((originalTokens - compressedTokens) / originalTokens) * 100 : 0;
      categoryStats.tests += 1;
      categoryStats.savingsTotal += Math.max(0, savings);
      outcomes.push({
        filterId: filter.id,
        testName: test.name,
        passed: actual === expected,
        actual,
        expected,
      });
    }
  }

  const benchmark = Array.from(benchmarkByCategory.entries())
    .map(([category, value]) => ({
      category,
      filters: value.filters.size,
      tests: value.tests,
      averageSavingsPercent:
        value.tests > 0 ? Math.round((value.savingsTotal / value.tests) * 100) / 100 : 0,
    }))
    .sort((a, b) => a.category.localeCompare(b.category));

  const failed = outcomes.some((outcome) => !outcome.passed);
  return {
    passed: !failed && (!options.requireAll || filtersWithoutTests.length === 0),
    outcomes,
    filtersWithoutTests,
    benchmark,
    diagnostics: options.customFiltersEnabled === false ? [] : getRtkFilterLoadDiagnostics(),
  };
}

/**
 * RTK discover — R7 / N7
 *
 * Pure function, no I/O.  DB wiring (reading from call_logs) is a follow-up task.
 * The function takes an in-memory array of CommandSample values so it can be
 * fully unit-tested with synthetic data.
 *
 * Finds line-templates that recur across many samples and are therefore good
 * DROP candidates (high-frequency noise) or PRESERVE candidates (errors/summaries).
 */

import { normalizeLine } from "./grouper.ts";

// ---------------------------------------------------------------------------
// Extended normalization for cross-sample mining
// ---------------------------------------------------------------------------

/**
 * Extends grouper.ts's normalizeLine with additional substitutions relevant
 * for mining command output across many samples:
 *
 *   8. npm/pip package names + versions: `left-pad@1.2.3` → `<PKG>@<N>`
 *      (the grouper replaces the version number but not the package name, so
 *      different packages give different templates — this collapses them).
 *   9. Exit codes and error codes: `E404`, `ENOENT`, `E2BIG` → `<CODE>`
 *  10. Numeric suffixes (time/size): `5s`, `120ms`, `4.2kb` → `<N><SFX>`
 *      collapsed to a single placeholder so "in 5s" and "in 2s" normalise alike.
 *
 * Applies AFTER grouper normalizeLine so all its substitutions are already done.
 */
export function discoverNormalizeLine(line: string): string {
  let s = normalizeLine(line);
  // npm/pip package identifiers with version: word@version → <PKG>@<N>
  // Handles both original (left-pad@1.2.3) and already-normalised (left-pad@<N>)
  // Bounded quantifiers ({0,N}) are mandatory: `[\w]` ⊂ `[\w.-]` followed by a
  // required `@` is the classic catastrophic-backtracking shape on a long
  // word-char run with no `@` (CLAUDE.md ReDoS rule). Real package names are short.
  s = s.replace(/[\w][\w.-]{0,128}@(?:<N>|\d[\w.-]{0,64})/g, "<PKG>@<N>");
  // Error/exit codes like E404, ENOENT, E2BIG, EACCES
  s = s.replace(/\bE[A-Z0-9]{2,}\b/g, "<CODE>");
  // Numeric values with attached units: 5s, 120ms, 4kb, 12MB, 0.5s, etc.
  s = s.replace(/\b\d+(?:\.\d+)?(?:ms|[smhd]|[kmg]b?)\b/gi, "<N>");
  // Also collapse the already-substituted <N> followed by a unit suffix leftover
  s = s.replace(/<N>(?:ms|[smhd]|[kmg]b?)\b/gi, "<N>");
  // Collapse repeated whitespace again after substitutions
  s = s.replace(/\s+/g, " ").trim();
  return s;
}

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

/** A captured command invocation with its combined stdout/stderr text. */
export interface CommandSample {
  /** The command string as typed by the user / agent, e.g. "npm install". */
  command: string;
  /** The full output (stdout + stderr) of that invocation. */
  output: string;
}

/**
 * A recurring line-template surfaced by discoverRepeatedNoise.
 * The `pattern` is a regex-compatible string derived from the normalised line.
 */
export interface NoiseCandidate {
  /** A regex-compatible string matching the recurring line template. */
  pattern: string;
  /** Number of samples in which this normalised pattern appeared at least once. */
  hits: number;
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Convert a normalised line (with <N> placeholders) to a regex pattern that
 * is safe to use in `new RegExp(pattern, "i")`.
 *
 * Strategy:
 *   1. Escape all regex special chars in the normalised form.
 *   2. Replace the literal placeholder `<N>` (already normalised) with `[\S]+`
 *      so the pattern matches the volatile fragments in real lines.
 *   3. Anchor loosely with a leading `^` so it matches from the start of a line
 *      (RTK dropPatterns are matched line-by-line via a startsWith / ^-anchored regex).
 */
function normalizedToPattern(normalised: string): string {
  // Escape regex special chars (< and > are not special, so placeholders survive intact)
  const escaped = normalised.replace(/[$()*+.?[\\\]^{|}]/g, "\\$&");
  // Replace placeholder tokens with wildcard regex fragments
  const withWildcards = escaped
    .replace(/<N>/g, "[\\S]+")
    .replace(/<PKG>/g, "[\\S]+")
    .replace(/<CODE>/g, "[A-Z][A-Z0-9]+");
  return `^${withWildcards}`;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Scan a set of command output samples and return a ranked list of line-templates
 * that appear frequently enough to be useful DROP candidates.
 *
 * Only templates that appear in MORE THAN ONE sample are included (single-occurrence
 * lines are noise-specific, not structural noise).  Results are sorted descending
 * by hit count.
 *
 * No I/O — pass samples from any source (DB, fixtures, user input).
 */
export function discoverRepeatedNoise(samples: CommandSample[]): NoiseCandidate[] {
  if (samples.length === 0) return [];

  // Count how many samples contain each normalised line (at least once per sample).
  const hitsBySample = new Map<string, Set<number>>();

  for (let i = 0; i < samples.length; i++) {
    const lines = samples[i].output.split(/\r?\n/);
    const seenInThisSample = new Set<string>();

    for (const raw of lines) {
      const trimmed = raw.trim();
      if (trimmed.length === 0) continue;
      const norm = discoverNormalizeLine(trimmed);
      if (norm.length === 0) continue;
      if (seenInThisSample.has(norm)) continue; // count each normalised form once per sample
      seenInThisSample.add(norm);

      if (!hitsBySample.has(norm)) {
        hitsBySample.set(norm, new Set());
      }
      hitsBySample.get(norm)!.add(i);
    }
  }

  const candidates: NoiseCandidate[] = [];
  for (const [norm, sampleSet] of hitsBySample) {
    if (sampleSet.size <= 1) continue; // must appear in more than one sample
    candidates.push({
      pattern: normalizedToPattern(norm),
      hits: sampleSet.size,
    });
  }

  // Sort descending by hits, then alphabetically for deterministic output
  candidates.sort((a, b) => b.hits - a.hits || a.pattern.localeCompare(b.pattern));
  return candidates;
}

/**
 * RTK learn — R6 / N7
 *
 * Pure function, no I/O.  DB wiring (reading from call_logs) is a follow-up task.
 * Takes an in-memory array of CommandSample values → returns a suggested RTK
 * filter draft in the canonical RtkFilterPack shape (same JSON structure as
 * filters/pip.json, filters/make.json, etc.) so it can be reviewed and saved
 * as a real filter without conversion.
 *
 * Key design decisions
 * ───────────────────
 * 1. Drop threshold: a normalised line template is included in dropPatterns only if
 *    it recurs in ≥ DROP_THRESHOLD_RATIO of samples (default 50 %).  Single-sample
 *    noise is too specific to be useful as a filter rule.
 *
 * 2. Preserve-vs-drop conflict guard: a candidate drop pattern is silently omitted
 *    if it matches ANY line that also matches an error or summary preserve pattern.
 *    This is conservative by design — it's safer to miss a drop than to drop an
 *    important error/summary.
 *
 * 3. Error / summary heuristics (ACON-style):
 *    - errorPatterns: lines whose normalised form contains "error", "err!", "fail",
 *      "warning", "warn", "critical", "exception", "fatal", or "panic".
 *    - summaryPatterns: lines whose normalised form contains "success", "done",
 *      "complete", "built", "added", "installed", "finished", or "passed".
 *
 * 4. The output id/label is derived mechanically from the command string so the
 *    caller can save it directly without rename.
 */

import { discoverRepeatedNoise, discoverNormalizeLine, type CommandSample } from "./discover.ts";

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

/**
 * Suggested filter shape — mirrors the canonical RtkFilterPack JSON structure
 * (id / label / description / category / priority / match / rules / preserve).
 * Re-exported so callers don't need to import from filterSchema.ts.
 */
export interface SuggestedFilter {
  id: string;
  label: string;
  description: string;
  category: "generic";
  priority: number;
  match: {
    outputTypes: string[];
    commands: string[];
    patterns: string[];
  };
  rules: {
    stripAnsi: boolean;
    dropPatterns: string[];
    collapsePatterns: string[];
    includePatterns: string[];
    deduplicate: boolean;
    maxLines: number;
    headLines: number;
    tailLines: number;
    onEmpty: string;
  };
  preserve: {
    errorPatterns: string[];
    summaryPatterns: string[];
  };
  /** Metadata about the learning run — not part of the filter schema but useful for UI review. */
  _meta: {
    learnedFromSamples: number;
    dropThreshold: number;
  };
}

// ---------------------------------------------------------------------------
// Internal constants and helpers
// ---------------------------------------------------------------------------

/**
 * A normalised line template must appear in at least this fraction of samples
 * to be included as a drop pattern.  50 % is conservative — it avoids flagging
 * lines that happen to appear in only a handful of runs.
 */
const DROP_THRESHOLD_RATIO = 0.5;

/**
 * Matched against the RAW (untrimmed) output line, case-insensitive.
 *
 * Error heuristic: lines that strongly signal a failure or warning worth
 * preserving.  "WARN deprecated" (npm deprecation noise) is deliberately
 * excluded — it is structural noise, not an actionable error signal.
 * We match "ERR!" (npm error prefix), "error:" / "error " patterns, etc.
 */
const ERROR_PATTERN =
  /(?:\bERR!|\berror\s*[:/]|\bfailed?\b|\bfailure\b|\bcritical\b|\bexception\b|\bfatal\b|\bpanic\b)/i;

/**
 * Matched against the RAW output line, case-insensitive.
 * Summary heuristic: lines that indicate a successful outcome or final tally.
 */
const SUMMARY_PATTERN =
  /(?:\bsuccess(?:ful(?:ly)?)?\b|\bdone\b|\bcomplete(?:d)?\b|\bbuilt\b|\badded\b|\binstalled\b|\bfinished?\b|\bpassed?\b)/i;

/**
 * Derive a slug-friendly id from a command string, e.g.
 *   "npm install"  → "npm-install"
 *   "pip install"  → "pip-install"
 */
export function commandToId(command: string): string {
  return command
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/**
 * Build a regex anchor pattern for the command so the filter's match.commands
 * array targets this specific invocation, e.g. "^npm\\s+install\\b".
 */
function commandToMatchPattern(command: string): string {
  const parts = command.trim().split(/\s+/);
  const escaped = parts.map((p) => p.replace(/[$()*+.?[\\\]^{|}]/g, "\\$&"));
  return `^${escaped.join("\\s+")}\\b`;
}

/**
 * Test whether a raw output line (from any sample) is matched by any of the
 * given regex patterns.  Invalid patterns are silently skipped.
 */
function matchesAny(line: string, patterns: string[]): boolean {
  for (const p of patterns) {
    try {
      if (new RegExp(p, "i").test(line)) return true;
    } catch {
      // ignore invalid regex
    }
  }
  return false;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Suggest an RTK filter for `command` based on `samples`.
 *
 * The returned object is a valid RtkFilterPack-shaped draft that can be
 * saved to `open-sse/services/compression/engines/rtk/filters/<id>.json`
 * and loaded by the existing filter loader without modification.
 *
 * No I/O — DB reads are a follow-up concern handled by the caller.
 */
export function suggestFilter(command: string, samples: CommandSample[]): SuggestedFilter {
  const id = commandToId(command) || "unknown";
  const commandPattern = commandToMatchPattern(command);
  const totalSamples = samples.length;

  if (totalSamples === 0) {
    return {
      id: `suggested-${id}`,
      label: command,
      description: `Auto-suggested filter for '${command}' (0 samples — no rules derived).`,
      category: "generic",
      priority: 50,
      match: { outputTypes: [], commands: [commandPattern], patterns: [] },
      rules: {
        stripAnsi: true,
        dropPatterns: [],
        collapsePatterns: [],
        includePatterns: [],
        deduplicate: true,
        maxLines: 200,
        headLines: 30,
        tailLines: 40,
        onEmpty: `${id}: ok`,
      },
      preserve: { errorPatterns: [], summaryPatterns: [] },
      _meta: { learnedFromSamples: 0, dropThreshold: DROP_THRESHOLD_RATIO },
    };
  }

  // ── Step 1: discover recurring noise candidates ──────────────────────────
  const noiseCandidates = discoverRepeatedNoise(samples);
  const dropThresholdHits = Math.max(2, Math.ceil(totalSamples * DROP_THRESHOLD_RATIO));

  // ── Step 2: build error/summary preserve patterns from ALL lines ─────────
  // We scan every line in every sample and collect normalised forms that look
  // like errors or summaries.  Each unique normalised form becomes one pattern.
  const errorNorms = new Set<string>();
  const summaryNorms = new Set<string>();

  for (const sample of samples) {
    for (const raw of sample.output.split(/\r?\n/)) {
      const trimmed = raw.trim();
      if (!trimmed) continue;
      const norm = discoverNormalizeLine(trimmed);
      if (!norm) continue;

      // Classify using the RAW line (before normalisation) so that textual
      // signals like "ERR!" and "added N packages" are not obscured by
      // placeholder substitutions like <CODE>.
      if (ERROR_PATTERN.test(trimmed)) {
        errorNorms.add(norm);
      } else if (SUMMARY_PATTERN.test(trimmed)) {
        summaryNorms.add(norm);
      }
    }
  }

  /**
   * Convert a set of normalised lines into regex patterns (same escaping as
   * normalizedToPattern in discover.ts, but re-implemented here to avoid
   * coupling to the internal helper).
   */
  function normsToPatterns(norms: Set<string>): string[] {
    return Array.from(norms).map((norm) => {
      // Escape regex special chars (< and > are not special, so placeholders survive)
      const escaped = norm.replace(/[$()*+.?[\\\]^{|}]/g, "\\$&");
      const withWildcards = escaped
        .replace(/<N>/g, "[\\S]+")
        .replace(/<PKG>/g, "[\\S]+")
        .replace(/<CODE>/g, "[A-Z][A-Z0-9]+");
      return withWildcards; // no ^ anchor: preserve patterns are substring-matched
    });
  }

  const errorPatterns = normsToPatterns(errorNorms);
  const summaryPatterns = normsToPatterns(summaryNorms);
  const allPreservePatterns = [...errorPatterns, ...summaryPatterns];

  // ── Step 3: filter noise candidates into safe drop patterns ─────────────
  // A candidate is safe to drop only if:
  //   (a) it recurs in >= dropThresholdHits samples, AND
  //   (b) its pattern does NOT match any preserve (error/summary) line from
  //       any sample (conflict guard).
  //
  // To apply the conflict guard we also collect all raw lines matched by
  // preserve patterns, then check each drop candidate against them.

  // Collect every raw line that any preserve pattern would protect.
  const preservedRawLines: string[] = [];
  for (const sample of samples) {
    for (const raw of sample.output.split(/\r?\n/)) {
      const trimmed = raw.trim();
      if (!trimmed) continue;
      if (matchesAny(trimmed, allPreservePatterns)) {
        preservedRawLines.push(trimmed);
      }
    }
  }

  const dropPatterns: string[] = [];
  for (const candidate of noiseCandidates) {
    if (candidate.hits < dropThresholdHits) continue; // below threshold
    // Conflict guard: skip if the drop pattern matches a preserved line
    const conflictsWithPreserve = preservedRawLines.some((line) => {
      try {
        return new RegExp(candidate.pattern, "i").test(line);
      } catch {
        return false;
      }
    });
    if (conflictsWithPreserve) continue;
    dropPatterns.push(candidate.pattern);
  }

  return {
    id: `suggested-${id}`,
    label: command,
    description: `Auto-suggested filter for '${command}' learned from ${totalSamples} sample(s).`,
    category: "generic",
    priority: 50,
    match: { outputTypes: [], commands: [commandPattern], patterns: [] },
    rules: {
      stripAnsi: true,
      dropPatterns,
      collapsePatterns: [],
      includePatterns: [...errorPatterns, ...summaryPatterns],
      deduplicate: true,
      maxLines: 200,
      headLines: 30,
      tailLines: 40,
      onEmpty: `${id}: ok`,
    },
    preserve: { errorPatterns, summaryPatterns },
    _meta: { learnedFromSamples: totalSamples, dropThreshold: DROP_THRESHOLD_RATIO },
  };
}

/**
 * session-dedup compression engine (R11 / N2 / TO1)
 *
 * Content-addressed cross-turn deduplication, inspired by the TokenMizer
 * session-graph + line-dedup blueprint (arXiv 2606.06337) and sqz prior-art.
 *
 * Algorithm (two-pass, suffix-block content-addressed):
 *   Pass 1 — scan all non-system messages. For each message, enumerate suffix
 *             line blocks (lines[start..end-of-message]) that meet minBlockChars
 *             and minBlockLines. Hash each block. Record the first message that
 *             owns each hash.
 *   Pass 2 — for each non-system message (index i), find blocks whose hash was
 *             first seen in a STRICTLY EARLIER message (index j < i). Replace the
 *             LONGEST such block's text with `[dedup:ref sha=<8hex>]`.
 *             First occurrence is always kept intact.
 *
 * Greedy, longest-first replacement: sort duplicate blocks by length descending;
 * replace the longest block first so shorter overlapping candidates are skipped.
 *
 * Conservative guards:
 *   - Never touch `role: "system"`.
 *   - Never touch multipart content parts other than `type: "text"`.
 *   - Only dedup blocks ≥ minBlockChars (default 80 chars) AND ≥ MIN_BLOCK_LINES lines.
 *   - First occurrence is ALWAYS kept intact; only later identical occurrences are replaced.
 *
 * Reconstruction:
 *   Replace every `[dedup:ref sha=XXXXXXXX]` marker with the original block text
 *   from the reverse map attached as `__sessionDedupMap__` on the body object.
 */

import crypto from "node:crypto";
import { createCompressionStats } from "../../stats.ts";
import { runFuzzyPass } from "./fuzzy.ts";
import type {
  CompressionEngine,
  CompressionEngineApplyOptions,
  EngineConfigField,
  EngineValidationResult,
} from "../types.ts";
import type { CompressionResult } from "../../types.ts";

// ─── constants ────────────────────────────────────────────────────────────────

const ENGINE_ID = "session-dedup";
/** Minimum block character count to be a dedup candidate. */
const DEFAULT_MIN_BLOCK_CHARS = 80;
/** Minimum number of lines a block must span to be a dedup candidate. */
const MIN_BLOCK_LINES = 3;
/**
 * Request-wide ceiling for the suffix strings materialized by the exact pass.
 * 32 MiB keeps ordinary sessions byte-identical while preventing line-rich inputs
 * from retaining a quadratic graph of suffix copies.
 */
const MAX_SUFFIX_WORK_CHARS = 32 * 1024 * 1024;
const SUFFIX_WORK_BUDGET_WARNING = "session-dedup: skipped (suffix work budget exceeded)";

type SuffixWorkBudget = { remaining: number };

// ─── hash helper (SHA-256 prefix, collision-resistant) ───────────────────────

function hashBlock(text: string): string {
  // 24 hex / 96 bits — collision-resistant (a 32-bit djb2 could collide and make a
  // dedup marker reference the WRONG block). Pass 2 additionally verifies block
  // equality before substituting, so a collision can never cause corruption.
  return crypto.createHash("sha256").update(text).digest("hex").slice(0, 24);
}

// ─── suffix-block extraction ──────────────────────────────────────────────────

/**
 * Reserves the characters that findSuffixBlocks() would materialize for one text.
 * The scan observes line starts without splitting or constructing any suffix strings.
 */
function reserveSuffixWork(text: string, passCount: number, budget: SuffixWorkBudget): boolean {
  let start = 0;
  while (start <= text.length) {
    const suffixChars = (text.length - start) * passCount;
    if (suffixChars > budget.remaining) return false;
    budget.remaining -= suffixChars;

    const nextNewline = text.indexOf("\n", start);
    if (nextNewline === -1) break;
    start = nextNewline + 1;
  }
  return true;
}

/**
 * For each starting line position, emit the suffix block `lines[start..end]`
 * (i.e. from `start` to the end of the line array). This ensures that any
 * multiline sub-content that appears verbatim in multiple messages is discoverable
 * regardless of what text precedes it in each message.
 *
 * Only emits blocks that meet minBlockChars AND have at least MIN_BLOCK_LINES lines.
 * Uses a seen-set to deduplicate identical suffix blocks.
 */
function findSuffixBlocks(
  lines: string[],
  minBlockChars: number
): Array<{ block: string; startLine: number }> {
  const n = lines.length;
  const seen = new Set<string>();
  const results: Array<{ block: string; startLine: number }> = [];

  for (let start = 0; start < n; start++) {
    const block = lines.slice(start).join("\n");
    const blockLines = n - start;
    if (blockLines >= MIN_BLOCK_LINES && block.length >= minBlockChars && !seen.has(block)) {
      seen.add(block);
      results.push({ block, startLine: start });
    }
  }
  return results;
}

// ─── two-pass dedup on message texts ─────────────────────────────────────────

/**
 * Deduplicates repeated lines within a single message (intra-message dedup).
 * Replaces repeated suffix blocks with markers.
 */
function dedupeWithinMessage(
  text: string,
  minBlockChars: number
): { deduped: string; changed: boolean } {
  const lines = text.split("\n");
  const blocks = findSuffixBlocks(lines, minBlockChars);

  if (blocks.length < 2) return { deduped: text, changed: false };

  // Find the most common block (likely candidate for intra-message dedup).
  const blockFreq = new Map<string, number>();
  for (const { block } of blocks) {
    blockFreq.set(block, (blockFreq.get(block) || 0) + 1);
  }

  // Sort by frequency descending, then by length descending (prefer replacing more common, longer blocks first).
  const sortedBlocks = [...blocks].sort((a, b) => {
    const freqDiff = (blockFreq.get(b.block) || 0) - (blockFreq.get(a.block) || 0);
    return freqDiff !== 0 ? freqDiff : b.block.length - a.block.length;
  });

  let result = text;
  let changed = false;

  for (const { block } of sortedBlocks) {
    // Only dedup blocks that appear 2+ times in the text.
    const occurrences = (
      result.match(new RegExp(block.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "g")) || []
    ).length;
    if (occurrences < 2) continue;

    const sha = hashBlock(block);
    const marker = `[dedup:ref sha=${sha}]`;
    // Replace ALL occurrences except the first (keep the original once).
    let count = 0;
    result = result.replace(new RegExp(block.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "g"), () => {
      count++;
      return count === 1 ? block : marker;
    });
    changed = true;
  }

  return { deduped: result, changed };
}

/**
 * Runs two-pass dedup over an ordered list of (msgIdx, text) pairs.
 * Returns the replaced texts for duplicate messages, a reverse map, and a count.
 */
function dedupMessageTexts(
  msgTexts: Array<{ msgIdx: number; text: string }>,
  minBlockChars: number
): {
  deduped: Map<number, string>;
  dedupCount: number;
} {
  const deduped = new Map<number, string>();
  let dedupCount = 0;

  // Single-message case: apply intra-message dedup.
  if (msgTexts.length === 1) {
    const { text, msgIdx } = msgTexts[0];
    const { deduped: dedupedText, changed } = dedupeWithinMessage(text, minBlockChars);
    if (changed) {
      deduped.set(msgIdx, dedupedText);
      dedupCount++;
    }
    return { deduped, dedupCount };
  }

  // Multi-message case: apply cross-turn dedup.
  // Pass 1: for each message, extract suffix blocks and record first ownership.
  // `firstSeen`: sha → { ownerMsgIdx, block }
  const firstSeen = new Map<string, { ownerMsgIdx: number; block: string }>();

  for (const { msgIdx, text } of msgTexts) {
    const lines = text.split("\n");
    const blocks = findSuffixBlocks(lines, minBlockChars);
    for (const { block } of blocks) {
      const sha = hashBlock(block);
      if (!firstSeen.has(sha)) {
        firstSeen.set(sha, { ownerMsgIdx: msgIdx, block });
      }
    }
  }

  // Pass 2: for each message, find blocks that were FIRST seen in an earlier message.
  for (const { msgIdx, text } of msgTexts) {
    const lines = text.split("\n");
    const blocks = findSuffixBlocks(lines, minBlockChars);

    // Collect blocks that are duplicates (owned by an earlier message).
    const dupBlocks: Array<{ block: string; sha: string }> = [];
    for (const { block } of blocks) {
      const sha = hashBlock(block);
      const owner = firstSeen.get(sha);
      // owner.block === block guards against a (now astronomically unlikely) hash
      // collision substituting a marker that would reference the wrong block.
      if (owner && owner.ownerMsgIdx < msgIdx && owner.block === block) {
        dupBlocks.push({ block, sha });
      }
    }

    if (dupBlocks.length === 0) continue;

    // Sort longest-first to prefer replacing the longest matching block.
    dupBlocks.sort((a, b) => b.block.length - a.block.length);

    let result = text;
    let changed = false;
    const replaced = new Set<string>(); // avoid double-replacing overlapping blocks

    for (const { block, sha } of dupBlocks) {
      // Skip if this block is a suffix of a block already replaced (overlap guard).
      if ([...replaced].some((r) => r.includes(block))) continue;

      const idx = result.indexOf(block);
      if (idx !== -1) {
        const marker = `[dedup:ref sha=${sha}]`;
        result = result.slice(0, idx) + marker + result.slice(idx + block.length);
        changed = true;
        replaced.add(block);
        // Only replace once per block per message pass.
        break;
      }
    }

    if (changed) {
      deduped.set(msgIdx, result);
      dedupCount++;
    }
  }

  return { deduped, dedupCount };
}

// ─── message array processing ─────────────────────────────────────────────────

type MessageLike = {
  role?: string;
  content?: string | Array<Record<string, unknown>>;
  [key: string]: unknown;
};

/**
 * Process messages: collect text content, run two-pass dedup, apply results.
 */
function processMessages(
  messages: MessageLike[],
  minBlockChars: number
): { messages: MessageLike[]; dedupCount: number; suffixWorkBudgetExceeded: boolean } {
  // Collect (msgIdx, text) for non-system string-content messages.
  // For multipart, index each text part separately.
  const msgTexts: Array<{ msgIdx: number; text: string }> = [];

  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i];
    if (msg.role === "system") continue;
    if (typeof msg.content === "string") {
      msgTexts.push({ msgIdx: i, text: msg.content });
    } else if (Array.isArray(msg.content)) {
      for (let p = 0; p < msg.content.length; p++) {
        const part = msg.content[p];
        if (part["type"] === "text" && typeof part["text"] === "string") {
          // Composite key: i * 100000 + p + 1 (safe for reasonable message counts)
          msgTexts.push({ msgIdx: i * 100000 + p + 1, text: part["text"] as string });
        }
      }
    }
  }

  if (msgTexts.length === 0) {
    return { messages, dedupCount: 0, suffixWorkBudgetExceeded: false };
  }

  // Single-message exact dedup enumerates suffixes once; cross-message dedup does so
  // in both passes. Reserve the request-wide work up front so no quadratic suffix graph
  // is partially materialized before the engine decides to fail open.
  const suffixWorkBudget: SuffixWorkBudget = { remaining: MAX_SUFFIX_WORK_CHARS };
  const passCount = msgTexts.length === 1 ? 1 : 2;
  for (const { text } of msgTexts) {
    if (!reserveSuffixWork(text, passCount, suffixWorkBudget)) {
      return { messages, dedupCount: 0, suffixWorkBudgetExceeded: true };
    }
  }

  const { deduped, dedupCount } = dedupMessageTexts(msgTexts, minBlockChars);

  if (dedupCount === 0) {
    return { messages, dedupCount: 0, suffixWorkBudgetExceeded: false };
  }

  const result = messages.map((msg, i) => {
    if (msg.role === "system") return { ...msg };

    if (typeof msg.content === "string") {
      const replacement = deduped.get(i);
      return replacement !== undefined ? { ...msg, content: replacement } : { ...msg };
    }

    if (Array.isArray(msg.content)) {
      let changed = false;
      const newContent = msg.content.map((part, p) => {
        if (part["type"] !== "text" || typeof part["text"] !== "string") return part;
        const key = i * 100000 + p + 1;
        const replacement = deduped.get(key);
        if (replacement !== undefined) {
          changed = true;
          return { ...part, text: replacement };
        }
        return part;
      });
      return changed ? { ...msg, content: newContent } : { ...msg };
    }

    return { ...msg };
  });

  return { messages: result, dedupCount, suffixWorkBudgetExceeded: false };
}

// ─── schema & validation ──────────────────────────────────────────────────────

const SESSION_DEDUP_SCHEMA: EngineConfigField[] = [
  {
    key: "enabled",
    type: "boolean",
    label: "Enabled",
    defaultValue: true,
  },
  {
    key: "minBlockChars",
    type: "number",
    label: "Minimum block characters",
    description: "Minimum character count for a suffix block to be a dedup candidate.",
    defaultValue: DEFAULT_MIN_BLOCK_CHARS,
    min: 1,
    max: 100000,
  },
  {
    key: "fuzzy",
    type: "boolean",
    label: "Fuzzy near-duplicate dedup",
    description:
      "Opt-in: replace whole messages ~85%+ similar to an earlier one with a recoverable CCR marker.",
    defaultValue: false,
  },
];

function validateSessionDedupConfig(config: Record<string, unknown>): EngineValidationResult {
  const errors: string[] = [];
  if (config["enabled"] !== undefined && typeof config["enabled"] !== "boolean") {
    errors.push("enabled must be a boolean");
  }
  if (config["minBlockChars"] !== undefined) {
    const v = config["minBlockChars"];
    if (typeof v !== "number" || !Number.isFinite(v) || v < 1) {
      errors.push("minBlockChars must be a positive number");
    }
  }
  if (config["fuzzy"] !== undefined) {
    const f = config["fuzzy"];
    if (typeof f === "object" && f !== null) {
      const fe = (f as Record<string, unknown>)["enabled"];
      if (fe !== undefined && typeof fe !== "boolean")
        errors.push("fuzzy.enabled must be a boolean");
    } else if (typeof f !== "boolean") {
      errors.push("fuzzy must be an object { enabled } or a boolean");
    }
  }
  return { valid: errors.length === 0, errors };
}

// ─── engine export ────────────────────────────────────────────────────────────

export const sessionDedupEngine: CompressionEngine = {
  id: ENGINE_ID,
  name: "Session Dedup",
  description:
    "Content-addressed cross-turn deduplication: replaces repeated multi-line blocks " +
    "with short reference markers (R11/N2/TO1, TokenMizer blueprint).",
  icon: "content_copy",
  targets: ["messages"],
  stackable: true,
  // stackPriority 3 = runs BEFORE lite (5), caveman (20), aggressive (30), ultra (40).
  // Dedup first so downstream engines operate on already-deduplicated content.
  stackPriority: 3,
  metadata: {
    id: ENGINE_ID,
    name: "Session Dedup",
    description:
      "Content-addressed cross-turn deduplication: replaces repeated multi-line blocks with short reference markers.",
    inputScope: "messages",
    targetLatencyMs: 1,
    supportsPreview: true,
    stable: true,
  },

  apply(body: Record<string, unknown>, options?: CompressionEngineApplyOptions): CompressionResult {
    const stepConfig = options?.stepConfig ?? {};

    if (stepConfig["enabled"] === false) {
      return { body, compressed: false, stats: null };
    }

    const minBlockChars =
      typeof stepConfig["minBlockChars"] === "number"
        ? (stepConfig["minBlockChars"] as number)
        : DEFAULT_MIN_BLOCK_CHARS;

    const messages = body["messages"];
    if (!Array.isArray(messages) || messages.length === 0) {
      return { body, compressed: false, stats: null };
    }

    const start = performance.now();
    const {
      messages: exactMessages,
      dedupCount,
      suffixWorkBudgetExceeded,
    } = processMessages(messages as MessageLike[], minBlockChars);

    if (suffixWorkBudgetExceeded) {
      const durationMs = Math.round(performance.now() - start);
      const stats = createCompressionStats(body, body, "stacked", [], undefined, durationMs);
      stats.validationWarnings = [SUFFIX_WORK_BUDGET_WARNING];
      return { body, compressed: false, stats };
    }

    const { messages: finalMessages, fuzzyCount } = runFuzzyPass(
      exactMessages,
      stepConfig,
      minBlockChars,
      options?.principalId
    );

    if (dedupCount + fuzzyCount === 0) {
      return { body, compressed: false, stats: null };
    }

    const newBody: Record<string, unknown> = { ...body, messages: finalMessages };
    const durationMs = Math.round(performance.now() - start);
    const techniques = ["session-dedup"];
    if (fuzzyCount > 0) techniques.push("fuzzy-dedup");
    const rules: string[] = [];
    if (dedupCount > 0) rules.push(`deduplicated-${dedupCount}-blocks`);
    if (fuzzyCount > 0) rules.push(`fuzzy-${fuzzyCount}-blocks`);
    const stats = createCompressionStats(body, newBody, "stacked", techniques, rules, durationMs);
    return { body: newBody, compressed: true, stats };
  },

  compress(body: Record<string, unknown>, config?: Record<string, unknown>): CompressionResult {
    return this.apply(body, { stepConfig: config ?? {} });
  },

  getConfigSchema(): EngineConfigField[] {
    return SESSION_DEDUP_SCHEMA;
  },

  validateConfig(config: Record<string, unknown>): EngineValidationResult {
    return validateSessionDedupConfig(config);
  },
};

// open-sse/services/compression/engines/session-dedup/fuzzy.ts
import { buildCcrMarker, tryStoreBlock } from "../ccr/index.ts";

type MessageLike = { role?: string; content?: unknown; [key: string]: unknown };

/** Hard cap on blocks compared in the fuzzy O(n²) pass (fail-safe bound). */
export const MAX_FUZZY_BLOCKS = 200;

/** FNV-1a 32-bit hash (deterministic, cheap, no Math.random). */
function fnv1a(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** Set of k-word shingle hashes (default k=3). Empty when the text has < k words. */
export function shingles(text: string, k = 3): Set<number> {
  const words = text.split(/\s+/).filter(Boolean);
  const out = new Set<number>();
  if (words.length < k) return out;
  for (let i = 0; i + k <= words.length; i++) {
    out.add(fnv1a(words.slice(i, i + k).join(" ")));
  }
  return out;
}

/** Jaccard similarity |a∩b| / |a∪b| (0..1; 0 when both empty). */
export function jaccard(a: Set<number>, b: Set<number>): number {
  if (a.size === 0 && b.size === 0) return 0;
  const [small, large] = a.size <= b.size ? [a, b] : [b, a];
  let inter = 0;
  for (const x of small) if (large.has(x)) inter++;
  const union = a.size + b.size - inter;
  return union === 0 ? 0 : inter / union;
}

export interface FuzzyBlock {
  text: string;
  index: number;
}
export interface NearDuplicate {
  block: FuzzyBlock;
  matchedIndex: number;
  similarity: number;
}

/**
 * For each block, find the EARLIER block with the highest Jaccard ≥ minJaccard.
 * O(n²); returns [] when blocks.length > maxBlocks (fail-safe bound, no blowup).
 */
export function findNearDuplicates(
  blocks: FuzzyBlock[],
  minJaccard: number,
  maxBlocks: number,
  shingleSize = 3
): NearDuplicate[] {
  if (blocks.length > maxBlocks) return [];
  const sets = blocks.map((b) => shingles(b.text, shingleSize));
  const out: NearDuplicate[] = [];
  for (let i = 0; i < blocks.length; i++) {
    let best = -1;
    let bestSim = 0;
    for (let j = 0; j < i; j++) {
      const sim = jaccard(sets[i], sets[j]);
      if (sim >= minJaccard && sim > bestSim) {
        bestSim = sim;
        best = j;
      }
    }
    if (best >= 0) {
      out.push({ block: blocks[i], matchedIndex: blocks[best].index, similarity: bestSim });
    }
  }
  return out;
}

export interface FuzzyPassOptions {
  minJaccard: number;
  shingleSize: number;
  maxBlocks: number;
  minBlockChars: number;
  principalId?: string;
}
export interface FuzzyPassResult {
  messages: MessageLike[];
  fuzzyCount: number;
}

/**
 * Near-duplicate second pass over WHOLE string-content messages. A later message ≥minJaccard
 * similar to an earlier one is stored in the CCR store and replaced inline with a recoverable
 * `[CCR retrieve …]` marker (only when the marker shrinks). FAIL-OPEN: any error → no-op.
 */
export function applyFuzzyPass(messages: MessageLike[], opts: FuzzyPassOptions): FuzzyPassResult {
  try {
    const blocks: FuzzyBlock[] = [];
    for (let i = 0; i < messages.length; i++) {
      const m = messages[i];
      if (m.role === "system") continue;
      if (typeof m.content === "string" && m.content.length >= opts.minBlockChars) {
        blocks.push({ text: m.content, index: i });
      }
    }
    if (blocks.length < 2) return { messages, fuzzyCount: 0 };

    const nearDups = findNearDuplicates(blocks, opts.minJaccard, opts.maxBlocks, opts.shingleSize);
    if (nearDups.length === 0) return { messages, fuzzyCount: 0 };

    const replacements = new Map<number, string>();
    for (const nd of nearDups) {
      const stored = tryStoreBlock(nd.block.text, opts.principalId, { source: "session-dedup" });
      if (!stored.stored) continue;
      const marker = buildCcrMarker(stored.hash, nd.block.text.length);
      if (marker.length < nd.block.text.length) replacements.set(nd.block.index, marker);
    }
    if (replacements.size === 0) return { messages, fuzzyCount: 0 };

    const out = messages.map((m, i) =>
      replacements.has(i) ? { ...m, content: replacements.get(i) } : m
    );
    return { messages: out, fuzzyCount: replacements.size };
  } catch {
    return { messages, fuzzyCount: 0 };
  }
}

/**
 * Resolve the `fuzzy` step-config (a bare boolean OR `{ enabled, minJaccard?, shingleSize? }`)
 * and run the near-duplicate pass. Returns the messages unchanged + `fuzzyCount: 0` when disabled.
 * Keeps the engine's `apply()` thin (config normalization + dispatch live here).
 */
export function runFuzzyPass(
  messages: MessageLike[],
  stepConfig: Record<string, unknown>,
  minBlockChars: number,
  principalId?: string
): FuzzyPassResult {
  const raw = stepConfig["fuzzy"] as
    boolean | { enabled?: boolean; minJaccard?: number; shingleSize?: number } | undefined;
  const cfg = typeof raw === "boolean" ? { enabled: raw } : raw;
  if (!cfg?.enabled) return { messages, fuzzyCount: 0 };
  return applyFuzzyPass(messages, {
    minJaccard: typeof cfg.minJaccard === "number" ? cfg.minJaccard : 0.85,
    shingleSize: typeof cfg.shingleSize === "number" ? cfg.shingleSize : 3,
    maxBlocks: MAX_FUZZY_BLOCKS,
    minBlockChars,
    principalId,
  });
}

/**
 * CCR (Content-Compression-Retrieve) engine (H4)
 *
 * Replaces large contiguous blocks of text with a content-addressed
 * retrieve marker: `[CCR retrieve hash=<24hex> chars=<N>]`
 *
 * The verbatim block is stored in a principal-scoped, bounded in-module store.
 * The store key is `${principalId ?? "__anon__"} ${contentHash}` so that one
 * principal cannot read another's stored blocks (IDOR protection).
 *
 * The `retrieve` MCP tool (or the `handleCcrRetrieve` helper exported here)
 * returns the block on demand when called with the matching callerId.
 *
 * Algorithm:
 *   - Scan non-system messages; for each `type:"text"` part or string content,
 *     find contiguous text blocks ≥ minChars characters.
 *   - Replace the block with `[CCR retrieve hash=<24hex> chars=<N>]` only if
 *     the marker is shorter than the original block.
 *   - Store the original block keyed by (principalId, hash) in the CCR store.
 *
 * Feedback (scoped by principal):
 *   - `recordRetrieval(hash, principalId)` increments a retrieval counter for
 *     that (principalId, hash) pair.
 *   - `shouldSkipCompression(hash, principalId)` returns true once the counter
 *     reaches RETRIEVAL_THRESHOLD for that principal — one principal's behaviour
 *     does not affect another's (cross-tenant state drift protection).
 *
 * Memory bound:
 *   - Entries are capped by count, global bytes, per-principal bytes, block bytes and TTL.
 *   - Expired and least-recently-used entries are removed before a store is rejected.
 *
 * Conservative guards:
 *   - Never touch `role: "system"`.
 *   - Only replace if it shrinks (marker shorter than original).
 *   - Only replace blocks ≥ minChars (default 600).
 *   - `stackable: true`, `stackPriority: 4` (runs just after session-dedup(3)).
 */

import crypto from "node:crypto";
import { createCompressionStats } from "../../stats.ts";
import { queryBlock, type CcrQuery } from "./ccrQuery.ts";
import { injectCcrProtocolInstruction } from "./protocolInstruction.ts";
import type {
  CompressionEngine,
  CompressionEngineApplyOptions,
  EngineConfigField,
  EngineValidationResult,
} from "../types.ts";
import type { CompressionResult } from "../../types.ts";

// ─── constants ────────────────────────────────────────────────────────────────

const ENGINE_ID = "ccr";
/** Default minimum character count for a block to be a CCR candidate. */
const DEFAULT_MIN_CHARS = 600;
/** Number of retrievals before a block is flagged "do-not-compress" for that principal. */
const RETRIEVAL_THRESHOLD = 3;
/**
 * H8 — default retrieval ramp factor. Each prior retrieval (below the threshold) raises a block's
 * effective `minChars` linearly, so hot content is compressed progressively less; `1` disables the
 * ramp (only the >= threshold cliff remains — the legacy binary behavior).
 */
const RETRIEVAL_RAMP_FACTOR_DEFAULT = 2;
/** Maximum number of entries in the principal-scoped, LRU-ordered store. */
export const MAX_CCR_ENTRIES = 5_000;
export const MAX_CCR_BLOCK_BYTES = 2 * 1024 * 1024;
export const MAX_CCR_PRINCIPAL_BYTES = 16 * 1024 * 1024;
export const MAX_CCR_GLOBAL_BYTES = 64 * 1024 * 1024;
export const DEFAULT_CCR_TTL_SECONDS = 24 * 60 * 60;
export const MAX_CCR_TTL_SECONDS = 7 * 24 * 60 * 60;
export const MAX_CCR_MCP_FULL_BYTES = 256 * 1024;

export type CcrEntrySource = "compression" | "mcp" | "ionizer" | "session-dedup";

export interface CcrEntryMetadata {
  hash: string;
  bytes: number;
  chars: number;
  lines: number;
  contentType: string;
  source: CcrEntrySource;
  createdAt: number;
  lastAccessedAt: number;
  expiresAt: number;
  retrievalCount: number;
}

type CcrEntry = Omit<CcrEntryMetadata, "retrievalCount"> & {
  principalId: string;
  content: string;
};

export interface StoreCcrBlockOptions {
  contentType?: string;
  source?: CcrEntrySource;
  ttlSeconds?: number;
  now?: number;
}

export type StoreCcrBlockResult =
  | { stored: true; hash: string; metadata: CcrEntryMetadata }
  | {
      stored: false;
      hash: string;
      reason: "block_too_large" | "principal_budget_exceeded" | "global_budget_exceeded";
    };

export interface CcrStoreStats {
  storage: "memory";
  entries: number;
  bytes: number;
  limits: {
    maxEntries: number;
    maxBlockBytes: number;
    maxPrincipalBytes: number;
    maxGlobalBytes: number;
    defaultTtlSeconds: number;
    maxTtlSeconds: number;
    maxMcpFullBytes: number;
  };
  lifecycle: {
    expiredEvictions: number;
    capacityEvictions: number;
    rejectedStores: number;
  };
}

// ─── principal-scoped, bounded content store ──────────────────────────────────

/**
 * Store key = `${principalId ?? "__anon__"} ${contentHash}`.
 * Using a compound key scopes data to the principal that stored it.
 */
const ccrStore = new Map<string, CcrEntry>();
const retrievalCounts = new Map<string, number>();
const principalBytesMap = new Map<string, number>();
let ccrTotalBytes = 0;
type CcrLifecycleCounters = CcrStoreStats["lifecycle"];
const lifecycleByPrincipal = new Map<string, CcrLifecycleCounters>();

/** Sentinel used when no principalId is provided. */
const ANON = "__anon__";

function buildStoreKey(hash: string, principalId?: string): string {
  return `${principalId ?? ANON} ${hash}`;
}

function readLifecycleCounters(principalId: string): CcrLifecycleCounters {
  return (
    lifecycleByPrincipal.get(principalId) ?? {
      expiredEvictions: 0,
      capacityEvictions: 0,
      rejectedStores: 0,
    }
  );
}

function mutableLifecycleCounters(principalId: string): CcrLifecycleCounters {
  const existing = lifecycleByPrincipal.get(principalId);
  if (existing) return existing;
  const counters = { expiredEvictions: 0, capacityEvictions: 0, rejectedStores: 0 };
  lifecycleByPrincipal.set(principalId, counters);
  return counters;
}

function publicMetadata(entry: CcrEntry): CcrEntryMetadata {
  const { principalId: _principalId, content: _content, ...metadata } = entry;
  return {
    ...metadata,
    retrievalCount: retrievalCounts.get(buildStoreKey(entry.hash, entry.principalId)) ?? 0,
  };
}

function setRetrievalCount(key: string, count: number): void {
  if (!retrievalCounts.has(key) && retrievalCounts.size >= MAX_CCR_ENTRIES) {
    const oldestKey = retrievalCounts.keys().next().value;
    if (oldestKey !== undefined) retrievalCounts.delete(oldestKey);
  }
  retrievalCounts.delete(key);
  retrievalCounts.set(key, count);
}

function removeEntry(key: string, reason?: "expired" | "capacity"): boolean {
  const entry = ccrStore.get(key);
  if (!entry) return false;
  ccrStore.delete(key);
  ccrTotalBytes = Math.max(0, ccrTotalBytes - entry.bytes);
  const remainingPrincipalBytes = Math.max(
    0,
    (principalBytesMap.get(entry.principalId) ?? 0) - entry.bytes
  );
  if (remainingPrincipalBytes === 0) principalBytesMap.delete(entry.principalId);
  else principalBytesMap.set(entry.principalId, remainingPrincipalBytes);
  const counters = mutableLifecycleCounters(entry.principalId);
  if (reason === "expired") counters.expiredEvictions++;
  if (reason === "capacity") counters.capacityEvictions++;
  return true;
}

function purgeExpired(now = Date.now()): void {
  for (const [key, entry] of ccrStore) {
    if (entry.expiresAt <= now) removeEntry(key, "expired");
  }
}

function getActiveEntry(key: string, now = Date.now()): CcrEntry | null {
  const entry = ccrStore.get(key);
  if (!entry) return null;
  if (entry.expiresAt <= now) {
    removeEntry(key, "expired");
    return null;
  }
  return entry;
}

function principalBytes(principalId: string): number {
  return principalBytesMap.get(principalId) ?? 0;
}

function evictOldestMatching(predicate: (entry: CcrEntry) => boolean): boolean {
  for (const [key, entry] of ccrStore) {
    if (predicate(entry)) return removeEntry(key, "capacity");
  }
  return false;
}

function normalizeTtlSeconds(value: number | undefined): number {
  if (!Number.isFinite(value) || value === undefined) return DEFAULT_CCR_TTL_SECONDS;
  return Math.max(60, Math.min(MAX_CCR_TTL_SECONDS, Math.floor(value)));
}

/**
 * Compute a 24-hex content hash for a text block (SHA-256 prefix).
 * This is the hash embedded in the marker; principal scoping is internal to
 * the store key and is NOT part of the marker itself.
 */
function hashContent(text: string): string {
  return crypto.createHash("sha256").update(text).digest("hex").slice(0, 24);
}

function rejectStore(
  hash: string,
  owner: string,
  reason: Exclude<StoreCcrBlockResult, { stored: true }>["reason"]
): StoreCcrBlockResult {
  mutableLifecycleCounters(owner).rejectedStores++;
  return { stored: false, hash, reason };
}

function enforcePrincipalBudget(owner: string, bytes: number): boolean {
  while (
    principalBytes(owner) + bytes > MAX_CCR_PRINCIPAL_BYTES &&
    evictOldestMatching((entry) => entry.principalId === owner)
  ) {
    // Evict the owner's least-recently-used entries until this block fits.
  }
  return principalBytes(owner) + bytes <= MAX_CCR_PRINCIPAL_BYTES;
}

function enforceGlobalBudget(bytes: number): boolean {
  while (
    (ccrStore.size >= MAX_CCR_ENTRIES || ccrTotalBytes + bytes > MAX_CCR_GLOBAL_BYTES) &&
    evictOldestMatching(() => true)
  ) {
    // Enforce both entry and global byte caps with LRU eviction.
  }
  return ccrTotalBytes + bytes <= MAX_CCR_GLOBAL_BYTES;
}

/**
 * Store a block in the CCR store under the given principal.
 * Returns the 24-hex content hash (for embedding in the marker).
 */
export function tryStoreBlock(
  text: string,
  principalId?: string,
  options: StoreCcrBlockOptions = {}
): StoreCcrBlockResult {
  const hash = hashContent(text);
  const owner = principalId ?? ANON;
  const key = buildStoreKey(hash, principalId);
  const now = options.now ?? Date.now();
  purgeExpired(now);

  const existing = ccrStore.get(key);
  if (existing) {
    existing.lastAccessedAt = now;
    existing.expiresAt = now + normalizeTtlSeconds(options.ttlSeconds) * 1000;
    ccrStore.delete(key);
    ccrStore.set(key, existing);
    return { stored: true, hash, metadata: publicMetadata(existing) };
  }

  const bytes = Buffer.byteLength(text, "utf8");
  if (bytes > MAX_CCR_BLOCK_BYTES) {
    return rejectStore(hash, owner, "block_too_large");
  }

  if (!enforcePrincipalBudget(owner, bytes)) {
    return rejectStore(hash, owner, "principal_budget_exceeded");
  }

  if (!enforceGlobalBudget(bytes)) {
    return rejectStore(hash, owner, "global_budget_exceeded");
  }

  const ttlSeconds = normalizeTtlSeconds(options.ttlSeconds);
  const entry: CcrEntry = {
    hash,
    principalId: owner,
    content: text,
    bytes,
    chars: text.length,
    lines: text.length === 0 ? 0 : text.split("\n").length,
    contentType: options.contentType?.trim().slice(0, 128) || "text/plain",
    source: options.source ?? "compression",
    createdAt: now,
    lastAccessedAt: now,
    expiresAt: now + ttlSeconds * 1000,
  };
  ccrStore.set(key, entry);
  ccrTotalBytes += bytes;
  principalBytesMap.set(owner, principalBytes(owner) + bytes);
  return { stored: true, hash, metadata: publicMetadata(entry) };
}

export function storeBlock(
  text: string,
  principalId?: string,
  options: StoreCcrBlockOptions = {}
): string {
  const result = tryStoreBlock(text, principalId, options);
  if (!result.stored) throw new RangeError(`CCR store rejected block: ${result.reason}`);
  return result.hash;
}

/**
 * Retrieve the verbatim block for a given hash and principal.
 * Returns null if not found or if the principal does not match the stored key.
 */
export function retrieveBlock(hash: string, principalId?: string, now = Date.now()): string | null {
  const key = buildStoreKey(hash, principalId);
  const entry = getActiveEntry(key, now);
  if (!entry) return null;
  entry.lastAccessedAt = now;
  ccrStore.delete(key);
  ccrStore.set(key, entry);
  return entry.content;
}

/**
 * Record a retrieval event for a given (hash, principal) pair (feedback signal).
 */
export function recordRetrieval(hash: string, principalId?: string): void {
  const key = buildStoreKey(hash, principalId);
  setRetrievalCount(key, (retrievalCounts.get(key) ?? 0) + 1);
}

/**
 * Returns true if the block has been retrieved often enough by this principal
 * that it should be excluded from compression in future requests.
 * Each principal's feedback is isolated from other principals.
 */
export function shouldSkipCompression(hash: string, principalId?: string): boolean {
  const key = buildStoreKey(hash, principalId);
  return (retrievalCounts.get(key) ?? 0) >= RETRIEVAL_THRESHOLD;
}

/**
 * H8 — retrieval-aware minimum block size (graduated feedback). A frequently-retrieved
 * `(principal, hash)` block is compressed progressively less: each prior retrieval (below the
 * threshold) raises the size bar linearly, and once the retrieval count reaches
 * `RETRIEVAL_THRESHOLD` the block is never compressed (`Infinity` — this subsumes the previous
 * binary `shouldSkipCompression` cliff). Pure function of the retrieval counter; `rampFactor <= 1`
 * disables the ramp so only the `>= threshold` cliff remains (byte-identical to the legacy path).
 */
export function effectiveMinChars(
  baseMinChars: number,
  hash: string,
  principalId: string | undefined,
  rampFactor: number
): number {
  const count = retrievalCounts.get(buildStoreKey(hash, principalId)) ?? 0;
  if (count >= RETRIEVAL_THRESHOLD) return Number.POSITIVE_INFINITY;
  if (count <= 0 || rampFactor <= 1) return baseMinChars;
  // Linear ramp: count=1 → base·rampFactor; count=2 → base·(1 + 2·(rampFactor−1)); …
  return Math.round(baseMinChars * (1 + (rampFactor - 1) * count));
}

/** Resolve the H8 ramp factor from the env (`COMPRESSION_CCR_RETRIEVAL_RAMP_FACTOR`), default 2. */
export function resolveRetrievalRampFactor(env: NodeJS.ProcessEnv = process.env): number {
  const raw = env.COMPRESSION_CCR_RETRIEVAL_RAMP_FACTOR;
  if (raw === undefined) return RETRIEVAL_RAMP_FACTOR_DEFAULT;
  const n = Number(raw);
  return Number.isFinite(n) && n >= 1 ? n : RETRIEVAL_RAMP_FACTOR_DEFAULT;
}

/**
 * Reset the CCR store and retrieval counts (for testing).
 */
export function resetCcrStore(): void {
  ccrStore.clear();
  retrievalCounts.clear();
  principalBytesMap.clear();
  ccrTotalBytes = 0;
  lifecycleByPrincipal.clear();
}

export function inspectCcrBlock(
  hash: string,
  principalId?: string,
  now = Date.now()
): CcrEntryMetadata | null {
  const entry = getActiveEntry(buildStoreKey(hash, principalId), now);
  return entry ? publicMetadata(entry) : null;
}

export function listCcrBlocks(
  principalId?: string,
  options: { offset?: number; limit?: number; now?: number } = {}
): { entries: CcrEntryMetadata[]; total: number; offset: number; limit: number; hasMore: boolean } {
  purgeExpired(options.now);
  const owner = principalId ?? ANON;
  const offset = Math.max(0, Math.floor(options.offset ?? 0));
  const limit = Math.max(1, Math.min(100, Math.floor(options.limit ?? 25)));
  const all: CcrEntryMetadata[] = [];
  for (const entry of ccrStore.values()) {
    if (entry.principalId === owner) all.push(publicMetadata(entry));
  }
  all.reverse();
  return {
    entries: all.slice(offset, offset + limit),
    total: all.length,
    offset,
    limit,
    hasMore: offset + limit < all.length,
  };
}

export function deleteCcrBlock(hash: string, principalId?: string, _now = Date.now()): boolean {
  return removeEntry(buildStoreKey(hash, principalId));
}

export function getCcrStoreStats(principalId?: string, now = Date.now()): CcrStoreStats {
  purgeExpired(now);
  const owner = principalId ?? ANON;
  const entries = Array.from(ccrStore.values()).filter((entry) => entry.principalId === owner);
  return {
    storage: "memory",
    entries: entries.length,
    bytes: entries.reduce((sum, entry) => sum + entry.bytes, 0),
    limits: {
      maxEntries: MAX_CCR_ENTRIES,
      maxBlockBytes: MAX_CCR_BLOCK_BYTES,
      maxPrincipalBytes: MAX_CCR_PRINCIPAL_BYTES,
      maxGlobalBytes: MAX_CCR_GLOBAL_BYTES,
      defaultTtlSeconds: DEFAULT_CCR_TTL_SECONDS,
      maxTtlSeconds: MAX_CCR_TTL_SECONDS,
      maxMcpFullBytes: MAX_CCR_MCP_FULL_BYTES,
    },
    lifecycle: { ...readLifecycleCounters(owner) },
  };
}

// ─── MCP tool handler (pure function) ────────────────────────────────────────

/**
 * Handler for the `omniroute_ccr_retrieve` MCP tool.
 *
 * The `callerId` parameter must be the authenticated principal id derived from
 * the MCP `extra` context (see compressionTools.ts). Only the principal that
 * stored the block can retrieve it.
 *
 * Returns the verbatim block for the given hash, or an error object.
 */
export function handleCcrRetrieve(
  args: { hash: string } & CcrQuery,
  callerId?: string
): { content: string } | { error: string } {
  if (!args.hash || typeof args.hash !== "string") {
    return { error: "hash parameter is required and must be a string" };
  }

  const block = retrieveBlock(args.hash, callerId);
  if (block === null) {
    return {
      error: `CCR block not found for hash=${args.hash}. The block may have expired or the hash is invalid.`,
    };
  }

  recordRetrieval(args.hash, callerId);
  if (!args.mode || args.mode === "full") return { content: block };
  return queryBlock(block, args);
}

// ─── message content processing ──────────────────────────────────────────────

type MessageLike = {
  role?: string;
  content?: string | Array<Record<string, unknown>>;
  [key: string]: unknown;
};

/**
 * Build a CCR marker string for a block.
 */
export function buildCcrMarker(hash: string, charCount: number): string {
  return `[CCR retrieve hash=${hash} chars=${charCount}]`;
}

export function buildCcrReference(
  hash: string,
  charCount: number
): {
  hash: string;
  uri: string;
  marker: string;
} {
  return { hash, uri: `ccr://${hash}`, marker: buildCcrMarker(hash, charCount) };
}

/**
 * #7746 guard: how many leading characters of the original block to keep in front
 * of the marker. `maybeCcrReplace` treats an entire message/part as ONE candidate
 * block (see module docstring), so a bare marker alone would silently discard the
 * ENTIRE prompt for any caller that cannot resolve `omniroute_ccr_retrieve`
 * (every plain OpenAI-compatible client — it is only ever exposed as an MCP tool).
 * Keeping a short, human-readable preamble means the model still sees the start
 * of the user's intent even when the marker itself is unreachable, while the full
 * text remains verbatim-retrievable by hash for MCP-capable callers.
 */
const MARKER_PREAMBLE_CHARS = 200;

/**
 * Build the text that replaces a compressed block: a short preamble of the
 * original content followed by the retrieve marker, never the marker alone.
 */
function buildCcrReplacementText(text: string, marker: string): string {
  const preamble = text.slice(0, MARKER_PREAMBLE_CHARS).trimEnd();
  return `${preamble}… ${marker}`;
}

/**
 * Replace a large text block with a CCR marker if it shrinks the content.
 * Returns the new text and a flag indicating whether replacement happened.
 */
function maybeCcrReplace(
  text: string,
  minChars: number,
  principalId: string | undefined,
  rampFactor: number
): { text: string; replaced: boolean; hash: string | null } {
  // Base floor first (no hash cost for tiny blocks that could never compress anyway).
  if (text.length < minChars) {
    return { text, replaced: false, hash: null };
  }

  const hash = hashContent(text);

  // H8: retrieved blocks demand an ever-larger size before compressing; at/above the retrieval
  // threshold the effective minimum is Infinity, so the block is excluded (subsumes the former
  // binary shouldSkipCompression cliff).
  if (text.length < effectiveMinChars(minChars, hash, principalId, rampFactor)) {
    return { text, replaced: false, hash: null };
  }

  const marker = buildCcrMarker(hash, text.length);
  // #7746: never leave a caller with ONLY the bare marker — keep a short preamble
  // so the original prompt is not silently, totally unreachable for non-MCP callers.
  const replacement = buildCcrReplacementText(text, marker);

  // Only replace if it actually shrinks
  if (replacement.length >= text.length) {
    return { text, replaced: false, hash: null };
  }

  const stored = tryStoreBlock(text, principalId, { source: "compression" });
  if (!stored.stored) return { text, replaced: false, hash: null };
  return { text: replacement, replaced: true, hash };
}

/**
 * Process all non-system messages: find large text blocks and replace with CCR markers.
 */
function processMessages(
  messages: MessageLike[],
  minChars: number,
  principalId: string | undefined,
  rampFactor: number
): { messages: MessageLike[]; replacedCount: number } {
  let replacedCount = 0;

  const result = messages.map((msg) => {
    if (msg.role === "system") return { ...msg };

    // H-fix1: skip tool outputs (OpenAI `role:"tool"` and Anthropic user
    // messages whose content is exclusively `tool_result` parts). When
    // OmniRoute is used as a chat-completion PROVIDER, the upstream LLM has no
    // way to call `omniroute_ccr_retrieve` and expand markers — replacing tool
    // outputs with `[CCR retrieve hash=…]` placeholders therefore breaks the agent
    // loop. Preserve tool outputs verbatim so the LLM can keep reasoning.
    if (msg.role === "tool") return { ...msg };
    if (msg.role === "user" && Array.isArray(msg.content)) {
      const parts = msg.content as Array<Record<string, unknown>>;
      if (parts.length > 0 && parts.every((p) => p?.["type"] === "tool_result")) {
        return { ...msg };
      }
    }

    if (typeof msg.content === "string") {
      const { text, replaced } = maybeCcrReplace(msg.content, minChars, principalId, rampFactor);
      if (replaced) {
        replacedCount++;
        return { ...msg, content: text };
      }
      return { ...msg };
    }

    if (Array.isArray(msg.content)) {
      let changed = false;
      const newContent = msg.content.map((part) => {
        if (part?.["type"] !== "text" || typeof part?.["text"] !== "string") return part;
        const { text, replaced } = maybeCcrReplace(
          part["text"] as string,
          minChars,
          principalId,
          rampFactor
        );
        if (replaced) {
          changed = true;
          replacedCount++;
          return { ...part, text };
        }
        return part;
      });
      if (changed) {
        return { ...msg, content: newContent };
      }
      return { ...msg };
    }

    return { ...msg };
  });

  return { messages: result, replacedCount };
}

