export function validateRelevanceConfig(config: Record<string, unknown>): EngineValidationResult {
  const errors: string[] = [];
  if (config.enabled !== undefined && typeof config.enabled !== "boolean") {
    errors.push("enabled must be a boolean");
  }
  for (const key of ["overlapThreshold", "budgetPercent", "boilerplateWeight"]) {
    if (config[key] !== undefined) {
      const v = config[key];
      if (typeof v !== "number" || v < 0 || v > 1) {
        errors.push(`${key} must be a number between 0 and 1`);
      }
    }
  }
  return { valid: errors.length === 0, errors };
}

export function resolveRelevanceConfig(stepConfig: Record<string, unknown>): RelevanceConfig {
  return {
    enabled: typeof stepConfig.enabled === "boolean" ? stepConfig.enabled : false,
    overlapThreshold: typeof stepConfig.overlapThreshold === "number" ? stepConfig.overlapThreshold : 0.1,
    budgetPercent: typeof stepConfig.budgetPercent === "number" ? stepConfig.budgetPercent : 0.5,
    boilerplateWeight: typeof stepConfig.boilerplateWeight === "number" ? stepConfig.boilerplateWeight : 0.5,
  };
}

import type { RelevanceConfig } from "../../types.ts";

const BOILERPLATE_TOKENS = new Set([
  "please",
  "note",
  "important",
  "indeed",
  "certainly",
  "basically",
  "essentially",
  "obviously",
  "clearly",
  "simply",
  "just",
  "really",
  "actually",
  "honestly",
  "conclusion",
  "summary",
  "hope",
  "understand",
  "thing",
  "things",
  "something",
]);

function tokenize(text: string): string[] {
  const lower = text.toLowerCase();
  const tokens: string[] = [];
  let start = -1;
  for (let i = 0; i <= lower.length; i++) {
    const ch = i < lower.length ? lower.charCodeAt(i) : -1;
    const isAlnum =
      ch !== -1 &&
      ((ch >= 97 && ch <= 122) || (ch >= 48 && ch <= 57));
    if (isAlnum) {
      if (start === -1) start = i;
    } else {
      if (start !== -1) {
        tokens.push(lower.slice(start, i));
        start = -1;
      }
    }
  }
  return tokens;
}

function jaccard(setA: Set<string>, setB: Set<string>): number {
  if (setA.size === 0 || setB.size === 0) return 0;
  let intersection = 0;
  for (const t of setA) {
    if (setB.has(t)) intersection++;
  }
  const union = setA.size + setB.size - intersection;
  return union === 0 ? 0 : intersection / union;
}

function boilerplateScore(tokens: string[]): number {
  if (tokens.length === 0) return 0;
  let count = 0;
  for (const t of tokens) {
    if (BOILERPLATE_TOKENS.has(t)) count++;
  }
  return count / tokens.length;
}

export function scoreSentences(
  sentences: string[],
  query: string,
  cfg: RelevanceConfig
): number[] {
  if (sentences.length === 0) return [];
  if (!query || query.trim().length === 0) return sentences.map(() => 0);

  const queryTokens = new Set(tokenize(query));

  return sentences.map((sentence) => {
    const sentTokens = tokenize(sentence);
    if (sentTokens.length === 0) return 0;
    const sentSet = new Set(sentTokens);
    const overlap = jaccard(sentSet, queryTokens);
    const boilerplate = boilerplateScore(sentTokens) * cfg.boilerplateWeight;
    return Math.max(0, overlap - boilerplate);
  });
}

/**
 * LLM-tier async compression engine (T05/C3 — opt-in, default-off).
 *
 * A generic "LLM compressor" tier: it can condense the prose of non-system messages via
 * a pluggable LLM backend. It mirrors the `llmlingua` engine's contract exactly, but the
 * backend is a full chat-completion model rather than a local ONNX classifier.
 *
 * ## Safe by construction (default-off)
 * - The DEFAULT backend is a no-op (`text => text`), so out of the box the engine NEVER
 *   mutates the payload — it returns the body unchanged (`compressed:false`).
 * - It is NOT part of the default stacked pipeline; an operator must add it explicitly.
 * - `enabled` defaults to `false` in the config schema.
 * A real LLM backend is wired via `setLlmCompressorBackend()` (the same injection seam the
 * tests use). The real production model is intentionally left as a VPS-validated follow-up
 * (Hard Rule #18), exactly as the `llmlingua` worker backend is gated.
 *
 * ## Fail-open everywhere (never throws, never corrupts)
 * 1. Backend rejection/error per prose segment → segment kept as-is.
 * 2. Any unexpected error in `applyAsync` → original body, `compressed:false`, no throw.
 *
 * ## Code-block protection (inviolable)
 * Fenced code blocks (and other preserved constructs) are tombstoned via
 * `extractPreservedBlocks` and re-stitched verbatim — the engine physically never passes
 * code to the backend. System messages are never touched.
 */

import { createCompressionStats, estimateCompressionTokens } from "../../stats.ts";
import { extractPreservedBlocks } from "../../preservation.ts";
import type {
  CompressionEngine,
  CompressionEngineApplyOptions,
  EngineConfigField,
  EngineValidationResult,
} from "../types.ts";
import type { CompressionResult } from "../../types.ts";

// ─── backend abstraction ──────────────────────────────────────────────────────

export interface LlmCompressorBackendOptions {
  model?: string;
  compressionRate?: number;
}

/**
 * A backend takes a prose text segment (+ optional config) and returns a compressed
 * version. Any rejection/error MUST be caught by the caller; the engine fail-opens.
 */
export type LlmCompressorBackend = (
  text: string,
  opts?: LlmCompressorBackendOptions
) => Promise<string>;

/** The default production backend: a no-op that returns the text unchanged (pass-through). */
const noopBackend: LlmCompressorBackend = async (text) => text;

/** Module-level injectable backend (null = use the no-op default). */
let _backend: LlmCompressorBackend | null = null;

/** Override the backend — for tests and for wiring a real LLM. `null` restores the no-op. */
export function setLlmCompressorBackend(b: LlmCompressorBackend | null): void {
  _backend = b;
}

function resolveBackend(): LlmCompressorBackend {
  return _backend ?? noopBackend;
}

// ─── prose / code splitting (code is never sent to the backend) ─────────────────

interface TextSegment {
  kind: "prose" | "preserved";
  text: string;
}

function splitProseAndPreserved(text: string): TextSegment[] {
  const { text: withPlaceholders, blocks } = extractPreservedBlocks(text);
  if (blocks.length === 0) return [{ kind: "prose", text }];

  const placeholderToOriginal = new Map(blocks.map((b) => [b.placeholder, b.content]));
  const escaped = blocks.map((b) => b.placeholder.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const splitRe = new RegExp(`(${escaped.join("|")})`, "g");

  const segments: TextSegment[] = [];
  for (const part of withPlaceholders.split(splitRe)) {
    if (!part) continue;
    const original = placeholderToOriginal.get(part);
    segments.push(
      original !== undefined ? { kind: "preserved", text: original } : { kind: "prose", text: part }
    );
  }
  return segments;
}

// ─── message processing ─────────────────────────────────────────────────────────

type MessageLike = {
  role?: string;
  content?: string | Array<Record<string, unknown>>;
  [key: string]: unknown;
};

async function compressProseText(
  text: string,
  backend: LlmCompressorBackend,
  opts?: LlmCompressorBackendOptions
): Promise<{ text: string; didCompress: boolean }> {
  if (!text.trim()) return { text, didCompress: false };
  try {
    const compressed = await backend(text, opts);
    if (typeof compressed === "string" && compressed.length < text.length) {
      return { text: compressed, didCompress: true };
    }
    return { text, didCompress: false };
  } catch {
    return { text, didCompress: false };
  }
}

async function compressMessageText(
  text: string,
  backend: LlmCompressorBackend,
  opts?: LlmCompressorBackendOptions
): Promise<{ text: string; didCompress: boolean }> {
  const segments = splitProseAndPreserved(text);
  let anyCompressed = false;
  const parts: string[] = [];
  for (const seg of segments) {
    if (seg.kind === "preserved") {
      parts.push(seg.text);
    } else {
      const { text: out, didCompress } = await compressProseText(seg.text, backend, opts);
      parts.push(out);
      if (didCompress) anyCompressed = true;
    }
  }
  return { text: parts.join(""), didCompress: anyCompressed };
}

async function processMessages(
  messages: MessageLike[],
  backend: LlmCompressorBackend,
  opts?: LlmCompressorBackendOptions
): Promise<{ messages: MessageLike[]; compressedCount: number }> {
  let compressedCount = 0;
  const result: MessageLike[] = [];
  for (const msg of messages) {
    if (msg.role === "system") {
      result.push({ ...msg });
      continue;
    }
    try {
      if (typeof msg.content === "string") {
        const { text, didCompress } = await compressMessageText(msg.content, backend, opts);
        if (didCompress) {
          compressedCount++;
          result.push({ ...msg, content: text });
        } else {
          result.push({ ...msg });
        }
      } else if (Array.isArray(msg.content)) {
        let changed = false;
        const newContent: Array<Record<string, unknown>> = [];
        for (const part of msg.content) {
          if (part["type"] === "text" && typeof part["text"] === "string") {
            const { text, didCompress } = await compressMessageText(
              part["text"] as string,
              backend,
              opts
            );
            if (didCompress) {
              changed = true;
              compressedCount++;
              newContent.push({ ...part, text });
            } else {
              newContent.push(part);
            }
          } else {
            newContent.push(part);
          }
        }
        result.push(changed ? { ...msg, content: newContent } : { ...msg });
      } else {
        result.push({ ...msg });
      }
    } catch {
      result.push({ ...msg });
    }
  }
  return { messages: result, compressedCount };
}

// ─── config schema ────────────────────────────────────────────────────────────

const LLM_COMPRESSOR_SCHEMA: EngineConfigField[] = [
  // Default OFF: this tier costs an extra model call and mutates the payload, so it is
  // opt-in (Hard Rule #20 spirit) — never on by default.
  { key: "enabled", type: "boolean", label: "Enabled", defaultValue: false },
  { key: "model", type: "string", label: "Compression model", defaultValue: "" },
  {
    key: "minTokens",
    type: "number",
    label: "Min tokens (floor)",
    defaultValue: 2000,
    min: 0,
    max: 100000,
  },
  {
    key: "compressionRate",
    type: "number",
    label: "Compression rate (keep ratio)",
    defaultValue: 0.5,
    min: 0.1,
    max: 0.9,
  },
];

function validateLlmCompressorConfig(config: Record<string, unknown>): EngineValidationResult {
  const errors: string[] = [];
  if (config["enabled"] !== undefined && typeof config["enabled"] !== "boolean") {
    errors.push("enabled must be a boolean");
  }
  if (config["model"] !== undefined && typeof config["model"] !== "string") {
    errors.push("model must be a string");
  }
  if (config["minTokens"] !== undefined) {
    const v = config["minTokens"];
    if (typeof v !== "number" || Number.isNaN(v) || v < 0) errors.push("minTokens must be a number >= 0");
  }
  if (config["compressionRate"] !== undefined) {
    const v = config["compressionRate"];
    if (typeof v !== "number" || Number.isNaN(v) || v < 0.1 || v > 0.9) {
      errors.push("compressionRate must be a number between 0.1 and 0.9");
    }
  }
  return { valid: errors.length === 0, errors };
}

// ─── engine export ──────────────────────────────────────────────────────────────

const ENGINE_ID = "llm";

export const llmCompressorEngine: CompressionEngine = {
  id: ENGINE_ID,
  name: "LLM Compressor (opt-in)",
  description:
    "Opt-in LLM-tier compression: condenses the prose of non-system messages via a pluggable " +
    "chat-completion backend. Default-off and a no-op until an operator both enables it and wires " +
    "a real backend; fenced code blocks and system messages are never sent to the model. " +
    "Fail-opens on any backend error.",
  icon: "robot",
  targets: ["messages"],
  stackable: true,
  // Runs after llmlingua (35) but before ultra (40); semantic LLM rewriting is most useful
  // once cheaper structural/semantic passes have already reduced the prose.
  stackPriority: 38,
  metadata: {
    id: ENGINE_ID,
    name: "LLM Compressor (opt-in)",
    description:
      "Opt-in LLM-tier prose compression via a pluggable backend. Default-off / no-op; " +
      "code blocks and system messages are protected; fail-open on backend error.",
    inputScope: "messages",
    targetLatencyMs: 1500,
    supportsPreview: false,
    stable: true,
  },

  /** Synchronous pass-through — the real work is async-only (`applyAsync`). */
  apply(body: Record<string, unknown>): CompressionResult {
    return { body, compressed: false, stats: null };
  },

  async applyAsync(
    body: Record<string, unknown>,
    options?: CompressionEngineApplyOptions
  ): Promise<CompressionResult> {
    const stepConfig = options?.stepConfig ?? {};
    // Opt-in: only runs when explicitly enabled.
    if (stepConfig["enabled"] !== true) {
      return { body, compressed: false, stats: null };
    }

    const messages = body["messages"];
    if (!Array.isArray(messages) || messages.length === 0) {
      return { body, compressed: false, stats: null };
    }

    const minTokens =
      typeof stepConfig["minTokens"] === "number" ? (stepConfig["minTokens"] as number) : 2000;
    if (minTokens > 0) {
      const nonSystemText = (messages as MessageLike[])
        .filter((m) => m.role !== "system")
        .map((m) => (typeof m.content === "string" ? m.content : JSON.stringify(m.content ?? "")))
        .join("\n");
      if (estimateCompressionTokens(nonSystemText) < minTokens) {
        return { body, compressed: false, stats: null };
      }
    }

    const backendOpts: LlmCompressorBackendOptions = {
      model: typeof stepConfig["model"] === "string" ? (stepConfig["model"] as string) : undefined,
      compressionRate:
        typeof stepConfig["compressionRate"] === "number"
          ? (stepConfig["compressionRate"] as number)
          : undefined,
    };

    try {
      const backend = resolveBackend();
      const start = performance.now();
      const { messages: newMessages, compressedCount } = await processMessages(
        messages as MessageLike[],
        backend,
        backendOpts
      );
      if (compressedCount === 0) {
        return { body, compressed: false, stats: null };
      }
      const newBody: Record<string, unknown> = { ...body, messages: newMessages };
      const durationMs = Math.round(performance.now() - start);
      const stats = createCompressionStats(
        body,
        newBody,
        "stacked",
        [ENGINE_ID],
        [`llm-compressed-${compressedCount}-messages`],
        durationMs
      );
      return { body: newBody, compressed: true, stats };
    } catch {
      return { body, compressed: false, stats: null };
    }
  },

  compress(body: Record<string, unknown>, config?: Record<string, unknown>): CompressionResult {
    return this.apply(body, { stepConfig: config ?? {} });
  },

  getConfigSchema(): EngineConfigField[] {
    return LLM_COMPRESSOR_SCHEMA;
  },

  validateConfig(config: Record<string, unknown>): EngineValidationResult {
    return validateLlmCompressorConfig(config);
  },
};

/**
 * read-lifecycle compression engine (T08/H7 — gaps v3.8.42; opt-in, default-off).
 *
 * Agentic conversations re-Read the same files repeatedly. An earlier Read becomes **stale**
 * once the same path is Read again (superseded by a newer view) or modified by a later
 * Write/Edit. This engine collapses those superseded Read tool-results to a short stub, keeping
 * only the current (last, un-superseded) Read intact.
 *
 * Unlike `session-dedup` (content-addressed — collapses *identical* blocks) or `ccr` (reversible
 * markers), this is **semantic + lossy**: it removes stale content the later Read supersedes, so
 * it is **opt-in / default-off**. It is conservative: it matches only well-known Read/Write tool
 * names, compares exact paths, and collapses a Read only when a strictly-later invocation touches
 * the same path. Fail-open — any unexpected shape is left untouched.
 *
 * Supports both the Anthropic content-block shape (`tool_use` / `tool_result`) and the OpenAI
 * shape (assistant `tool_calls` + `role:"tool"` messages), linked by call id.
 */

import { createCompressionStats } from "../../stats.ts";
import type {
  CompressionEngine,
  CompressionEngineApplyOptions,
  EngineConfigField,
  EngineValidationResult,
} from "../types.ts";
import type { CompressionResult } from "../../types.ts";

const ENGINE_ID = "read-lifecycle";

/** Conservative tool-name classification (exact, lower-cased) — avoids false collapses. */
const READ_NAMES = new Set(["read", "read_file", "readfile", "view", "view_file", "cat"]);
const WRITE_NAMES = new Set([
  "write",
  "write_file",
  "writefile",
  "edit",
  "edit_file",
  "multiedit",
  "str_replace",
  "str_replace_editor",
  "str_replace_based_edit_tool",
  "apply_patch",
  "create_file",
  "update_file",
]);

function classifyTool(name: unknown): "read" | "write" | null {
  if (typeof name !== "string") return null;
  const lc = name.trim().toLowerCase();
  if (READ_NAMES.has(lc)) return "read";
  if (WRITE_NAMES.has(lc)) return "write";
  return null;
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

/** Extract a file path from a tool input object across common field names. */
function extractPath(input: unknown): string | null {
  if (!isRecord(input)) return null;
  for (const key of ["file_path", "path", "filePath", "filename", "file", "target_file"]) {
    const v = input[key];
    if (typeof v === "string" && v.trim()) return v.trim();
  }
  return null;
}

function parseMaybeJson(value: unknown): unknown {
  if (isRecord(value)) return value;
  if (typeof value === "string") {
    try {
      return JSON.parse(value);
    } catch {
      return null;
    }
  }
  return null;
}

interface ToolInvocation {
  callId: string;
  kind: "read" | "write";
  path: string;
  order: number;
}

type MessageLike = { role?: string; content?: unknown; tool_calls?: unknown; [k: string]: unknown };

/**
 * Collect Read/Write tool invocations in conversation order (Anthropic `tool_use` +
 * OpenAI `tool_calls`), with a map of read call ids → path for stub rendering.
 */
export function extractInvocations(messages: MessageLike[]): {
  invocations: ToolInvocation[];
  readPathByCallId: Map<string, string>;
} {
  const invocations: ToolInvocation[] = [];
  const readPathByCallId = new Map<string, string>();
  let order = 0;

  for (const msg of messages) {
    // Anthropic: content array with tool_use blocks.
    if (Array.isArray(msg?.content)) {
      for (const block of msg.content) {
        if (!isRecord(block) || block.type !== "tool_use") continue;
        const kind = classifyTool(block.name);
        const callId = typeof block.id === "string" ? block.id : null;
        const path = extractPath(block.input);
        if (kind && callId && path) {
          invocations.push({ callId, kind, path, order: order++ });
          if (kind === "read") readPathByCallId.set(callId, path);
        }
      }
    }
    // OpenAI: assistant.tool_calls array.
    if (Array.isArray(msg?.tool_calls)) {
      for (const call of msg.tool_calls) {
        if (!isRecord(call)) continue;
        const fn = isRecord(call.function) ? call.function : null;
        const kind = classifyTool(fn?.name);
        const callId = typeof call.id === "string" ? call.id : null;
        const path = extractPath(parseMaybeJson(fn?.arguments));
        if (kind && callId && path) {
          invocations.push({ callId, kind, path, order: order++ });
          if (kind === "read") readPathByCallId.set(callId, path);
        }
      }
    }
  }
  return { invocations, readPathByCallId };
}

/**
 * A read is superseded when a strictly-later invocation (read OR write) touches the same path.
 * Returns the set of Read call ids whose tool-results can be collapsed.
 */
export function findSupersededReadCallIds(invocations: ToolInvocation[]): Set<string> {
  const superseded = new Set<string>();
  for (const inv of invocations) {
    if (inv.kind !== "read") continue;
    const hasLater = invocations.some((o) => o.path === inv.path && o.order > inv.order);
    if (hasLater) superseded.add(inv.callId);
  }
  return superseded;
}

function stubFor(path: string): string {
  return `[read superseded — "${path}" was re-read or modified later in the conversation; the current content appears below]`;
}

function replaceResultText(content: unknown, stub: string): unknown {
  if (typeof content === "string") return stub;
  if (Array.isArray(content)) {
    return content.map((part) =>
      isRecord(part) && part.type === "text" && typeof part.text === "string"
        ? { ...part, text: stub }
        : part
    );
  }
  return stub;
}

/**
 * Collapse the tool-results of superseded reads to a stub (Anthropic `tool_result` blocks +
 * OpenAI `role:"tool"` messages), keyed by call id. Returns the new messages + collapse count.
 */
export function collapseSupersededReads(
  messages: MessageLike[],
  superseded: Set<string>,
  readPathByCallId: Map<string, string>
): { messages: MessageLike[]; collapsedCount: number } {
  if (superseded.size === 0) return { messages, collapsedCount: 0 };
  let collapsedCount = 0;

  const out = messages.map((msg) => {
    // OpenAI tool result message.
    if (
      msg?.role === "tool" &&
      typeof msg.tool_call_id === "string" &&
      superseded.has(msg.tool_call_id)
    ) {
      collapsedCount++;
      const path = readPathByCallId.get(msg.tool_call_id) ?? "file";
      return { ...msg, content: stubFor(path) };
    }
    // Anthropic tool_result blocks inside a content array.
    if (Array.isArray(msg?.content)) {
      let changed = false;
      const newContent = msg.content.map((block) => {
        if (
          isRecord(block) &&
          block.type === "tool_result" &&
          typeof block.tool_use_id === "string" &&
          superseded.has(block.tool_use_id)
        ) {
          changed = true;
          collapsedCount++;
          const path = readPathByCallId.get(block.tool_use_id) ?? "file";
          return { ...block, content: replaceResultText(block.content, stubFor(path)) };
        }
        return block;
      });
      if (changed) return { ...msg, content: newContent };
    }
    return msg;
  });

  return { messages: out, collapsedCount };
}

// ─── schema ──────────────────────────────────────────────────────────────────

const SCHEMA: EngineConfigField[] = [
  { key: "enabled", type: "boolean", label: "Enabled", defaultValue: false },
];

function validate(config: Record<string, unknown>): EngineValidationResult {
  const errors: string[] = [];
  if (config["enabled"] !== undefined && typeof config["enabled"] !== "boolean") {
    errors.push("enabled must be a boolean");
  }
  return { valid: errors.length === 0, errors };
}

export const readLifecycleEngine: CompressionEngine = {
  id: ENGINE_ID,
  name: "Read Lifecycle (opt-in)",
  description:
    "Collapses stale/superseded file-Read tool results: when the same path is re-read or modified " +
    "later in the conversation, earlier Reads are replaced with a short stub, keeping the current " +
    "Read intact. Lossy + opt-in (default off). Supports Anthropic and OpenAI tool shapes.",
  icon: "history",
  targets: ["messages"],
  stackable: true,
  // Runs early (before content engines) so stale reads are gone before other passes work on them.
  stackPriority: 5,
  metadata: {
    id: ENGINE_ID,
    name: "Read Lifecycle (opt-in)",
    description:
      "Collapse superseded file-Read tool results (same path re-read/modified later). " +
      "Lossy, opt-in, default off. Anthropic + OpenAI shapes.",
    inputScope: "messages",
    targetLatencyMs: 2,
    supportsPreview: true,
    stable: true,
  },

  apply(body: Record<string, unknown>, options?: CompressionEngineApplyOptions): CompressionResult {
    const stepConfig = options?.stepConfig ?? {};
    if (stepConfig["enabled"] !== true) {
      return { body, compressed: false, stats: null };
    }
    const messages = body["messages"];
    if (!Array.isArray(messages) || messages.length === 0) {
      return { body, compressed: false, stats: null };
    }
    try {
      const start = performance.now();
      const { invocations, readPathByCallId } = extractInvocations(messages as MessageLike[]);
      const superseded = findSupersededReadCallIds(invocations);
      const { messages: newMessages, collapsedCount } = collapseSupersededReads(
        messages as MessageLike[],
        superseded,
        readPathByCallId
      );
      if (collapsedCount === 0) {
        return { body, compressed: false, stats: null };
      }
      const newBody: Record<string, unknown> = { ...body, messages: newMessages };
      const durationMs = Math.round(performance.now() - start);
      const stats = createCompressionStats(
        body,
        newBody,
        "stacked",
        [ENGINE_ID],
        [`read-lifecycle-collapsed-${collapsedCount}`],
        durationMs
      );
      return { body: newBody, compressed: true, stats };
    } catch {
      // Fail-open: any unexpected shape leaves the body untouched.
      return { body, compressed: false, stats: null };
    }
  },

  compress(body: Record<string, unknown>, config?: Record<string, unknown>): CompressionResult {
    return this.apply(body, { stepConfig: config ?? {} });
  },

  getConfigSchema(): EngineConfigField[] {
    return SCHEMA;
  },

  validateConfig(config: Record<string, unknown>): EngineValidationResult {
    return validate(config);
  },
};

/**
 * OmniGlyph — compressão contexto-como-imagem (Anthropic/Fable 5 apenas).
 * Renderiza system prompt, tool docs, histórico antigo e tool_results grandes
 * como páginas PNG densas; o modelo lê as páginas no lugar do texto por ~10×
 * menos tokens no bloco convertido (59-70% ponta a ponta, medido).
 *
 * GATES (todos fail-closed; cada skip vira técnica `skip:<motivo>` nos stats):
 *  - supportsVision !== true            → skip:no_vision
 *  - modelo fora da allowlist medida    → skip:model_not_approved
 *  - providerTransport !== 'direct'     → skip:transport_not_direct
 *    (agregadores redimensionam imagens e destroem a legibilidade — medido)
 *  - corpo não é formato Claude nativo  → skip:source_format_not_claude
 *  - gate de rentabilidade interno do omniglyph decide o resto (patches 28px
 *    exatos; texto esparso/pequeno passa direto) → skip:not_profitable
 *
 * `sampling: true`: perda é INTENCIONAL (byte-exatos viajam no factsheet em
 * texto) — o fidelity gate pula esta engine por design, não por acidente.
 */
import type { CompressionEngine, CompressionEngineApplyOptions } from "./types.ts";
import type { CompressionResult } from "../types.ts";
import { createCompressionStats } from "../stats.ts";
import { transformAnthropicMessages, isOmniGlyphSupportedModel } from "omniglyph";

function skip(body: Record<string, unknown>, reason: string): CompressionResult {
  try {
    return {
      body,
      compressed: false,
      stats: createCompressionStats(body, body, "stacked", [`skip:${reason}`]),
    };
  } catch {
    // Fail-open guard: a non-serializable body (e.g. circular reference) makes
    // createCompressionStats' internal JSON.stringify throw too — stats become
    // best-effort telemetry, never a reason to propagate the error.
    return { body, compressed: false, stats: null };
  }
}

/** Formato Claude nativo: system no topo, nunca role:"system" dentro de messages. */
function isClaudeFormat(body: Record<string, unknown>): boolean {
  const messages = body.messages;
  if (!Array.isArray(messages)) return false;
  return !messages.some((m) => (m as { role?: string } | null)?.role === "system");
}

async function applyOmniglyph(
  body: Record<string, unknown>,
  options?: CompressionEngineApplyOptions
): Promise<CompressionResult> {
  const model = options?.model ?? (body as { model?: string }).model ?? "";
  if (options?.supportsVision !== true) return skip(body, "no_vision");
  if (!isOmniGlyphSupportedModel(model)) return skip(body, "model_not_approved");
  if (options?.providerTransport !== "direct") return skip(body, "transport_not_direct");
  if (!isClaudeFormat(body)) return skip(body, "source_format_not_claude");

  const started = Date.now();
  let outBody: Record<string, unknown>;
  try {
    const encoded = new TextEncoder().encode(JSON.stringify(body));
    const result = await transformAnthropicMessages({ body: encoded, model });
    if (!result.applied) return skip(body, result.reason ?? "not_profitable");
    outBody = JSON.parse(new TextDecoder().decode(result.body)) as Record<string, unknown>;
  } catch {
    // Fail-open: qualquer erro no encode/transform/decode (ex.: corpo não serializável,
    // render PNG estourando, JSON decodificado malformado) vira skip, nunca propaga.
    return skip(body, "transform_error");
  }

  return {
    body: outBody,
    compressed: true,
    stats: createCompressionStats(
      body,
      outBody,
      "stacked",
      ["omniglyph:context-as-image"],
      undefined,
      Date.now() - started
    ),
  };
}

export const omniglyphEngine: CompressionEngine = {
  id: "omniglyph",
  name: "OmniGlyph",
  description:
    "Contexto-como-imagem (Anthropic Fable 5, rota direta): system prompt, tool docs e histórico viram páginas PNG densas — ~10× menos tokens no bloco convertido.",
  icon: "image",
  targets: ["messages", "tool_results"],
  stackable: true,
  stackPriority: 90, // por último: RTK/Caveman limpam texto antes; omniglyph imageia o residual
  sampling: true, // perda intencional + factsheet → fidelity gate pula por design
  metadata: {
    id: "omniglyph",
    name: "OmniGlyph",
    description: "Contexto-como-imagem para Claude Fable 5 via rota direta Anthropic.",
    inputScope: "mixed",
    targetLatencyMs: 250, // render+encode PNG de páginas grandes
    supportsPreview: true,
    stable: false, // P1: preview — promover após o e2e P3 (30/30 via OmniRoute)
  },
  // Contrato da interface: engines async-only mantêm apply síncrono como pass-through seguro.
  apply(body) {
    return { body, compressed: false, stats: null };
  },
  applyAsync: applyOmniglyph,
  compress(body, config) {
    return this.apply(body, { stepConfig: config });
  },
  getConfigSchema() {
    return [];
  },
  validateConfig() {
    return { valid: true, errors: [] };
  },
};

