  return countTextTokens(text, { provider: "codex" });
}
const SUPPORTED_TYPES = new Set([
  "function_call_output",
  "local_shell_call_output",
  "apply_patch_call_output",
]);

const DIFF_HUNK_RE =
  /^@@{1,2}\s+-\d+(?:,\d+)?(?:\s+-\d+(?:,\d+)?)*\s+\+\d+(?:,\d+)?(?:,\d+)?\s+@@{1,2}/m;
const SEARCH_LINE_RE = /^\s*(?:[\w./-]+:\d+(?::\d+)?:|\d+(?::\d+)?[-:])\s*\S/m;
const IMPORTANT_LOG_RE =
  /(?:^|\b)(?:error|warning|warn|failed|failure|fatal|panic|exception|traceback|assertion|exit\s+code)\b/i;
const BUILD_RE =
  /\b(?:build|compile|test|lint|npm|yarn|pnpm|mix|make|cargo|gradle|maven|pytest|rspec|exunit)\b/i;

const CODEX_SCHEMA: EngineConfigField[] = [
  { key: "enabled", type: "boolean", label: "Enabled", defaultValue: false },
  {
    key: "minBytes",
    type: "number",
    label: "Minimum output bytes",
    defaultValue: DEFAULT_CODEX_RESPONSES_CONFIG.minBytes,
    min: 0,
    max: 2_000_000,
  },
  {
    key: "maxOutputBytes",
    type: "number",
    label: "Maximum output bytes",
    defaultValue: DEFAULT_CODEX_RESPONSES_CONFIG.maxOutputBytes,
    min: 1,
    max: 10_000_000,
  },
  {
    key: "maxCandidateBytes",
    type: "number",
    label: "Maximum candidate bytes",
    defaultValue: DEFAULT_CODEX_RESPONSES_CONFIG.maxCandidateBytes,
    min: 1,
    max: 2_000_000,
  },
  {
    key: "maxLines",
    type: "number",
    label: "Maximum retained lines",
    defaultValue: DEFAULT_CODEX_RESPONSES_CONFIG.maxLines,
    min: 1,
    max: 10_000,
  },
];

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function bounded(value: unknown, fallback: number, min: number, max: number): number {
  return typeof value === "number" && Number.isFinite(value)
    ? Math.min(max, Math.max(min, Math.floor(value)))
    : fallback;
}

function mergeConfig(options?: CompressionEngineApplyOptions): CodexResponsesConfig {
  const source = options?.config?.codexResponsesConfig ?? {};
  const step = options?.stepConfig ?? {};
  const merged = { ...DEFAULT_CODEX_RESPONSES_CONFIG, ...source, ...step };
  return {
    ...DEFAULT_CODEX_RESPONSES_CONFIG,
    enabled: merged.enabled !== false,
    minBytes: bounded(merged.minBytes, DEFAULT_CODEX_RESPONSES_CONFIG.minBytes, 0, 2_000_000),
    maxOutputBytes: bounded(
      merged.maxOutputBytes,
      DEFAULT_CODEX_RESPONSES_CONFIG.maxOutputBytes,
      1,
      10_000_000
    ),
    maxCandidateBytes: bounded(
      merged.maxCandidateBytes,
      DEFAULT_CODEX_RESPONSES_CONFIG.maxCandidateBytes,
      1,
      2_000_000
    ),
    maxLines: bounded(merged.maxLines, DEFAULT_CODEX_RESPONSES_CONFIG.maxLines, 1, 10_000),
    minSearchMatches: bounded(
      merged.minSearchMatches,
      DEFAULT_CODEX_RESPONSES_CONFIG.minSearchMatches,
      2,
      10_000
    ),
    minLogLines: bounded(merged.minLogLines, DEFAULT_CODEX_RESPONSES_CONFIG.minLogLines, 2, 10_000),
    preserveToolNames: Array.isArray(merged.preserveToolNames)
      ? merged.preserveToolNames.filter((name): name is string => typeof name === "string")
      : DEFAULT_CODEX_RESPONSES_CONFIG.preserveToolNames,
  };
}

function minifyJson(text: string): string | null {
  try {
    const parsed = JSON.parse(text) as unknown;
    if (!Array.isArray(parsed) && !isRecord(parsed)) return null;
    return JSON.stringify(parsed);
  } catch {
    return null;
  }
}

function collapseLines(text: string, config: CodexResponsesConfig): string | null {
  const lines = text.split(/\r?\n/);
  if (lines.length < config.minLogLines) return null;
  const important = lines
    .map((line, index) => ({ line, index }))
    .filter(
      ({ line }) => IMPORTANT_LOG_RE.test(line) || /^(?:\s*(?:at\s|File\s|\S+[:(]\d+))/.test(line)
    )
    .map(({ index }) => index);
  if (important.length === 0 && !BUILD_RE.test(text)) return null;
  const keep = new Set<number>();
  for (let index = 0; index < Math.min(8, lines.length); index++) keep.add(index);
  for (let index = Math.max(0, lines.length - 8); index < lines.length; index++) keep.add(index);
  for (const index of important) {
    for (let offset = -2; offset <= 2; offset++) {
      if (index + offset >= 0 && index + offset < lines.length) keep.add(index + offset);
    }
  }
  const indexes = [...keep].sort((a, b) => a - b).slice(0, config.maxLines);
  const output: string[] = [];
  let previous = -1;
  for (const index of indexes) {
    if (index - previous > 1)
      output.push(`[compressed log output: omitted ${index - previous - 1} lines]`);
    output.push(lines[index]);
    previous = index;
  }
  if (previous < lines.length - 1)
    output.push(`[compressed log output: omitted ${lines.length - previous - 1} lines]`);
  return output.join("\n");
}

function compactDiff(text: string, config: CodexResponsesConfig): string | null {
  if (!DIFF_HUNK_RE.test(text)) return null;
  const lines = text.split(/\r?\n/);
  const output: string[] = [];
  let changedSinceContext = 0;
  for (const line of lines) {
    const changed = line.startsWith("+") || line.startsWith("-") || line.startsWith("@@");
    if (changed) {
      output.push(line);
      changedSinceContext = 0;
    } else if (changedSinceContext < 2) {
      output.push(line);
      changedSinceContext++;
    }
  }
  return output.length < lines.length && output.length <= config.maxLines * 4
    ? output.join("\n")
    : null;
}

function compactSearch(text: string, config: CodexResponsesConfig): string | null {
  const lines = text.split(/\r?\n/);
  const matches = lines.filter((line) => SEARCH_LINE_RE.test(line));
  if (matches.length < config.minSearchMatches) return null;
  const grouped = new Map<string, string[]>();
  for (const line of matches) {
    const path = line.trim().split(/:\d/)[0].split(/-\d/)[0];
    const group = grouped.get(path) ?? [];
    if (group.length < 3) group.push(line.trim());
    grouped.set(path, group);
  }
  const output = [...grouped.entries()]
    .map(([path, entries]) => [path, ...entries].join("\n"))
    .join("\n");
  return output.length < text.length ? output : null;
}

function candidateRewrite(text: string, config: CodexResponsesConfig): string | null {
  if (Buffer.byteLength(text, "utf8") < config.minBytes) return null;
  if (Buffer.byteLength(text, "utf8") > config.maxCandidateBytes) return null;
  const json = minifyJson(text);
  const diff = compactDiff(text, config);
  const search = compactSearch(text, config);
  const log = collapseLines(text, config);
  return (
    [json, diff, search, log]
      .filter((value): value is string => typeof value === "string")
      .sort((a, b) => Buffer.byteLength(a) - Buffer.byteLength(b))[0] ?? null
  );
}

function rewriteText(value: unknown, config: CodexResponsesConfig): string | null {
  if (typeof value !== "string") return null;
  if (Buffer.byteLength(value, "utf8") > config.maxOutputBytes) return null;
  const rewritten = candidateRewrite(value, config);
  if (!rewritten || Buffer.byteLength(rewritten) >= Buffer.byteLength(value)) return null;
  if (countCodexTokens(rewritten) >= countCodexTokens(value)) {
    return null;
  }
  return rewritten;
}

function hasLossyRewriteCandidate(text: unknown, config: CodexResponsesConfig): boolean {
  if (typeof text !== "string") return false;
  return (
    compactDiff(text, config) !== null ||
    compactSearch(text, config) !== null ||
    collapseLines(text, config) !== null
  );
}

function protectedByConfig(meta: { type: string; eligible: boolean }): boolean {
  return !SUPPORTED_TYPES.has(meta.type) || !meta.eligible;
}

export const codexResponsesEngine: CompressionEngine = {
  id: ENGINE_ID,
  name: "Responses Tool Output",
  description: "Conservative lossless-first compression for supported Responses tool outputs.",
  icon: "data_object",
  targets: ["tool_results"],
  stackable: true,
  stackPriority: 12,
  metadata: {
    id: ENGINE_ID,
    name: "Responses Tool Output",
    description: "Compresses eligible shell, patch, search, build, and JSON outputs.",
    inputScope: "tool-results",
    targetLatencyMs: 5,
    supportsPreview: true,
    stable: true,
  },
  apply(body, options): CompressionResult {
    const config = mergeConfig(options);
    if (!config.enabled || !Array.isArray(body.messages)) {
      return { body, compressed: false, stats: null };
    }
    let changed = false;
    const messages = body.messages.map((raw) => {
      if (!isRecord(raw) || raw.role !== "tool") return raw;
      const meta = (raw as Record<string | symbol, unknown>)[CODEX_RESPONSE_ITEM_META] as
        { type?: unknown; eligible?: unknown } | undefined;
      if (!meta || typeof meta.type !== "string" || meta.eligible !== true) return raw;
      const typeMeta = { type: meta.type, eligible: true };
      if (protectedByConfig(typeMeta)) return raw;
      if (
        meta.type === "local_shell_call_output" &&
        hasLossyRewriteCandidate(raw.content, config)
      ) {
        return raw;
      }
      const next = rewriteText(raw.content, config);
      if (next === null) return raw;
      changed = true;
      return { ...raw, content: next };
    });
    if (!changed) return { body, compressed: false, stats: null };
    const nextBody = { ...body, messages };
    const stats = createCompressionStats(body, nextBody, "codex-responses", [ENGINE_ID]);
    const originalTokens = countCodexTokens(JSON.stringify(body));
    const compressedTokens = countCodexTokens(JSON.stringify(nextBody));
    stats.originalTokens = originalTokens;
    stats.compressedTokens = compressedTokens;
    stats.savingsPercent =
      originalTokens > 0
        ? Math.round(((originalTokens - compressedTokens) / originalTokens) * 10000) / 100
        : 0;
    return { body: nextBody, compressed: stats.compressedTokens < stats.originalTokens, stats };
  },
  compress(body, config): CompressionResult {
    return this.apply(body, { stepConfig: config });
  },
  getConfigSchema(): EngineConfigField[] {
    return CODEX_SCHEMA;
  },
  validateConfig(config): EngineValidationResult {
    const errors: string[] = [];
    for (const [key, min, max] of [
      ["minBytes", 0, 2_000_000],
      ["maxOutputBytes", 1, 10_000_000],
      ["maxCandidateBytes", 1, 2_000_000],
      ["maxLines", 1, 10_000],
      ["minSearchMatches", 2, 10_000],
      ["minLogLines", 2, 10_000],
    ] as const) {
      if (
        config[key] !== undefined &&
        (typeof config[key] !== "number" || config[key] < min || config[key] > max)
      ) {
        errors.push(`${key} must be between ${min} and ${max}`);
      }
    }
    if (config.enabled !== undefined && typeof config.enabled !== "boolean")
      errors.push("enabled must be boolean");
    return { valid: errors.length === 0, errors };
  },
};

import { registerBuiltinCompressionEngines } from "./index.ts";
import { getCompressionEngine } from "./registry.ts";
import type { CompressionEngineApplyOptions } from "./types.ts";
import type { CompressionResult } from "../types.ts";

/**
 * Single-mode resolution for the async-only "omniglyph" engine. Selecting the
 * "omniglyph" mode IS the enable signal — run it alone, same pattern as the
 * "rtk" single mode. (B-MODE-ENGINE-DECOUPLE)
 *
 * Kept out of strategySelector's runCompressionAsync so the dispatcher stays
 * under the complexity gate; this helper owns the registry lookup + the
 * fail-safe pass-through when the engine (or its async entry) is unavailable.
 */
export async function applyOmniglyphSingleMode(
  body: Record<string, unknown>,
  options?: CompressionEngineApplyOptions
): Promise<CompressionResult> {
  registerBuiltinCompressionEngines();
  const engine = getCompressionEngine("omniglyph");
  if (!engine?.applyAsync) return { body, compressed: false, stats: null };
  return engine.applyAsync(body, options);
}

/**
 * Cache-aware strategy selection for AI model compression.
 * Implements logic to detect caching context from request body and adjust strategies accordingly.
 *
 * @file cachingAware.ts
 * @exports CachingContext, CacheAwareStrategy, detectCachingContext, getCacheAwareStrategy
 */

import {
  providerSupportsCaching,
  type ConnectionCacheOverride,
} from "../../utils/cacheControlPolicy.ts";

type JsonRecord = Record<string, unknown>;

export interface CachingDetectionContext {
  provider?: string | null;
  targetFormat?: string | null;
  model?: string | null;
  connectionCacheOverride?: ConnectionCacheOverride | null;
}

export interface CachingContext {
  hasCacheControl: boolean;
  provider: string | null;
  targetFormat: string | null;
  isCachingProvider: boolean;
}

export interface CacheAwareStrategy {
  strategy: string;
  skipSystemPrompt: boolean;
  deterministicOnly: boolean;
}

function isRecord(value: unknown): value is JsonRecord {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function normalizeString(value: unknown): string | null {
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : null;
}

function inferProviderFromModel(model: unknown): string | null {
  const normalized = normalizeString(model);
  if (!normalized) return null;
  const slashIndex = normalized.indexOf("/");
  if (slashIndex <= 0) return null;
  return normalized.slice(0, slashIndex).toLowerCase();
}

function hasOwnCacheControl(value: unknown): boolean {
  return isRecord(value) && value.cache_control !== undefined && value.cache_control !== null;
}

function arrayHasCacheControl(values: unknown): boolean {
  return Array.isArray(values) && values.some((value) => hasCacheControl(value));
}

function hasCacheControl(value: unknown): boolean {
  if (hasOwnCacheControl(value)) return true;
  if (Array.isArray(value)) return value.some((item) => hasCacheControl(item));
  if (!isRecord(value)) return false;

  if (arrayHasCacheControl(value.system)) return true;
  if (arrayHasCacheControl(value.tools)) return true;
  if (arrayHasCacheControl(value.messages)) return true;
  if (arrayHasCacheControl(value.input)) return true;
  if (arrayHasCacheControl(value.contents)) return true;

  if (isRecord(value.request) && arrayHasCacheControl(value.request.contents)) return true;
  if (isRecord(value.content) || Array.isArray(value.content)) {
    return hasCacheControl(value.content);
  }

  return false;
}

/**
 * Detect the caching context from the request body.
 *
 * @param body - The request body to analyze
 * @param context - Explicit provider/format/model metadata from the routing pipeline
 * @returns A CachingContext object
 */
export function detectCachingContext(
  body: unknown,
  context: CachingDetectionContext = {}
): CachingContext {
  const bodyRecord = isRecord(body) ? body : {};
  const provider =
    normalizeString(context.provider)?.toLowerCase() ??
    inferProviderFromModel(context.model) ??
    inferProviderFromModel(bodyRecord.model);
  const targetFormat = normalizeString(context.targetFormat)?.toLowerCase() ?? null;

  return {
    hasCacheControl: hasCacheControl(body),
    provider,
    targetFormat,
    isCachingProvider: providerSupportsCaching(provider, targetFormat, context.connectionCacheOverride),
  };
}

/**
 * Get a cache-aware strategy based on the given strategy and caching context.
 *
 * @param strategy - The initial strategy (e.g., "aggressive", "ultra", etc.)
 * @param ctx - The caching context
 * @returns A CacheAwareStrategy object
 */
export function getCacheAwareStrategy(strategy: string, ctx: CachingContext): CacheAwareStrategy {
  // #3955: a caching provider is enough on its own to protect the cacheable prefix.
  // OpenAI / Codex (and other automatic-prefix-cache providers) carry NO explicit
  // `cache_control` markers, yet the upstream still caches the longest matching prefix
  // (system prompt / earliest messages). Gating on `hasCacheControl` skipped the guard
  // for those providers, so a prefix-compressing mode rewrote the prefix → guaranteed
  // cache miss. Treat `isCachingProvider` alone as sufficient; the explicit
  // `cache_control` path is now a subset of this.
  if (ctx.isCachingProvider) {
    return {
      strategy: ["aggressive", "ultra"].includes(strategy) ? "standard" : strategy,
      skipSystemPrompt: true,
      deterministicOnly: true,
    };
  }

  // Return the original strategy with no modifications
  return {
    strategy,
    skipSystemPrompt: false,
    deterministicOnly: false,
  };
}

/**
 * Cache Control Policy
 *
 * Determines when to preserve client-side prompt caching headers (cache_control)
 * vs. applying OmniRoute's own caching strategy.
 *
 * Client-side caching (e.g., Claude Code) is preserved when:
 * 1. Client is Claude Code or similar caching-aware client
 * 2. Provider supports prompt caching (Anthropic, etc.)
 *
 * Combo membership / routing strategy no longer gates preservation: rewriting a
 * caching-aware client's markers produced per-request breakpoint positions that
 * thrashed the provider prompt cache, while preserving them is never worse
 * (see shouldPreserveCacheControl).
 */

import type { RoutingStrategyValue } from "../../src/shared/constants/routingStrategies";

/**
 * Cache control preservation modes
 */
export type CacheControlMode = "auto" | "always" | "never";

/**
 * Cache control settings from the database
 */
export interface CacheControlSettings {
  alwaysPreserveClientCache?: CacheControlMode;
}

/**
 * Cache metrics for tracking effectiveness
 */
export interface CacheControlMetrics {
  // Totals
  totalRequests: number;
  requestsWithCacheControl: number;

  // Token counts
  totalInputTokens: number;
  totalCachedTokens: number;
  totalCacheCreationTokens: number;

  // Savings
  tokensSaved: number;
  estimatedCostSaved: number;

  // Breakdowns
  byProvider: Record<
    string,
    {
      requests: number;
      inputTokens: number;
      cachedTokens: number;
      cacheCreationTokens: number;
    }
  >;
  byStrategy: Record<
    string,
    {
      requests: number;
      inputTokens: number;
      cachedTokens: number;
      cacheCreationTokens: number;
    }
  >;

  lastUpdated: string;
}

/**
 * Routing strategies that are deterministic (same request → same provider)
 */
const DETERMINISTIC_STRATEGIES: Set<RoutingStrategyValue> = new Set(["priority", "cost-optimized"]);

/**
 * Providers that support prompt caching
 */
const CACHING_PROVIDERS = new Set([
  "claude",
  "anthropic",
  "zai",
  "deepseek",
  // Kimi Code's OpenAI protocol requires prompt_cache_key for Coding Plan
  // cache affinity. The OAuth card and hidden API-key compatibility ID share
  // the same upstream API.
  "kimi-coding",
  "kimi-coding-apikey",
  // #3088 — Xiaomi MiMo honors OpenAI-format cache_control breakpoints. Without
  // this entry, shouldPreserveCacheControl() returns false for Claude Code
  // clients and filterToOpenAIFormat() strips cache_control, so Xiaomi never
  // sees the cache hints and every request is a cache miss.
  "xiaomi-mimo",
  // #3955 — OpenAI / Codex / Azure-OpenAI use AUTOMATIC prefix caching: the longest
  // matching prefix of a request is cached upstream WITHOUT any explicit cache_control
  // markers. They must count as caching providers so the cache-aware compression guard
  // preserves the cacheable prefix (system prompt / earliest messages) instead of
  // rewriting it and forcing a cache miss. This also activates the intended
  // `prompt_cache_key` cache-routing hint for OpenAI in chatCore.
  "openai",
  "codex",
  "azure",
  // #2069 — DashScope's OpenAI-compatible endpoints (Alibaba Model Studio and
  // Qwen Cloud pay-as-you-go, upstream "alicode"/"alicode-intl") natively honor
  // `cache_control: {type:"ephemeral"}` breakpoints. Without these entries
  // shouldPreserveCacheControl() returns false for Claude Code clients and the
  // OpenAI-format translator strips cache_control, so DashScope never sees the
  // hints and every request is a cache miss.
  "alibaba",
  "alibaba-cn",
  "qwen-cloud",
]);

/**
 * Providers that honor EXPLICIT `cache_control` breakpoints carried inside an
 * OpenAI-format request body (i.e. the markers must be passed THROUGH the
 * Claude→OpenAI translation instead of stripped).
 *
 * This is a strict subset of CACHING_PROVIDERS and deliberately excludes
 * `openai` / `codex` / `azure`: those use AUTOMATIC prefix caching (#3955) and
 * do NOT accept explicit `cache_control` fields in the request — forwarding the
 * markers there is meaningless at best and a 400 "unknown field" at worst, and
 * it broke the chatCore "strips cache markers for non-Claude providers" test.
 * Claude-format providers re-inject markers via prepareClaudeRequest, so they
 * are not listed here either.
 */
const OPENAI_FORMAT_CACHE_CONTROL_PROVIDERS = new Set([
  // #2069 — DashScope OpenAI-compatible endpoints accept ephemeral breakpoints.
  "alibaba",
  "alibaba-cn",
  "qwen-cloud",
  // #3088 — Xiaomi MiMo honors OpenAI-format cache_control breakpoints.
  "xiaomi-mimo",
]);

/**
 * Per-connection override for cache behavior, resolved from the connection's
 * `provider_specific_data.cache` JSON sub-object (see `resolveConnectionCacheOverride`).
 * Lets an operator opt a custom/openai-compatible connection into prompt-cache
 * behavior that the hardcoded provider-name sets above can never match (#6880).
 */
export interface ConnectionCacheOverride {
  supportsPromptCaching?: boolean;
  cacheControlPassthrough?: "strip" | "openai-format" | "claude-format";
}

/**
 * Extract and validate a `ConnectionCacheOverride` from a connection's
 * `providerSpecificData` bag. Returns `null` when absent/malformed so every
 * call site can safely pass the result straight through.
 */
export function resolveConnectionCacheOverride(
  providerSpecificData: unknown
): ConnectionCacheOverride | null {
  if (!providerSpecificData || typeof providerSpecificData !== "object") return null;
  const cache = (providerSpecificData as Record<string, unknown>).cache;
  if (!cache || typeof cache !== "object" || Array.isArray(cache)) return null;
  const record = cache as Record<string, unknown>;
  const result: ConnectionCacheOverride = {};
  if (typeof record.supportsPromptCaching === "boolean") {
    result.supportsPromptCaching = record.supportsPromptCaching;
  }
  if (
    record.cacheControlPassthrough === "strip" ||
    record.cacheControlPassthrough === "openai-format" ||
    record.cacheControlPassthrough === "claude-format"
  ) {
    result.cacheControlPassthrough = record.cacheControlPassthrough;
  }
  return Object.keys(result).length > 0 ? result : null;
}

/**
 * Whether `cache_control` markers should be PASSED THROUGH the OpenAI-format
 * translation for this provider (vs. stripped). Used to gate the request-side
 * passthrough so generic / implicit-cache OpenAI providers keep getting cleaned.
 */
export function providerHonorsOpenAIFormatCacheControl(
  provider: string | null | undefined,
  connectionCacheOverride?: ConnectionCacheOverride | null
): boolean {
  if (connectionCacheOverride?.cacheControlPassthrough === "openai-format") return true;
  if (connectionCacheOverride?.cacheControlPassthrough === "strip") return false;
  if (!provider) return false;
  return OPENAI_FORMAT_CACHE_CONTROL_PROVIDERS.has(provider.toLowerCase());
}

/**
 * Detect if the client is Claude Code or another caching-aware client
 */
export function isClaudeCodeClient(userAgent: string | null | undefined): boolean {
  if (!userAgent) return false;
  const ua = userAgent.toLowerCase();

  // Claude Code user agents
  if (ua.includes("claude-code") || ua.includes("claude_code")) return true;
  if (ua.includes("claude-cli/")) return true;
  if (ua.includes("sdk-cli")) return true;
  if (ua.includes("anthropic") && ua.includes("cli")) return true;

  return false;
}

/**
 * Check if a provider supports prompt caching
 * Supports caching if:
 * 1. Provider is in the known caching providers list, OR
 * 2. Provider uses Claude protocol (detected via targetFormat)
 */
export function providerSupportsCaching(
  provider: string | null | undefined,
  targetFormat?: string | null,
  connectionCacheOverride?: ConnectionCacheOverride | null
): boolean {
  if (typeof connectionCacheOverride?.supportsPromptCaching === "boolean") {
    return connectionCacheOverride.supportsPromptCaching;
  }
  if (!provider) return false;
  if (CACHING_PROVIDERS.has(provider.toLowerCase())) return true;
  // All Claude-protocol providers support prompt caching
  if (targetFormat === "claude") return true;
  return false;
}

/**
 * Check if a routing strategy is deterministic
 */
export function isDeterministicStrategy(
  strategy: RoutingStrategyValue | null | undefined
): boolean {
  if (!strategy) return false;
  return DETERMINISTIC_STRATEGIES.has(strategy);
}

/**
 * Determine if client-side cache_control headers should be preserved
 *
 * Auto mode preserves for every caching-aware client talking to a
 * caching-capable provider — regardless of combo membership or routing
 * strategy. The old gate (combos only preserved on "deterministic"
 * strategies) forced OmniRoute to strip the client's markers and re-derive
 * breakpoints per request; the re-derived positions are not stable
 * turn-over-turn, which thrashed the provider prompt cache (observed in
 * production as ~200k cache_write tokens per turn on quota-share combos).
 * Preserving the client's markers is never worse than rewriting them: on a
 * stable target the client's breakpoints advance deterministically, and on a
 * target switch both approaches miss equally.
 *
 * @param userAgent - User-Agent header from the request
 * @param isCombo - Whether this is a combo model (kept for callers/telemetry;
 *   no longer gates preservation)
 * @param comboStrategy - The combo's routing strategy (kept for
 *   callers/telemetry; no longer gates preservation)
 * @param targetProvider - The target provider for the request
 * @param settings - Cache control settings from database (optional)
 * @returns true if cache_control should be preserved, false if OmniRoute should manage it
 */
export function shouldPreserveCacheControl({
  userAgent,
  targetProvider,
  targetFormat,
  settings,
  connectionCacheOverride,
}: {
  userAgent: string | null | undefined;
  isCombo: boolean;
  comboStrategy?: RoutingStrategyValue | null;
  targetProvider: string | null | undefined;
  targetFormat?: string | null;
  settings?: CacheControlSettings;
  connectionCacheOverride?: ConnectionCacheOverride | null;
}): boolean {
  // User override takes precedence
  if (settings?.alwaysPreserveClientCache === "always") {
    return true;
  }
  if (settings?.alwaysPreserveClientCache === "never") {
    return false;
  }

  // Auto mode: must be a caching-aware client…
  if (!isClaudeCodeClient(userAgent)) {
    return false;
  }

  // …talking to a provider that supports prompt caching.
  return providerSupportsCaching(targetProvider, targetFormat, connectionCacheOverride);
}

/**
 * Track cache control metrics for a request
 */
export function trackCacheMetrics({
  preserved,
  provider,
  strategy,
  metrics,
  inputTokens,
  cachedTokens,
  cacheCreationTokens,
}: {
  preserved: boolean;
  provider: string;
  strategy: string | null | undefined;
  metrics: CacheControlMetrics;
  inputTokens?: number;
  cachedTokens?: number;
  cacheCreationTokens?: number;
}): CacheControlMetrics {
  const now = new Date().toISOString();

  // Initialize metrics if empty
  if (!metrics) {
    metrics = {
      totalRequests: 0,
      requestsWithCacheControl: 0,
      totalInputTokens: 0,
      totalCachedTokens: 0,
      totalCacheCreationTokens: 0,
      tokensSaved: 0,
      estimatedCostSaved: 0,
      byProvider: {},
      byStrategy: {},
      lastUpdated: now,
    };
  }

  // Increment total requests
  metrics.totalRequests++;

  // Track token counts
  const input = inputTokens || 0;
  const cached = cachedTokens || 0;
  const creation = cacheCreationTokens || 0;

  metrics.totalInputTokens += input;
  metrics.totalCachedTokens += cached;
  metrics.totalCacheCreationTokens += creation;

  // Calculate tokens saved (cached tokens are reused, not charged)
  if (cached > 0) {
    metrics.tokensSaved += cached;
  }

  // Only track requests where cache_control was preserved
  if (preserved) {
    metrics.requestsWithCacheControl++;

    // Initialize provider tracking
    if (!metrics.byProvider[provider]) {
      metrics.byProvider[provider] = {
        requests: 0,
        inputTokens: 0,
        cachedTokens: 0,
        cacheCreationTokens: 0,
      };
    }
    metrics.byProvider[provider].requests++;
    metrics.byProvider[provider].inputTokens += input;
    metrics.byProvider[provider].cachedTokens += cached;
    metrics.byProvider[provider].cacheCreationTokens += creation;

    // Initialize strategy tracking
    if (strategy && !metrics.byStrategy[strategy]) {
      metrics.byStrategy[strategy] = {
        requests: 0,
        inputTokens: 0,
        cachedTokens: 0,
        cacheCreationTokens: 0,
      };
    }
    if (strategy) {
      metrics.byStrategy[strategy].requests++;
      metrics.byStrategy[strategy].inputTokens += input;
      metrics.byStrategy[strategy].cachedTokens += cached;
      metrics.byStrategy[strategy].cacheCreationTokens += creation;
    }
  }

  metrics.lastUpdated = now;
  return metrics;
}

/**
 * Record cache token usage and update metrics
 */
export function updateCacheTokenMetrics({
  metrics,
  provider,
  strategy,
  inputTokens,
  cachedTokens,
  cacheCreationTokens,
  costSaved,
}: {
  metrics: CacheControlMetrics;
  provider: string;
  strategy: string | null | undefined;
  inputTokens: number;
  cachedTokens: number;
  cacheCreationTokens: number;
  costSaved?: number;
}): CacheControlMetrics {
  metrics.totalCachedTokens += cachedTokens;
  metrics.totalCacheCreationTokens += cacheCreationTokens;
  metrics.totalInputTokens += inputTokens;

  // Cached tokens are reused (saved), creation tokens are new cache writes
  metrics.tokensSaved += cachedTokens;
  if (costSaved !== undefined) {
    metrics.estimatedCostSaved += costSaved;
  }

  // Update provider tracking
  if (metrics.byProvider[provider]) {
    metrics.byProvider[provider].cachedTokens += cachedTokens;
    metrics.byProvider[provider].cacheCreationTokens += cacheCreationTokens;
    metrics.byProvider[provider].inputTokens += inputTokens;
  }

  // Update strategy tracking
  if (strategy && metrics.byStrategy[strategy]) {
    metrics.byStrategy[strategy].cachedTokens += cachedTokens;
    metrics.byStrategy[strategy].cacheCreationTokens += cacheCreationTokens;
    metrics.byStrategy[strategy].inputTokens += inputTokens;
  }

  metrics.lastUpdated = new Date().toISOString();
  return metrics;
}

import { deriveDefaultPlan, type DerivedPlan } from "./deriveDefaultPlan.ts";

export interface ResolveCtx {
  comboId?: string | null;
  combos?: Record<string, Array<{ engine: string; intensity?: string }>>; // named combo pipelines by id
}

export function resolveCompressionPlan(config: any, ctx: ResolveCtx): DerivedPlan {
  if (config?.enabled === false) return { mode: "off", stackedPipeline: [] };

  // routing-combo override
  const ov = ctx.comboId ? config?.comboOverrides?.[ctx.comboId] : undefined;
  if (ov) return modeToPlan(ov, config);

  // active named combo
  if (config?.activeComboId && ctx.combos?.[config.activeComboId]) {
    return { mode: "stacked", stackedPipeline: ctx.combos[config.activeComboId] };
  }

  // derived default
  return deriveDefaultPlan(config?.engines ?? {}, config?.enabled !== false);
}

function modeToPlan(mode: string, config: any): DerivedPlan {
  return mode === "stacked"
    ? { mode: "stacked", stackedPipeline: config?.stackedPipeline ?? [] }
    : { mode, stackedPipeline: [] };
}

import { ENGINE_CATALOG, engineMeta } from "./engineCatalog.ts";
import type { EngineToggle } from "./types.ts";

/** Maps single-mode engine ids to the effective CompressionMode name. */
const SINGLE_MODE_OF: Record<string, string> = {
  lite: "lite",
  caveman: "standard",
  aggressive: "aggressive",
  ultra: "ultra",
  rtk: "rtk",
  "codex-responses": "codex-responses",
  omniglyph: "omniglyph",
};

export type CompressionSource =
  "request-header" | "routing-override" | "active-profile" | "auto-trigger" | "default" | "off";

export interface DerivedPlan {
  mode: string;
  stackedPipeline: Array<{ engine: string; intensity?: string }>;
  /** Which precedence layer decided this plan (Phase 3 observability). Optional so
   *  Phase 1/2 callers and snapshots are unaffected. */
  source?: CompressionSource;
}

/**
 * Derives the effective compression plan from the per-engine toggle map.
 *
 * Rules (evaluated in order):
 *  1. masterEnabled=false OR no engines on  → { mode:"off", stackedPipeline:[] }
 *  2. Exactly one engine on AND it is single-mode → that engine's standalone mode
 *  3. Otherwise → { mode:"stacked", stackedPipeline: enabled engines sorted by stackPriority }
 */
export function deriveDefaultPlan(
  engines: Record<string, EngineToggle>,
  masterEnabled: boolean
): DerivedPlan {
  if (!masterEnabled) return { mode: "off", stackedPipeline: [] };

  const onIds = Object.keys(ENGINE_CATALOG).filter((id) => engines[id]?.enabled === true);

  if (onIds.length === 0) return { mode: "off", stackedPipeline: [] };

  if (onIds.length === 1 && engineMeta(onIds[0]).isSingleMode) {
    return { mode: SINGLE_MODE_OF[onIds[0]], stackedPipeline: [] };
  }

  const ordered = onIds.sort((a, b) => engineMeta(a).stackPriority - engineMeta(b).stackPriority);

  const stackedPipeline = ordered.map((id) => {
    const level = engines[id]?.level;
    return level ? { engine: id, intensity: level } : { engine: id };
  });

  return { mode: "stacked", stackedPipeline };
}

import type { CompressionConfig, CompressionPipelineStep, CompressionStats } from "./types.ts";
import { resolveCompressionPlan } from "./resolveCompressionPlan.ts";
import {
  deriveDefaultPlan,
  type DerivedPlan,
  type CompressionSource,
} from "./deriveDefaultPlan.ts";

/** Named-combo map: combo id → its stacked pipeline (operator-defined profiles). */
type NamedCombos = Record<string, CompressionPipelineStep[]>;

const MAX_COMPRESSION_ANNOTATION_BYTES = 768;
const NON_ASCII_HEADER_VALUE_CHARS = /[^\x20-\x7e]/g;

function utf8ByteLength(value: string): number {
  return new TextEncoder().encode(value).byteLength;
}

/** Tags a plan with the precedence layer that produced it (Phase 3 observability). */
export function withSource(plan: DerivedPlan, source: CompressionSource): DerivedPlan {
  return { ...plan, source };
}

/**
 * Interprets the `x-omniroute-compression` request header into a plan, or null when the
 * value is unrecognized (caller falls through to normal resolution). Pure.
 *   off            -> no compression
 *   default        -> the panel-derived Default (ignores active profile / routing / auto-trigger)
 *   engine:<id>    -> that single engine, when enabled in config.engines
 *   <combo>        -> a named combo, matched name-first (lowercased) then exact id (Decision A)
 */
export function planFromHeader(
  config: CompressionConfig,
  header: string,
  combos: NamedCombos
): DerivedPlan | null {
  const h = header.trim();
  if (!h) return null;
  const lower = h.toLowerCase();

  if (lower === "off") return withSource({ mode: "off", stackedPipeline: [] }, "request-header");

  if (lower === "default") {
    // Empty combos + null comboId yields the pure panel default (no active-combo leak).
    return withSource(deriveDefaultPlanFromConfig(config, null, {}), "request-header");
  }

  if (lower.startsWith("engine:")) {
    const id = lower.slice("engine:".length).trim();
    const engine = config.engines?.[id];
    return engine?.enabled
      ? withSource(deriveDefaultPlan({ [id]: engine }, true), "request-header")
      : null;
  }

  const combo = combos[lower] ?? combos[h];
  return combo ? withSource({ mode: "stacked", stackedPipeline: combo }, "request-header") : null;
}

/** Renders the X-OmniRoute-Compression response header value. */
export function formatCompressionMeta(plan: DerivedPlan): string {
  return `${plan.mode}; source=${plan.source ?? "off"}`;
}

/**
 * Builds the annotation suffix for X-OmniRoute-Compression from compression stats.
 * Returns "" when there are no rules to aggregate (caller skips the append).
 * Format: `tokens=<orig>-><comp>; rules: <name>x<count>, ...` sorted by count desc.
 * ASCII-only: this string is appended to the X-OmniRoute-Compression HTTP header,
 * whose value is a latin-1 ByteString — a non-ASCII char (e.g. U+2192 →) throws at
 * Response/Headers construction (500). Keep the UI badge's arrow in the JSX, not here.
 */
export function formatCompressionAnnotation(stats: CompressionStats): string {
  const rules = stats.rulesApplied;
  if (!rules || rules.length === 0) return "";

  const counts = new Map<string, number>();
  for (const rule of rules) {
    const safeRule = rule.replace(NON_ASCII_HEADER_VALUE_CHARS, "?");
    counts.set(safeRule, (counts.get(safeRule) ?? 0) + 1);
  }

  const sorted = [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  const prefix = `tokens=${stats.originalTokens}->${stats.compressedTokens}; rules: `;
  const suffix = ", ...";
  const parts: string[] = [];
  let bytes = utf8ByteLength(prefix);
  for (const [name, n] of sorted) {
    const part = `${name}x${n}`;
    const separator = parts.length > 0 ? ", " : "";
    const partBytes = utf8ByteLength(separator + part);
    if (bytes + partBytes > MAX_COMPRESSION_ANNOTATION_BYTES - utf8ByteLength(suffix)) {
      if (parts.length === 0) return "";
      return `${prefix}${parts.join(", ")}${suffix}`;
    }
    parts.push(part);
    bytes += partBytes;
  }
  const agg = parts.join(", ");
  return `${prefix}${agg}`;
}

/**
 * Builds the named-combo lookup keyed by BOTH combo id and lowercased (trimmed) name, so the
 * `<combo>` header form can match by either. A combo with a blank/whitespace/missing name
 * contributes only its id key — a blank name would otherwise register a useless "" key, and a
 * single malformed row must not throw and disable the whole map (`name` is NOT NULL in the DB
 * but may be an empty string). Pure.
 */
export function buildNamedComboLookup(
  combos: Array<{ id: string; name?: string | null; pipeline: CompressionPipelineStep[] }>
): NamedCombos {
  const map: NamedCombos = {};
  for (const c of combos) {
    map[c.id] = c.pipeline;
    const name = c.name?.trim();
    if (name) map[name.toLowerCase()] = c.pipeline;
  }
  return map;
}

/**
 * Derived-default step. The per-engine toggle map drives the default ONLY when it was
 * EXPLICITLY configured via the panel (a stored `engines` row — `config.enginesExplicit`).
 * For legacy installs the map is backfilled for DISPLAY only (so the panel shows current
 * state); dispatch falls back to the historical `config.defaultMode` so behaviour is
 * byte-for-byte preserved until the operator opts into the panel by saving. This avoids a
 * silent behaviour change for installs whose backfilled engine flags don't exactly match
 * their old defaultMode.
 */
export function deriveDefaultPlanFromConfig(
  config: CompressionConfig,
  comboId: string | null,
  combos: NamedCombos = {}
): DerivedPlan {
  if (config.enginesExplicit) {
    // Panel-configured: the engines map (via the resolver, which stays header/active-combo
    // aware for Phases 2-3) is authoritative — including an explicit "everything off".
    return resolveCompressionPlan(config, { comboId, combos });
  }

  // Legacy path: defaultMode carries the effective mode (the engines map is display-only here).
  const legacyMode = config.defaultMode;
  if (legacyMode && legacyMode !== "off") {
    return legacyMode === "stacked"
      ? { mode: legacyMode, stackedPipeline: config.stackedPipeline ?? [] }
      : { mode: legacyMode, stackedPipeline: [] };
  }

  return { mode: "off", stackedPipeline: [] };
}

import type { DerivedPlan } from "../deriveDefaultPlan.ts";
import type { AdaptiveTelemetry, ContextBudgetConfig, LadderStage } from "./types.ts";
import { DEFAULT_LADDER, aggressivenessOf, expectedReductionFactor } from "./ladder.ts";
import { computeTarget } from "./computeTarget.ts";

export interface ResolveAdaptiveInput {
  basePlan: DerivedPlan;
  estimatedTokens: number;
  modelContextLimit: number | null;
  requestMaxTokens: number | null;
  config: ContextBudgetConfig;
  /**
   * Injected per-stage estimator (design §4.1/§9). Returns the NEW token estimate after a
   * stage is applied to a prompt of `priorTokens`. Default models it with the cheap
   * per-engine expected-reduction factor (no dry-run, no real tokenizer).
   */
  estimate?: (priorTokens: number, stage: LadderStage) => number;
}

export interface ResolveAdaptiveResult {
  plan: DerivedPlan;
  telemetry: AdaptiveTelemetry | null;
}

const defaultEstimate = (prior: number, stage: LadderStage): number =>
  Math.round(prior * expectedReductionFactor(stage.engine));

/**
 * Pure adaptive resolver (design §4.2). Floors/escalates a base plan so the (estimated)
 * compressed prompt fits the context budget. Never drops content: if the ladder is
 * exhausted while still over target, returns the best-effort plan with fit=false.
 *
 * Returns telemetry=null only when there is no usable target (unknown model limit) — the
 * caller then skips adaptive entirely (design §6: skip, never throw).
 */
export function resolveAdaptivePlan(input: ResolveAdaptiveInput): ResolveAdaptiveResult {
  const { basePlan, estimatedTokens, modelContextLimit, requestMaxTokens, config } = input;
  const estimate = input.estimate ?? defaultEstimate;

  if (config.mode === "off") return { plan: basePlan, telemetry: null };
  if (!modelContextLimit || modelContextLimit <= 0) {
    return { plan: basePlan, telemetry: null }; // unknown limit → skip (D-C / §6)
  }

  const target = computeTarget(config.policy, modelContextLimit, requestMaxTokens, config);
  const headroomBefore = target - estimatedTokens;

  // replace-autotrigger only acts on a bare Default/off base plan; an explicit choice wins.
  const baseRank = aggressivenessOf(basePlan.mode);
  if (config.mode === "replace-autotrigger" && baseRank > aggressivenessOf("off")) {
    return {
      plan: basePlan,
      telemetry: { policy: config.policy, target, headroomBefore, stagesApplied: [], headroomAfter: headroomBefore, fit: headroomBefore >= 0 },
    };
  }

  // Already fits → never over-compress (D-C2).
  if (headroomBefore >= 0) {
    return {
      plan: basePlan,
      telemetry: { policy: config.policy, target, headroomBefore, stagesApplied: [], headroomAfter: headroomBefore, fit: true },
    };
  }

  // Escalation: start just ABOVE the base plan's aggressiveness (floor escalates beyond it).
  const ladder = config.ladderOverride && config.ladderOverride.length > 0 ? config.ladderOverride : DEFAULT_LADDER;
  const startTier = config.mode === "floor" ? baseRank : aggressivenessOf("off");
  const stages = ladder.filter((s) => aggressivenessOf(s.engine) > startTier);

  let current = estimatedTokens;
  const applied: LadderStage[] = [];
  for (const stage of stages) {
    current = estimate(current, stage);
    applied.push(stage);
    if (current <= target) break;
  }

  const headroomAfter = target - current;
  const fit = headroomAfter >= 0;
  return {
    plan: planFromStages(basePlan, applied),
    telemetry: {
      policy: config.policy,
      target,
      headroomBefore,
      stagesApplied: applied.map((s) => s.engine),
      headroomAfter,
      fit,
    },
  };
}

/**
 * Turn the applied ladder stages into a DerivedPlan. A single applied stage that is a
 * single-mode engine collapses to that engine's mode; otherwise a stacked pipeline.
 * The base plan's own pipeline is preserved as the prefix (floor escalates AFTER the base).
 */
function planFromStages(basePlan: DerivedPlan, applied: LadderStage[]): DerivedPlan {
  if (applied.length === 0) return basePlan;
  const basePipeline =
    basePlan.mode === "stacked" ? basePlan.stackedPipeline : [];
  const stackedPipeline = [...basePipeline, ...applied];
  return { mode: "stacked", stackedPipeline };
}

import type { ContextBudgetConfig, ContextBudgetPolicy } from "./types.ts";

/**
 * Pure target-token computation (design D-C1). No clock, no DB, no tokenizer.
 *
 * @param policy            active target policy
 * @param modelContextLimit the resolved upstream model's context window (impure caller looks it up)
 * @param requestMaxTokens  request.max_tokens, if the client sent one (reserve-output only)
 * @param config            reserves / margin / pct / absoluteBudget
 * @returns the maximum prompt-token target the compressed request should fit within
 */
export function computeTarget(
  policy: ContextBudgetPolicy,
  modelContextLimit: number,
  requestMaxTokens: number | null,
  config: Pick<ContextBudgetConfig, "outputReserve" | "safetyMargin" | "pct" | "absoluteBudget">
): number {
  if (policy === "absolute") {
    return Math.max(0, Math.floor(config.absoluteBudget));
  }
  if (policy === "percentage") {
    const pct = config.pct > 0 && config.pct <= 1 ? config.pct : 1;
    return Math.max(0, Math.floor(modelContextLimit * pct));
  }
  // reserve-output (default): limit − output reservation − safety margin.
  const reserve =
    typeof requestMaxTokens === "number" && requestMaxTokens > 0
      ? requestMaxTokens
      : config.outputReserve;
  return Math.max(0, Math.floor(modelContextLimit - reserve - config.safetyMargin));
}

import type { CompressionResult } from "../types.ts";
import type { CompressionConfig } from "../types.ts";
import { applyRiskMask, restoreRiskBlocks } from "./riskGateStep.ts";
import type { RiskGateConfig } from "./riskGate.ts";

/** Resolve the effective risk-gate config (explicit option wins over config); enabled-gated. */
export function resolveRiskGate(options?: {
  riskGate?: RiskGateConfig;
  config?: CompressionConfig;
}): RiskGateConfig | undefined {
  const rg = options?.riskGate ?? options?.config?.riskGate;
  return rg?.enabled ? rg : undefined;
}

function attach(
  result: CompressionResult,
  mask: ReturnType<typeof applyRiskMask>
): CompressionResult {
  if (mask.blocks.length) result.body = restoreRiskBlocks(result.body, mask.blocks);
  if (result.stats) result.stats.riskGate = mask.stats;
  return result;
}

/** Outer mask→run→restore wrapper for a sync compression entry point. Byte-identical when gate absent. */
export function withRiskGate(
  body: Record<string, unknown>,
  riskGate: RiskGateConfig | undefined,
  run: (b: Record<string, unknown>) => CompressionResult
): CompressionResult {
  if (!riskGate) return run(body);
  const mask = applyRiskMask(body, riskGate);
  return attach(run(mask.maskedBody), mask);
}

/** Async variant of withRiskGate. */
export async function withRiskGateAsync(
  body: Record<string, unknown>,
  riskGate: RiskGateConfig | undefined,
  run: (b: Record<string, unknown>) => Promise<CompressionResult>
): Promise<CompressionResult> {
  if (!riskGate) return run(body);
  const mask = applyRiskMask(body, riskGate);
  return attach(await run(mask.maskedBody), mask);
}

import { preserveSpans, restorePreservedBlocks, type PreservedBlock } from "../preservation.ts";
import { detectRiskSpans, type RiskGateConfig } from "./riskGate.ts";
import type { RiskCategory } from "./riskPatterns.ts";

export interface RiskGateStats {
  spansProtected: number;
  categories: Partial<Record<RiskCategory, number>>;
}

export interface RiskMaskResult {
  maskedBody: Record<string, unknown>;
  blocks: PreservedBlock[];
  stats: RiskGateStats;
}

interface TextPart {
  type?: string;
  text?: string;
}

/** Mask one content string; returns masked text + blocks + per-category counts. */
function maskString(
  text: string,
  cfg: RiskGateConfig,
  tally: Partial<Record<RiskCategory, number>>
): { masked: string; blocks: PreservedBlock[] } {
  const spans = detectRiskSpans(text, cfg);
  if (!spans.length) return { masked: text, blocks: [] };
  for (const s of spans) tally[s.category] = (tally[s.category] ?? 0) + 1;
  const { text: masked, blocks } = preserveSpans(
    text,
    spans.map((s) => ({ start: s.start, end: s.end, kind: `risk_${s.category}` }))
  );
  return { masked, blocks };
}

/**
 * Mask risky spans in every message content (string or `{type:"text"}` parts).
 * Pure: clones touched messages, leaves the original body unmutated. Fail-open.
 */
export function applyRiskMask(body: Record<string, unknown>, cfg: RiskGateConfig): RiskMaskResult {
  const tally: Partial<Record<RiskCategory, number>> = {};
  const allBlocks: PreservedBlock[] = [];
  const messages = body.messages;
  if (!Array.isArray(messages)) {
    return { maskedBody: body, blocks: [], stats: { spansProtected: 0, categories: {} } };
  }

  let changed = false;
  const maskedMessages = messages.map((msg) => {
    const m = msg as { role?: unknown; content?: unknown };
    if (typeof m.content === "string") {
      const { masked, blocks } = maskString(m.content, cfg, tally);
      if (!blocks.length) return msg;
      changed = true;
      allBlocks.push(...blocks);
      return { ...m, content: masked };
    }
    if (Array.isArray(m.content)) {
      let partChanged = false;
      const parts = (m.content as TextPart[]).map((p) => {
        if (p && p.type === "text" && typeof p.text === "string") {
          const { masked, blocks } = maskString(p.text, cfg, tally);
          if (!blocks.length) return p;
          partChanged = true;
          allBlocks.push(...blocks);
          return { ...p, text: masked };
        }
        return p;
      });
      if (!partChanged) return msg;
      changed = true;
      return { ...m, content: parts };
    }
    return msg;
  });

  const maskedBody = changed ? { ...body, messages: maskedMessages } : body;
  return {
    maskedBody,
    blocks: allBlocks,
    stats: { spansProtected: allBlocks.length, categories: tally },
  };
}

/** Restore every masked span in the (possibly compressed) body. Fail-open. */
export function restoreRiskBlocks(
  body: Record<string, unknown>,
  blocks: PreservedBlock[]
): Record<string, unknown> {
  if (!blocks.length) return body;
  const messages = body.messages;
  if (!Array.isArray(messages)) return body;
  const restoreParts = (content: unknown): unknown => {
    if (typeof content === "string") return restorePreservedBlocks(content, blocks);
    if (Array.isArray(content)) {
      return (content as TextPart[]).map((p) =>
        p && p.type === "text" && typeof p.text === "string"
          ? { ...p, text: restorePreservedBlocks(p.text, blocks) }
          : p
      );
    }
    return content;
  };
  return {
    ...body,
    messages: messages.map((msg) => {
      const m = msg as { content?: unknown };
      if (typeof m.content === "string" || Array.isArray(m.content)) {
        return { ...m, content: restoreParts(m.content) };
      }
      return msg;
    }),
  };
}

import { RISK_PATTERNS, type RiskCategory } from "./riskPatterns.ts";

export interface RiskGateConfig {
  enabled: boolean;
  /** Subset of categories to scan for. Absent/empty ⇒ all categories. */
  categories?: RiskCategory[];
}

export interface RiskSpan {
  start: number; // inclusive char offset
  end: number; // exclusive
  category: RiskCategory;
}

interface Hit {
  start: number;
  end: number;
  category: RiskCategory;
}

const SHORT_SECTION = 200;
const MIN_DDL = 2;
const VCS_LINE = /^(?:commit [0-9a-f]{7,40}|diff --git |@@ |[+-]{3} )/m;
const DIFF_HUNK_LINE = /^[+-]/;

function isLikelyVcsContext(text: string): boolean {
  return VCS_LINE.test(text);
}

/** Collect raw regex hits for enabled categories (no guards yet). */
function collectRegexHits(text: string, enabled: Set<RiskCategory>): Hit[] {
  const hits: Hit[] = [];
  for (const { category, regex } of RISK_PATTERNS) {
    if (!enabled.has(category)) continue;
    regex.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = regex.exec(text)) !== null) {
      if (m[0].length === 0) {
        regex.lastIndex++;
        continue;
      }
      hits.push({ start: m.index, end: m.index + m[0].length, category });
    }
  }
  return hits;
}

/** True when the hit's line starts with a diff marker (`+`/`-`). */
function inDiffHunk(text: string, start: number): boolean {
  const lineStart = text.lastIndexOf("\n", start - 1) + 1;
  return DIFF_HUNK_LINE.test(text.slice(lineStart, lineStart + 1));
}

/** Structural k8s Secret detector: a YAML doc carrying `kind: Secret` + `data:`. */
function detectK8sSecret(text: string): Hit[] {
  const hits: Hit[] = [];
  const kindRe = /^kind:[ \t]*Secret\b/gm;
  let m: RegExpExecArray | null;
  while ((m = kindRe.exec(text)) !== null) {
    // Document boundaries: nearest `---`/start before, nearest `---`/end after.
    const prevSep = text.lastIndexOf("\n---", m.index);
    const docStart = prevSep === -1 ? 0 : prevSep + 1;
    const nextSep = text.indexOf("\n---", m.index);
    const docEnd = nextSep === -1 ? text.length : nextSep + 1;
    const doc = text.slice(docStart, docEnd);
    if (/^\s*(?:data|stringData):/m.test(doc)) {
      hits.push({ start: docStart, end: docEnd, category: "k8s_secret" });
    }
  }
  return hits;
}

function mergeSpans(spans: RiskSpan[]): RiskSpan[] {
  if (spans.length <= 1) return spans;
  const sorted = [...spans].sort((a, b) => a.start - b.start);
  const out: RiskSpan[] = [sorted[0]];
  for (let i = 1; i < sorted.length; i++) {
    const last = out[out.length - 1];
    const cur = sorted[i];
    if (cur.start <= last.end) {
      last.end = Math.max(last.end, cur.end);
    } else {
      out.push(cur);
    }
  }
  return out;
}

/**
 * Detect spans that should be shielded from compression. Pure and fail-open:
 * any internal error yields an empty result (never throws).
 */
export function detectRiskSpans(text: string, cfg: RiskGateConfig): RiskSpan[] {
  try {
    if (!cfg.enabled) return [];
    if (!text) return [];
    const enabled = new Set<RiskCategory>(
      cfg.categories?.length
        ? cfg.categories
        : (["stack_trace", "private_key", "secret_assignment", "k8s_secret", "db_migration", "legal"] as RiskCategory[])
    );
    const vcs = isLikelyVcsContext(text);

    const regexHits = collectRegexHits(text, enabled);
    const k8sHits = enabled.has("k8s_secret") ? detectK8sSecret(text) : [];

    // db_migration: require >=MIN_DDL hits; drop those inside a diff hunk.
    const ddl = regexHits.filter((h) => h.category === "db_migration" && !(vcs && inDiffHunk(text, h.start)));
    const ddlPromoted: RiskSpan[] =
      ddl.length >= MIN_DDL ? [{ start: ddl[0].start, end: ddl[ddl.length - 1].end, category: "db_migration" }] : [];

    // Guarded categories: secret_assignment, stack_trace, legal.
    const guarded = regexHits.filter(
      (h) => h.category === "secret_assignment" || h.category === "stack_trace" || h.category === "legal"
    );
    // private_key is the only regex-hit self-evident category; k8s_secret and
    // db_migration self-promote via their own structural paths below.
    const selfEvident = regexHits.filter((h) => h.category === "private_key");

    // Count corroborating signals (self-evident + promoted-ddl + k8s + guarded).
    const signalCount = selfEvident.length + (ddlPromoted.length ? 1 : 0) + k8sHits.length + guarded.length;
    const shortSection = !vcs && text.length < SHORT_SECTION;
    const guardedPromoted = signalCount >= 2 || shortSection ? guarded : [];

    const promoted: RiskSpan[] = [
      ...selfEvident.map((h) => ({ start: h.start, end: h.end, category: h.category })),
      ...k8sHits.map((h) => ({ start: h.start, end: h.end, category: h.category })),
      ...ddlPromoted,
      ...guardedPromoted.map((h) => ({ start: h.start, end: h.end, category: h.category })),
    ];

    return mergeSpans(promoted);
  } catch {
    return [];
  }
}

/**
 * Risk-gate pattern catalog. Every variable-length pattern uses bounded
 * quantifiers (`{0,N}`) to prevent catastrophic backtracking (ReDoS) on
 * untrusted input. Patterns are ours (not agent-supplied), so safe-regex is not
 * required — boundedness is verified by an adversarial-input test.
 */
export type RiskCategory =
  | "stack_trace"
  | "private_key"
  | "secret_assignment"
  | "k8s_secret"
  | "db_migration"
  | "legal";

export const MAX_PEM_LEN = 4096;

export interface RiskPattern {
  category: RiskCategory;
  regex: RegExp;
}

/**
 * Categories whose single match is strong enough evidence on its own (no
 * corroborating second signal / short-section required).
 * `k8s_secret` and `db_migration` are promoted structurally in riskGate.ts.
 */
export const SELF_EVIDENT: ReadonlySet<RiskCategory> = new Set<RiskCategory>([
  "private_key",
  "k8s_secret",
  "db_migration",
]);

export const RISK_PATTERNS: RiskPattern[] = [
  {
    category: "private_key",
    regex: new RegExp(
      `-----BEGIN [A-Z0-9 ]{0,40}PRIVATE KEY-----[\\s\\S]{1,${MAX_PEM_LEN}}?-----END [A-Z0-9 ]{0,40}PRIVATE KEY-----`,
      "g"
    ),
  },
  {
    category: "secret_assignment",
    regex:
      /\b(?:api[_-]?key|secret|token|password|passwd|bearer|authorization|client[_-]?secret)\b[ \t]{0,20}[:=][ \t]{0,20}["']?[A-Za-z0-9._\-+/]{8,200}/gi,
  },
  {
    category: "stack_trace",
    regex:
      /^\s{0,8}(?:at\s+\S.{0,300}|File ".{1,300}", line \d{1,9}|Traceback \(most recent call last\):|[A-Za-z_.]{1,80}(?:Error|Exception):.{0,300})$/gm,
  },
  {
    // Single DDL hit; the ">=2 DDL" promotion rule is enforced in riskGate.ts.
    category: "db_migration",
    regex: /\b(?:CREATE|ALTER|DROP)\s+(?:TABLE|INDEX|SCHEMA|DATABASE|COLUMN)\b/gi,
  },
  {
    category: "legal",
    regex:
      /\bWITHOUT WARRANTY\b|\bPermission is hereby granted\b|^SPDX-License-Identifier:.{0,200}$|\bCopyright \(c\)\b|\bAll rights reserved\b/gim,
  },
];

import type { CompressionConfig, CompressionResult } from "./types.ts";
import type { CachingDetectionContext } from "./cachingAware.ts";
import type { RiskGateConfig } from "./riskGate/riskGate.ts";
import { resolveRiskGate, withRiskGate } from "./riskGate/strategyWrap.ts";
import {
  resolveQuantumLock,
  quantumCachingContext,
  withQuantumLock,
  withQuantumLockAsync,
} from "./quantumLock/index.ts";

export interface CompressionEntrypointOptions {
  config?: CompressionConfig;
  riskGate?: RiskGateConfig;
  cachingContext?: CachingDetectionContext;
}

export function withCompressionEntrypointGuards<T extends CompressionEntrypointOptions>(
  body: Record<string, unknown>,
  options: T | undefined,
  run: (body: Record<string, unknown>) => CompressionResult
): CompressionResult {
  return withQuantumLock(
    body,
    resolveQuantumLock(options),
    quantumCachingContext(body, options),
    (quantumBody) =>
      withRiskGate(quantumBody, resolveRiskGate(options), (riskBody) => run(riskBody))
  );
}

export function withCompressionEntrypointGuardsAsync<T extends CompressionEntrypointOptions>(
  body: Record<string, unknown>,
  options: T | undefined,
  run: (body: Record<string, unknown>) => Promise<CompressionResult>
): Promise<CompressionResult> {
  return withQuantumLockAsync(
    body,
    resolveQuantumLock(options),
    quantumCachingContext(body, options),
    run
  );
}

export {
  QUANTUM_PATTERNS,
  TAIL_DELIM,
  placeholderFor,
  type QuantumCategory,
  type QuantumLockConfig,
  type QuantumLockStats,
  type VolatileSpan,
} from "./quantumPatterns.ts";
export { detectVolatileSpans } from "./quantumLock.ts";
export { applyQuantumLock } from "./quantumLockStep.ts";
export {
  resolveQuantumLock,
  quantumCachingContext,
  withQuantumLock,
  withQuantumLockAsync,
} from "./strategyWrap.ts";

/**
 * QuantumLock leaf module: category enum, span/config/stats types, constants, and the
 * fixed-order, ReDoS-bounded detection patterns. No imports — keeps every consumer one-way
 * (cycle-safe). See docs/superpowers/specs/2026-06-28-compression-quantumlock-design.md.
 */

export type QuantumCategory =
  | "uuid"
  | "unix_ts"
  | "long_hex"
  | "jwt"
  | "api_key_shape"
  | "request_id";

export interface VolatileSpan {
  start: number; // inclusive char offset into the system text
  end: number; // exclusive
  category: QuantumCategory;
}

export interface QuantumLockConfig {
  enabled: boolean;
  /** Subset of categories to stabilize. Absent/empty ⇒ all categories. */
  categories?: QuantumCategory[];
}

export interface QuantumLockStats {
  fragments: number;
  categories: Partial<Record<QuantumCategory, number>>;
}

/** Idempotency sentinel + tail header. Its presence in system text ⇒ already stabilized. */
export const TAIL_DELIM = "⟦QUANTUMLOCK⟧";

/** Positional, value-independent placeholder. Depends ONLY on match index. */
export const placeholderFor = (i: number): string => `⟦Q${i}⟧`;

interface QuantumPattern {
  category: QuantumCategory;
  pattern: RegExp;
}

/**
 * Detection order is FIXED: most-specific / widest first so a token is never split.
 * Every variable-length run is bounded ({N,M}) — no unbounded quantifier (anti-ReDoS).
 */
export const QUANTUM_PATTERNS: QuantumPattern[] = [
  // JWTs start with base64url of `{"` → "eyJ". Run first so the whole token wins.
  // Trailing negative-lookahead (not \b): a JWT signature can END in base64url `-`/`_`,
  // where \b would misfire (it needs a following word char) and let the token escape detection.
  {
    category: "jwt",
    pattern: /\beyJ[A-Za-z0-9_-]{8,512}\.[A-Za-z0-9_-]{8,512}\.[A-Za-z0-9_-]{8,512}(?![A-Za-z0-9_-])/g,
  },
  // Prefixed API keys (stripe/github/slack shapes).
  {
    category: "api_key_shape",
    pattern: /\b(?:sk|pk|rk|ghp|gho|xox[baprs])[-_][A-Za-z0-9]{16,200}\b/g,
  },
  // Bearer tokens. Bounded whitespace ([ \t]{1,4}) per the file convention (no unbounded \s+).
  {
    category: "api_key_shape",
    pattern: /\bBearer[ \t]{1,4}[A-Za-z0-9._-]{16,400}\b/g,
  },
  // Canonical UUID. Runs before long_hex so its inner hex is not re-claimed.
  {
    category: "uuid",
    pattern: /\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/gi,
  },
  // Correlation / request ids.
  {
    category: "request_id",
    pattern: /\b(?:req|trace|span|corr|request)[-_][A-Za-z0-9]{6,128}\b/gi,
  },
  // Digests / SHAs. After uuid/jwt so it never eats their inner hex.
  { category: "long_hex", pattern: /\b[0-9a-f]{16,128}\b/gi },
  // 10- or 13-digit unix epoch in the 2001–2033 window (leading 1). LAST so it never
  // fragments a longer token already claimed above.
  { category: "unix_ts", pattern: /\b1[0-9]{9}(?:[0-9]{3})?\b/g },
];

import {
  QUANTUM_PATTERNS,
  type QuantumLockConfig,
  type VolatileSpan,
} from "./quantumPatterns.ts";

interface PrioritizedSpan extends VolatileSpan {
  prio: number;
}

/**
 * Detect non-semantic volatile spans in `text`, in the FIXED pattern order, then merge
 * overlapping spans so a token is never double-replaced. Pure + fail-open: a throwing
 * pattern aborts the scan and returns [] (QuantumLock must never corrupt a request).
 *
 * Merge rule (widest wins): sort by start asc, then by width desc, then by priority asc
 * (earlier pattern = higher precedence); greedily keep a span only if it starts at/after
 * the last accepted span's end.
 */
export function detectVolatileSpans(text: string, cfg: QuantumLockConfig): VolatileSpan[] {
  if (!text) return [];
  const allow = cfg.categories && cfg.categories.length > 0 ? new Set(cfg.categories) : null;
  const raw: PrioritizedSpan[] = [];

  try {
    QUANTUM_PATTERNS.forEach(({ category, pattern }, prio) => {
      if (allow && !allow.has(category)) return;
      pattern.lastIndex = 0;
      let m: RegExpExecArray | null;
      while ((m = pattern.exec(text)) !== null) {
        if (m[0].length === 0) {
          pattern.lastIndex++;
          continue;
        }
        raw.push({ start: m.index, end: m.index + m[0].length, category, prio });
      }
    });
  } catch {
    return [];
  }

  raw.sort((a, b) => a.start - b.start || b.end - a.end || a.prio - b.prio);

  // Greedy non-overlapping sweep: accept a span only if it starts at/after the last accepted
  // span's end. A nested or PARTIALLY-overlapping span is dropped whole (never split) — this is
  // always SAFE (it can only under-stabilize, never corrupt text or shift placeholder numbering).
  // With the current `\b`-anchored patterns true partial overlaps are unreachable; the drop rule
  // is the conservative default if a future pattern can produce one.
  const merged: VolatileSpan[] = [];
  let lastEnd = -1;
  for (const s of raw) {
    if (s.start >= lastEnd) {
      merged.push({ start: s.start, end: s.end, category: s.category });
      lastEnd = s.end;
    }
  }
  return merged;
}

import { detectVolatileSpans } from "./quantumLock.ts";
import {
  placeholderFor,
  TAIL_DELIM,
  type QuantumCategory,
  type QuantumLockConfig,
  type QuantumLockStats,
} from "./quantumPatterns.ts";

/**
 * Fresh zero-stats per call. NOT a shared singleton on purpose: `applyQuantumLock` is a public
 * export and `categories` is mutable, so returning one shared object would let a stats-aggregating
 * caller corrupt the no-op result for every subsequent call in the process.
 */
const emptyStats = (): QuantumLockStats => ({ fragments: 0, categories: {} });

function isRecord(v: unknown): v is Record<string, unknown> {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

/** v1 stabilizes string-content system messages only. Array/multimodal ⇒ no-op (follow-up). */
function systemTextOf(msg: Record<string, unknown>): string {
  return typeof msg.content === "string" ? msg.content : "";
}

/**
 * Stabilize volatile fragments in the FIRST role:system message: replace each detected span
 * with a positional, value-independent placeholder (⟦Q{i}⟧) and append a delimited value-tail.
 * The rewritten body is sent to the model (lossless — the tail carries every value). Pure:
 * clones the touched message, never mutates input. Fail-open: returns the input body + zero
 * stats on every no-op path. `ctx` is accepted for symmetry with the wrapper; unused here.
 */
export function applyQuantumLock(
  body: Record<string, unknown>,
  cfg: QuantumLockConfig,
  _ctx?: { isCachingProvider: boolean }
): { body: Record<string, unknown>; stats: QuantumLockStats } {
  const messages = body.messages;
  if (!Array.isArray(messages)) return { body, stats: emptyStats() };

  const idx = messages.findIndex((m) => isRecord(m) && m.role === "system");
  if (idx === -1) return { body, stats: emptyStats() };

  const sys = messages[idx] as Record<string, unknown>;
  const text = systemTextOf(sys);
  if (!text) return { body, stats: emptyStats() };
  if (text.includes(TAIL_DELIM)) return { body, stats: emptyStats() }; // idempotency

  const spans = detectVolatileSpans(text, cfg);
  if (spans.length === 0) return { body, stats: emptyStats() };

  let out = "";
  let cursor = 0;
  const values: string[] = [];
  const categories: Partial<Record<QuantumCategory, number>> = {};
  spans.forEach((span, i) => {
    out += text.slice(cursor, span.start) + placeholderFor(i);
    values.push(text.slice(span.start, span.end));
    categories[span.category] = (categories[span.category] ?? 0) + 1;
    cursor = span.end;
  });
  out += text.slice(cursor);

  const tail = `\n\n${TAIL_DELIM}\n${values.map((v, i) => `${placeholderFor(i)}=${v}`).join("\n")}`;
  const newMessages = messages.slice();
  newMessages[idx] = { ...sys, content: out + tail };

  return {
    body: { ...body, messages: newMessages },
    stats: { fragments: values.length, categories },
  };
}

import { detectCachingContext, type CachingDetectionContext } from "../cachingAware.ts";
import type { CompressionConfig, CompressionResult, CompressionStats } from "../types.ts";
import { applyQuantumLock } from "./quantumLockStep.ts";
import type { QuantumLockConfig, QuantumLockStats } from "./quantumPatterns.ts";

/** The QuantumLock config to apply, or undefined when absent/disabled. */
export function resolveQuantumLock(options?: { config?: CompressionConfig }): QuantumLockConfig | undefined {
  const ql = options?.config?.quantumLock;
  return ql?.enabled ? ql : undefined;
}

/**
 * Resolve the caching gate. Production passes `options.model` (provider inferred from the
 * model slug) or an explicit `options.cachingContext`; the studio dry-run forces a caching
 * context so the operator can see what WOULD be stabilized.
 */
export function quantumCachingContext(
  body: Record<string, unknown>,
  options?: { model?: string; cachingContext?: CachingDetectionContext }
): { isCachingProvider: boolean } {
  const ctx = detectCachingContext(body, options?.cachingContext ?? { model: options?.model });
  return { isCachingProvider: ctx.isCachingProvider };
}

/** Attach QuantumLock stats to a result, creating a minimal stats carrier when needed. */
function attachQuantumLockStats(
  result: CompressionResult,
  qlStats: QuantumLockStats
): CompressionResult {
  if (result.stats) {
    result.stats.quantumLock = qlStats;
    return result;
  }
  // Downstream compression produced no stats (e.g. message too short to compress).
  // Create a passthrough carrier so the quantumLock field is not lost.
  const carrier: CompressionStats = {
    originalTokens: 0,
    compressedTokens: 0,
    savingsPercent: 0,
    techniquesUsed: ["quantum-lock"],
    mode: "off",
    timestamp: Date.now(),
    quantumLock: qlStats,
  };
  return { ...result, stats: carrier };
}

export function withQuantumLock(
  body: Record<string, unknown>,
  ql: QuantumLockConfig | undefined,
  ctx: { isCachingProvider: boolean },
  run: (b: Record<string, unknown>) => CompressionResult
): CompressionResult {
  if (!ql || !ctx.isCachingProvider) return run(body);
  const { body: locked, stats } = applyQuantumLock(body, ql, ctx);
  const result = run(locked);
  if (stats.fragments > 0) return attachQuantumLockStats(result, stats);
  return result;
}

export async function withQuantumLockAsync(
  body: Record<string, unknown>,
  ql: QuantumLockConfig | undefined,
  ctx: { isCachingProvider: boolean },
  run: (b: Record<string, unknown>) => Promise<CompressionResult>
): Promise<CompressionResult> {
  if (!ql || !ctx.isCachingProvider) return run(body);
  const { body: locked, stats } = applyQuantumLock(body, ql, ctx);
  const result = await run(locked);
  if (stats.fragments > 0) return attachQuantumLockStats(result, stats);
  return result;
}

import crypto from "node:crypto";
import type { CompressionConfig, CompressionMode, CompressionResult } from "./types.ts";

export const MEMO_CAP = 5_000;

const memoMap = new Map<string, CompressionResult>();

// Opt-IN whitelist (NOT opt-out): cache only engines proven pure + STATELESS across
// requests. Excluded on purpose: `ccr` and `session-dedup` write to the cross-request
// CCR store (`ccr/index.ts` ccrStore; session-dedup imports storeBlock), so their output
// depends on prior state → not safe to memoize; `ultra`/`aggressive`/`llmlingua` are
// model-backed/non-deterministic. Any NEW engine is excluded until explicitly vetted.
// "omniglyph" is intentionally excluded too (P2 registry-consistency pass): it renders
// context as an image via a model-backed pipeline, so it is not yet proven deterministic
// across requests — conservative default (never-wrong) until explicitly vetted.
const DETERMINISTIC_ENGINES = new Set(["lite", "caveman", "rtk"]);

/** Top-level modes safe to cache (whitelist — any unknown/new mode defaults to false).
 * "omniglyph" intentionally omitted — see comment on DETERMINISTIC_ENGINES above. */
const DETERMINISTIC_MODES = new Set<CompressionMode>(["lite", "standard", "rtk"]);

export function isDeterministicMode(mode: CompressionMode, config?: CompressionConfig): boolean {
  if (mode === "stacked") {
    const pipeline = config?.stackedPipeline;
    if (!pipeline || pipeline.length === 0) return false;
    return pipeline.every((step) => DETERMINISTIC_ENGINES.has(step.engine));
  }
  return DETERMINISTIC_MODES.has(mode);
}

function sha256hex(text: string): string {
  return crypto.createHash("sha256").update(text).digest("hex");
}

export function makeMemoKey(
  body: Record<string, unknown>,
  mode: CompressionMode,
  config: CompressionConfig,
  principalId?: string,
  model?: string,
  supportsVision?: boolean | null
): string {
  const bodyHash = sha256hex(JSON.stringify(body));

  // #8137: Only include model + supportsVision in the cache key when the compression
  // result actually depends on them. The `lite` engine strips data:image URLs only when
  // vision is unsupported (replaceImageUrls / modelSupportsVision), so the same (body,
  // config) yields a DIFFERENT result per target — omitting them would return a wrong
  // (image-stripped or image-kept) cached body across vision/non-vision targets.
  //
  // For all other deterministic engines (caveman, rtk), the output is model-independent.
  // Including model in the key defeats memoization across combo retries — the body is
  // identical but the model changes each attempt, producing a fresh cache miss every time
  // and re-running the full compression pipeline 5-8x per request.
  const isVisionDependent = usesVisionDependentEngine(mode, config);

  return sha256hex(
    JSON.stringify({
      bodyHash,
      mode,
      config,
      principalId: principalId ?? null,
      model: isVisionDependent ? (model ?? null) : null,
      supportsVision: isVisionDependent ? (supportsVision ?? null) : null,
    })
  );
}

/**
 * Whether the compression pipeline for this mode/config includes the `lite` engine,
 * whose output depends on the target's vision support (image-URL stripping).
 * Only `lite` itself, `standard` (lite → caveman), and `stacked` pipelines containing
 * a `lite` step are vision-dependent.
 */
function usesVisionDependentEngine(mode: CompressionMode, config?: CompressionConfig): boolean {
  if (mode === "lite") return true;
  if (mode === "standard") return true; // standard = lite → caveman pipeline
  if (mode === "stacked") {
    const pipeline = config?.stackedPipeline;
    if (!pipeline || pipeline.length === 0) return false;
    return pipeline.some((step) => step.engine === "lite");
  }
  return false;
}

function boundedSet(key: string, value: CompressionResult): void {
  if (!memoMap.has(key) && memoMap.size >= MEMO_CAP) {
    const firstKey = memoMap.keys().next().value;
    if (firstKey !== undefined) {
      memoMap.delete(firstKey);
    }
  }
  memoMap.set(key, value);
}

export function memoLookup(key: string): CompressionResult | null {
  const hit = memoMap.get(key);
  if (!hit) return null;
  // Return a clone so downstream mutation cannot corrupt the cached value.
  return JSON.parse(JSON.stringify(hit)) as CompressionResult;
}

export function memoStore(key: string, result: CompressionResult): void {
  // Clone on STORE too (memoLookup already clones on read). Storing the caller's live
  // object would let a later mutation of it (e.g. an async engine holding a sub-ref)
  // corrupt the cached entry. Both ends isolated ⇒ the cache is immutable once stored.
  boundedSet(key, JSON.parse(JSON.stringify(result)) as CompressionResult);
}

/** For tests only — clears the in-process memo store. */
export function clearMemoStore(): void {
  memoMap.clear();
}

import type { CompressionConfig } from "./types.ts";
import type { CachingDetectionContext } from "./cachingAware.ts";
import { detectCachingContext, getCacheAwareStrategy } from "./cachingAware.ts";
import {
  normalizePreserveSystemPromptMode,
  resolvePreserveSystemPrompt,
} from "./preserveSystemPromptMode.ts";
import {
  resolvePrefixFreezeConfig,
  extractStablePrefixHash,
  observePrefix,
  isPrefixFrozen,
} from "./prefixFreeze.ts";

/**
 * T08/H5 — augment the static cache signal with usage-observed prefix freeze. Opt-in
 * (default off): when a system prompt has recurred `>= threshold` times, treat it as a stable
 * cacheable prefix to preserve even for a provider the static check does not flag as caching.
 * "Freeze" only *preserves* the prefix, so it never corrupts a payload.
 */
function observeAndCheckPrefixFreeze(body: Record<string, unknown>): boolean {
  const cfg = resolvePrefixFreezeConfig();
  if (!cfg.enabled) return false;
  const hash = extractStablePrefixHash(body);
  if (!hash) return false;
  observePrefix(hash);
  return isPrefixFrozen(hash, cfg.threshold);
}

/**
 * #3890/#3955 + T05/C5: materialize the engine-facing `preserveSystemPrompt`
 * boolean from the authoritative `preserveSystemPromptMode` intent, using the
 * cache-aware `skipSystemPrompt` signal that `getCacheAwareStrategy` already
 * computes (a caching provider — or `cache_control` — means the system prompt is
 * part of the cacheable prefix, so compressing it breaks the upstream cache).
 *
 * This generalizes the previous hard-coded "force `true` when a cache is present
 * and the operator disabled preservation" into the three modes:
 * - `always`      → always `true`.
 * - `whenNoCache` → `true` only when a cache is present (the legacy `false`
 *   behaviour — preserved exactly for back-compat).
 * - `never`       → always `false`, even when it breaks a prompt cache.
 */
export function resolveCacheAwareConfig(
  config: CompressionConfig,
  body?: Record<string, unknown>,
  context?: CachingDetectionContext
): CompressionConfig {
  const mode = normalizePreserveSystemPromptMode(config);
  // No request body → no cacheable prefix to detect; honor the mode at its no-cache baseline.
  // The signal is the static caching heuristic OR (H5, opt-in) a usage-observed stable prefix.
  const staticCache = body
    ? getCacheAwareStrategy(config.defaultMode, detectCachingContext(body, context))
        .skipSystemPrompt
    : false;
  const hasCache = staticCache || (body ? observeAndCheckPrefixFreeze(body) : false);
  const effective = resolvePreserveSystemPrompt(mode, { hasCache });
  if (effective === config.preserveSystemPrompt) return config;
  return { ...config, preserveSystemPrompt: effective };
}

import type { CompressionConfig, PreserveSystemPromptMode } from "./types.ts";

/**
 * T05/C5 — system-prompt preservation mode.
 *
 * The engine-facing field is the boolean `CompressionConfig.preserveSystemPrompt`
 * (truthy = skip/preserve the system prompt). Its authoritative *intent* is the
 * `preserveSystemPromptMode` enum, resolved to that boolean at the cache-aware layer
 * (`resolveCacheAwareConfig`), which already runs upstream in `chatCore` with the
 * caching context. This module is the single source of the enum<->boolean mapping so
 * the legacy boolean and the new enum can never drift.
 *
 * Mode semantics:
 * - `always`      → preserve the system prompt unconditionally.
 * - `whenNoCache` → preserve it only when there is a cache to protect (provider caches
 *                   the prefix or `cache_control` is present); compress it otherwise.
 *                   This is exactly what the legacy `preserveSystemPrompt: false` already
 *                   did via the #3890/#3955 cache guard.
 * - `never`       → compress the system prompt even when it breaks a prompt cache.
 */
export const PRESERVE_SYSTEM_PROMPT_MODES: readonly PreserveSystemPromptMode[] = [
  "always",
  "whenNoCache",
  "never",
];

export function isPreserveSystemPromptMode(value: unknown): value is PreserveSystemPromptMode {
  return (
    typeof value === "string" &&
    (PRESERVE_SYSTEM_PROMPT_MODES as readonly string[]).includes(value)
  );
}

/**
 * Back-compat shim: derive the authoritative mode from a config. An explicit
 * `preserveSystemPromptMode` always wins; otherwise the legacy boolean is mapped
 * 1:1 to the behaviour it already had (`false → whenNoCache`, anything else → `always`).
 */
export function normalizePreserveSystemPromptMode(
  config: Pick<CompressionConfig, "preserveSystemPrompt" | "preserveSystemPromptMode">
): PreserveSystemPromptMode {
  if (isPreserveSystemPromptMode(config.preserveSystemPromptMode)) {
    return config.preserveSystemPromptMode;
  }
  return config.preserveSystemPrompt === false ? "whenNoCache" : "always";
}

/**
 * Resolve a mode to the effective engine-facing boolean given whether a cacheable
 * prefix is present. `true` = preserve (skip), `false` = compress the system prompt.
 */
export function resolvePreserveSystemPrompt(
  mode: PreserveSystemPromptMode,
  { hasCache }: { hasCache: boolean }
): boolean {
  switch (mode) {
    case "always":
      return true;
    case "never":
      return false;
    case "whenNoCache":
      return hasCache;
  }
}

/**
 * The no-cache projection of a mode — the stored/effective boolean used as a sane
 * default for any reader that runs before the cache-aware layer materializes it.
 */
export function modeToBaselineBoolean(mode: PreserveSystemPromptMode): boolean {
  return resolvePreserveSystemPrompt(mode, { hasCache: false });
}

/**
 * T08/H5 — usage-observed prefix freeze (gaps v3.8.42; opt-in, default OFF).
 *
 * Augments the static cache-aware heuristic (`getCacheAwareStrategy`). Instead of only freezing the
 * system prompt for providers the static check knows to cache, it OBSERVES which system prompts
 * actually recur across requests and, once one has been seen `>= threshold` times, treats it as a
 * stable cacheable prefix to preserve — even for a provider the static check does not recognize.
 *
 * Content-addressed by a hash of the system prompt (no principal needed): a "freeze" only
 * *preserves* the prefix from compression, which never corrupts a payload and is safe to share
 * across tenants. In-memory + bounded, zero DB/IO. Default OFF
 * (`COMPRESSION_PREFIX_FREEZE_ENABLED`); when off the observer is never consulted (zero cost).
 */

import crypto from "node:crypto";

export interface PrefixFreezeConfig {
  /** Master switch. Default false — the resolver never observes/consults when off. */
  enabled: boolean;
  /** Times a system prompt must be observed before it is treated as a frozen stable prefix. */
  threshold: number;
}

export const DEFAULT_PREFIX_FREEZE: PrefixFreezeConfig = { enabled: false, threshold: 3 };

/** Upper bound on tracked prefixes (oldest evicted first), mirroring the CCR store cap. */
export const MAX_PREFIX_ENTRIES = 5_000;

const observations = new Map<string, number>();

function boundedInc(hash: string): void {
  if (!observations.has(hash) && observations.size >= MAX_PREFIX_ENTRIES) {
    const oldest = observations.keys().next().value;
    if (oldest !== undefined) observations.delete(oldest);
  }
  observations.set(hash, (observations.get(hash) ?? 0) + 1);
}

function toPositiveInt(raw: string | undefined, fallback: number): number {
  if (raw === undefined) return fallback;
  const n = Number(raw);
  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : fallback;
}

/** Resolve config from env (`COMPRESSION_PREFIX_FREEZE_ENABLED` / `_THRESHOLD`). Opt-in. */
export function resolvePrefixFreezeConfig(
  env: NodeJS.ProcessEnv = process.env
): PrefixFreezeConfig {
  return {
    enabled: env.COMPRESSION_PREFIX_FREEZE_ENABLED === "true",
    threshold: toPositiveInt(
      env.COMPRESSION_PREFIX_FREEZE_THRESHOLD,
      DEFAULT_PREFIX_FREEZE.threshold
    ),
  };
}

// ─── prefix extraction ──────────────────────────────────────────────────────────

function isRecord(v: unknown): v is Record<string, unknown> {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

/**
 * Pull plain text out of the system-prompt shapes: `string`, `Array<…>`, `{text}` (OpenAI/Claude
 * text parts), and `{parts: [...]}` (Gemini `systemInstruction`).
 */
function collectText(value: unknown, out: string[]): void {
  if (typeof value === "string") {
    if (value.trim()) out.push(value);
    return;
  }
  if (Array.isArray(value)) {
    for (const item of value) collectText(item, out);
    return;
  }
  if (isRecord(value)) {
    if (typeof value.text === "string" && value.text.trim()) out.push(value.text);
    if (value.parts !== undefined) collectText(value.parts, out); // Gemini systemInstruction
  }
}

/**
 * Compute a stable 24-hex hash of the request's system prompt across the common body shapes
 * (OpenAI `messages[].role==="system"`, Claude `system`, Gemini `systemInstruction`). Returns
 * `null` when there is no system prompt to freeze.
 */
export function extractStablePrefixHash(body: unknown): string | null {
  if (!isRecord(body)) return null;
  const parts: string[] = [];
  collectText(body.system, parts);
  collectText(body.systemInstruction, parts);
  collectText(body.system_instruction, parts);
  const messages = body.messages;
  if (Array.isArray(messages)) {
    for (const msg of messages) {
      if (isRecord(msg) && msg.role === "system") collectText(msg.content, parts);
    }
  }
  if (parts.length === 0) return null;
  return crypto.createHash("sha256").update(parts.join("\n")).digest("hex").slice(0, 24);
}

// ─── observation + query ──────────────────────────────────────────────────────────

/** Record one observation of a system-prompt hash (call once per request when enabled). */
export function observePrefix(hash: string): void {
  boundedInc(hash);
}

/** True once a prefix has been observed `>= threshold` times (a stable, freezable prefix). */
export function isPrefixFrozen(hash: string, threshold: number): boolean {
  return (observations.get(hash) ?? 0) >= threshold;
}

/** Current observation count for a prefix hash (telemetry/tests). */
export function getPrefixObservations(hash: string): number {
  return observations.get(hash) ?? 0;
}

/** Clear all observations (tests + operator reset). */
export function resetPrefixFreeze(): void {
  observations.clear();
}
